		const path = require("node:path");
		const pkgPath = path.resolve(
			new URL(".", import.meta.url).pathname,
			"../../../../package.json",
		);
		const pkg = JSON.parse(fs.readFileSync(pkgPath, "utf-8"));
		return pkg.version || "0.0.0";
	} catch {
		return "0.0.0";
	}
}

