	completedAt?: number;
}

/** Workspace entry as it appears in plan-state.json */
export interface WorkspaceJson {
	workspaceId: string;
	stage: string;
	attempts: number;
	startedAt?: number;
	completedAt?: number;
	ownedFiles?: string[];
	error?: string | null;
}

export interface WorkerInfo {
	id: string;
	stage: "pending" | "active" | "blocked" | "complete" | "failed";
	attempt: number;
