 * P11.A — Platform Capability Manifest Validation
 *
 * Validates capability manifests for structural correctness,
 * referential integrity, and contract compliance.
 *
 * @packageDocumentation
 */

import {
	PLATFORM_CONTRACT_VERSION,
	PLATFORM_PERMISSIONS,
	type ManifestValidationError,
	type ManifestValidationResult,
	type PlatformAuditAction,
	type PlatformAuditPolicy,
	type PlatformCapabilityManifest,
	type PlatformCompatibility,
	type PlatformHook,
	type PlatformPermissionDescriptor,
} from "./types.js";

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------

/** Valid lifecycle identifiers. */
const VALID_LIFECYCLES = new Set<string>(["init", "execute", "error", "shutdown"]);

/** Valid hook triggers. */
const VALID_TRIGGERS = new Set<string>(["before", "after", "on"]);

/** Valid audit actions. */
const VALID_AUDIT_ACTIONS = new Set<string>([
	"capability.enable",
	"capability.disable",
	"capability.change",
	"permission.grant",
	"permission.revoke",
	"hook.register",
	"hook.unregister",
	"manifest.create",
	"manifest.update",
	"manifest.delete",
]);

/** Semver regex. */
const SEMVER_RE = /^\d+\.\d+\.\d+$/;

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function isValidSemver(v: string): boolean {
	return SEMVER_RE.test(v);
}

function compareSemver(a: string, b: string): number {
	const pa = a.split(".").map(Number);
	const pb = b.split(".").map(Number);
	for (let i = 0; i < 3; i++) {
		const diff = (pa[i] ?? 0) - (pb[i] ?? 0);
		if (diff !== 0) return diff;
	}
	return 0;
}

