/**
 * Type of scale mode.
 * - `"stable"`: 1-3 workers, no prerequisites required.
 * - `"scale"`: 4-6 workers, all prerequisites must be met.
 */
export type ScaleModeType = "stable" | "scale";

/**
 * Status of a single prerequisite for enabling scale mode.
 */
