 * @param now - Current timestamp (epoch ms)
 * @param halfLifeMs - Freshness half-life in ms
 * @param accessBoost - Freshness boost per access
 * @returns Freshness score (0-1)
 */
export function computeFreshness(
	createdAt: number,
	lastAccessedAt: number | undefined,
	accessCount: number,
	now: number,
	halfLifeMs: number,
	accessBoost: number,
): number {
	const age = Math.max(0, now - createdAt);
	const decayFactor = Math.exp((-Math.LN2 * age) / halfLifeMs);
	const baseFreshness = decayFactor;

	// Boost from accesses
	const accessBonus = Math.min(accessCount * accessBoost, 1 - baseFreshness);
	const freshness = Math.min(1, baseFreshness + accessBonus);

	return Math.max(0, freshness);
}

	private buildResult(matched: ForbiddenPattern[]): ForbiddenCheckResult {
		if (matched.length === 0) {
			return { blocked: false, hard: false, matchedPatterns: [] };
		}

		const hardMatched = matched.filter((m) => m.hard);
		const blocked = hardMatched.length > 0;
		const hard = hardMatched.length > 0;

		// Determine the highest severity
		const severityOrder = { forbidden: 3, unsafe: 2, caution: 1 };
		let highestSeverity: "forbidden" | "unsafe" | "caution" = "caution";
		for (const m of matched) {
			if (m.severity === "forbidden") {
				highestSeverity = "forbidden";
				break;
			}
			if (m.severity === "unsafe") highestSeverity = "unsafe";
		}

		const reasons = matched.map((m) => m.reason);
