 */
export const SCAN_TYPE_LABELS: Record<ScanType, string> = {
	repo_health: "Repository Health",
	run_history: "Run History",
	queue: "Queue",
	dashboard_metrics: "Dashboard Metrics",
	proposal_refresh: "Proposal Refresh",
};

