 */
export const ORCHESTRATOR_STATE_LABELS: Record<OrchestratorState, string> = {
	stopped: "Stopped",
	starting: "Starting",
	running: "Running",
	pausing: "Pausing",
	paused: "Paused",
	stopping: "Stopping",
	failed: "Failed",
};

// ---------------------------------------------------------------------------
// Orchestrator Status
// ---------------------------------------------------------------------------

/**
