rder   Reorder queued plans\n *   POST   /api/projects/:projectId/queue/:entryId/skip    Skip a queued plan\n *   DELETE /api/projects/:projectId/queue/:entryId  Remove a queued plan\n *   POST   /api/projects/:projectId/queue/:entryId/move-to-top  Move entry to top\n *   POST   /api/projects/:projectId/queue/run-next   Run next queued plan\n *   POST   /api/projects/:projectId/queue/pause      Pause queue processing\n *   POST   /api/projects/:projectId/queue/resume     Resume queue processing\n *   POST   /api/projects/:projectId/queue/stop-after-current  Stop after current plan\n */\n\nimport { execSync } from \"node:child_process\";\nimport { randomUUID } from \"node:crypto\";\nimport { existsSync } from \"node:fs\";\nimport * as fs from \"node:fs/promises\";\nimport { readdir, readFile, watch, writeFile } from \"node:fs/promises\";\nimport { join, resolve } from \"node:path\";\nimport { getModels, getProviders } from \"@earendil-works/pi-ai\";\nimport {\n\tcreateSafetyDoctor,\n\tdetectStateStoreBackend,\n\tJsonStateStore,\n\tparsePlan,\n} from \"@earendil-works/pi-coding-agent\";\nimport fastifyCors from \"@fastify/cors\";\nimport fastifyStatic from \"@fastify/static\";\nimport fastifyWebsocket from \"@fastify/websocket\";\nimport Fastify from \"fastify\";\nimport { registerArtifactRoutes } from \"./artifact-routes.js\";\nimport { registerLogStreamRoutes } from \"./log-stream-routes.js\";\nimport { registerPerformanceRoutes } from \"./performance-routes.js\";\nimport {\n\tapplyDependencyPatches,\n\tcomputeBatchPlan,\n\ttype DependencyPatch,\n\tgenerateSuggestedFixes,\n\trequiresInteractiveApproval,\n} from \"./plan-preview.js\";\nimport {\n\tgetActiveExecution,\n\tgetActiveExecutions,\n\tloadExecutionMeta,\n\tresumeStrandedExecutions,\n\trunPlan,\n\tsignalExecutionEvent,\n} from \"./plan-runner.js\";\nimport { registerProposalRoutes } from \"./proposal-routes.js\";\nimport { registerScaleRoutes } from \"./scale-routes.js\";\nimport { getSettingsManager, getStateStore, getWorkspaceRoot } from \"./state-store-provider.js\";\n\n// ── helpers for enriching workspace data ────────────────────────────────────\n\n\n[3479 more lines in file. Use offset=81 to continue.]"}],"isError":false,"timestamp":1778942332825}}
{"type":"message","id":"cd1ddbf0","parentId":"0f04af61","timestamp":"2026-05-16T14:38:56.934Z","message":{"role":"toolResult","toolCallId":"call_00_6G2pvNnOdJIo9hImf98x7437","toolName":"read","content":[{"type":"text","text":"/**\n * Remediation Runtime - P9.A Approval-Gated Remediation Runtime\n *\n * A state machine that manages the lifecycle of applying remediation proposals\n * from the repo health scanner, with two separate approval gates:\n *\n *   1. Planning approval — Approve the remediation plan before dry-run\n *   2. Execution approval — Approve actual execution after dry-run\n *\n * The runtime enforces that execution cannot proceed without a completed\n * dry-run and explicit execution approval.\n *\n * State machine:\n *\n *   Idle\n *    │\n *    ├──[plan]──> Scanning ──> ScanComplete\n *    │                           │\n *    │                    ┌──────┴──────┐\n *    │                    │ (auto)      │\n *    │                    v              v\n *    │            PlanningApproval   PlanningRejected\n *    │            Pending\n *    │              │\n *    │        ┌─────┴──────┐\n *    │        │            │\n *    │        v            v\n *    │   Planning      Planning\n *    │   Approved      Rejected\n *    │      │\n *    │      ├──[requestDryRun]──> DryRunPending\n *    │      │                        │\n *    │      │                   ┌────┴────┐\n *    │      │                   │ (auto)  │\n *    │      │                   v         v\n *    │      │              DryRunning   Failed\n *    │      │                   │\n *    │      │                   v\n *    │      │              DryRunComplete\n *    │      │                   │\n *    │      ├──[execute]──> ExecutionApprovalPending\n *    │      │                   │\n *    │      │              ┌────┴─────────┐\n *    │      │              │              │\n *    │      │              v              v\n *    │      │         Execution       Execution\n *    │      │         Approved        Rejected\n *    │      │              │\n *    │      │              v\n *    │      ├─────────> Executing ──> Complete\n *    │      │\n *    │      v\n *    │   Failed\n *    │\n *    └──[reset]──> Idle\n *\n * Key invariants:\n * - planning_approval_pending → planning_approved (Gate 1)\n * - dry_run_complete → execution_approved (Gate 2)\n * - Dry-run MUST complete before execution approval is possible\n * - Cannot execute without execution_approved + dry_run_complete\n */\n\nimport type { HealthSignal, SignalProposal } from \"../repo-scanner/repo-health-signal.js\";\nimport type { BudgetSummary } from \"./budget-enforcer.js\";\n\n// ---------------------------------------------------------------------------\n// Remediation Runtime States\n// ---------------------------------------------------------------------------\n\n/**\n * All possible states of the remediation runtime.\n */\nexport type RemediationState =\n\t| \"idle\"\n\t| \"scanning\"\n\t| \"scan_complete\"\n\t| \"planning_approval_pending\"\n\t| \"planning_approved\"\n\t| \"planning_rejected\"\n\t| \"dry_run_pending\"\n\t| \"dry_running\"\n\t| \"dry_run_complete\"\n\t| \"execution_approval_pending\"\n\t| \"execution_approved\"\n\t| \"execution_rejected\"\n\t| \"executing\"\n\t| \"complete\"\n\t| \"failed\";\n\n/**\n * Human-readable label for each state.\n */\nexport const REMEDIATION_STATE_LABELS: Record<RemediationState, string> = {\n\tidle: \"Idle\",\n\tscanning: \"Scanning repository\",\n\tscan_complete: \"Scan complete\",\n\tplanning_approval_pending: \"Awaiting planning approval\",\n\tplanning_approved: \"Planning approved\",\n\tplanning_rejected: \"Planning rejected\",\n\n[1286 more lines in file. Use offset=101 to continue.]"}],"isError":false,"timestamp":1778942336934}}
