import { existsSync, readdirSync, readFileSync, statSync } from "fs";
import ignore from "ignore";
import { homedir } from "os";
import { basename, dirname, isAbsolute, join, relative, resolve, sep } from "path";
import { CONFIG_DIR_NAME, getAgentDir } from "../config.js";
import { parseFrontmatter } from "../utils/frontmatter.js";
import { canonicalizePath } from "../utils/paths.js";
import type { ResourceDiagnostic } from "./diagnostics.js";
import { createSyntheticSourceInfo, type SourceInfo } from "./source-info.js";

/** Max name length per spec */
const MAX_NAME_LENGTH = 64;

/** Max description length per spec */
const MAX_DESCRIPTION_LENGTH = 1024;

const IGNORE_FILE_NAMES = [".gitignore", ".ignore", ".fdignore"];

type IgnoreMatcher = ReturnType<typeof ignore>;

function toPosixPath(p: string): string {
	return p.split(sep).join("/");
}

function prefixIgnorePattern(line: string, prefix: string): string | null {
	const trimmed = line.trim();
	if (!trimmed) return null;
	if (trimmed.startsWith("#") && !trimmed.startsWith("\\#")) return null;

	let pattern = line;
	let negated = false;

	if (pattern.startsWith("!")) {
		negated = true;
		pattern = pattern.slice(1);
	} else if (pattern.startsWith("\\!")) {
		pattern = pattern.slice(1);
	}

	if (pattern.startsWith("/")) {
		pattern = pattern.slice(1);
	}

	const prefixed = prefix ? `${prefix}${pattern}` : pattern;
	return negated ? `!${prefixed}` : prefixed;
}

function addIgnoreRules(ig: IgnoreMatcher, dir: string, rootDir: string): void {
	const relativeDir = relative(rootDir, dir);
	const prefix = relativeDir ? `${toPosixPath(relativeDir)}/` : "";

	for (const filename of IGNORE_FILE_NAMES) {
		const ignorePath = join(dir, filename);
		if (!existsSync(ignorePath)) continue;
		try {
			const content = readFileSync(ignorePath, "utf-8");
			const patterns = content
				.split(/\r?\n/)
				.map((line) => prefixIgnorePattern(line, prefix))
				.filter((line): line is string => Boolean(line));
			if (patterns.length > 0) {
				ig.add(patterns);
			}
		} catch {}
	}
}

export interface SkillFrontmatter {
	name?: string;
	description?: string;
	"disable-model-invocation"?: boolean;
	[key: string]: unknown;
}

export interface Skill {
	name: string;
	description: string;
	filePath: string;
	baseDir: string;
	sourceInfo: SourceInfo;
	disableModelInvocation: boolean;
}

export interface LoadSkillsResult {
	skills: Skill[];
	diagnostics: ResourceDiagnostic[];
}

/**
 * Validate skill name per Agent Skills spec.
 * Returns array of validation error messages (empty if valid).
 */
function validateName(name: string, parentDirName: string): string[] {
	const errors: string[] = [];

	if (name !== parentDirName) {
		errors.push(`name "${name}" does not match parent directory "${parentDirName}"`);
	}

	if (name.length > MAX_NAME_LENGTH) {
		errors.push(`name exceeds ${MAX_NAME_LENGTH} characters (${name.length})`);
	}

	if (!/^[a-z0-9-]+$/.test(name)) {
		errors.push(`name contains invalid characters (must be lowercase a-z, 0-9, hyphens only)`);
	}

	if (name.startsWith("-") || name.endsWith("-")) {
		errors.push(`name must not start or end with a hyphen`);
	}

	if (name.includes("--")) {
		errors.push(`name must not contain consecutive hyphens`);
	}

	return errors;
}

/**
 * Validate description per Agent Skills spec.
 */
function validateDescription(description: string | undefined): string[] {
	const errors: string[] = [];

	if (!description || description.trim() === "") {
		errors.push("description is required");
	} else if (description.length > MAX_DESCRIPTION_LENGTH) {
		errors.push(`description exceeds ${MAX_DESCRIPTION_LENGTH} characters (${description.length})`);
	}

	return errors;
}

export interface LoadSkillsFromDirOptions {
	/** Directory to scan for skills */
	dir: string;
	/** Source identifier for these skills */
	source: string;
}

function createSkillSourceInfo(filePath: string, baseDir: string, source: string): SourceInfo {
	switch (source) {
		case "user":
			return createSyntheticSourceInfo(filePath, {
				source: "local",
				scope: "user",
				baseDir,
			});
		case "project":
			return createSyntheticSourceInfo(filePath, {
				source: "local",
				scope: "project",
				baseDir,
			});
		case "path":
			return createSyntheticSourceInfo(filePath, {
				source: "local",
				baseDir,
			});
		default:
			return createSyntheticSourceInfo(filePath, { source, baseDir });
	}
}

/**
 * Load skills from a directory.
 *
 * Discovery rules:
 * - if a directory contains SKILL.md, treat it as a skill root and do not recurse further
 * - otherwise, load direct .md children in the root
 * - recurse into subdirectories to find SKILL.md
 */
export function loadSkillsFromDir(options: LoadSkillsFromDirOptions): LoadSkillsResult {
	const { dir, source } = options;
	return loadSkillsFromDirInternal(dir, source, true);
}

function loadSkillsFromDirInternal(
	dir: string,
	source: string,
	includeRootFiles: boolean,
	ignoreMatcher?: IgnoreMatcher,
	rootDir?: string,
): LoadSkillsResult {
	const skills: Skill[] = [];
	const diagnostics: ResourceDiagnostic[] = [];

	if (!existsSync(dir)) {
		return { skills, diagnostics };
	}

	const root = rootDir ?? dir;
	const ig = ignoreMatcher ?? ignore();
	addIgnoreRules(ig, dir, root);

	try {
		const entries = readdirSync(dir, { withFileTypes: true });

		for (const entry of entries) {
			if (entry.name !== "SKILL.md") {
				continue;
			}

			const fullPath = join(dir, entry.name);

			let isFile = entry.isFile();
			if (entry.isSymbolicLink()) {
				try {
					isFile = statSync(fullPath).isFile();
				} catch {
					continue;
				}
			}

			const relPath = toPosixPath(relative(root, fullPath));
			if (!isFile || ig.ignores(relPath)) {
				continue;
			}

			const result = loadSkillFromFile(fullPath, source);
			if (result.skill) {
				skills.push(result.skill);
			}
			diagnostics.push(...result.diagnostics);
			return { skills, diagnostics };
		}

		for (const entry of entries) {
			if (entry.name.startsWith(".")) {
				continue;
			}

			// Skip node_modules to avoid scanning dependencies
			if (entry.name === "node_modules") {
				continue;
			}

			const fullPath = join(dir, entry.name);

			// For symlinks, check if they point to a directory and follow them
			let isDirectory = entry.isDirectory();
			let isFile = entry.isFile();
			if (entry.isSymbolicLink()) {
				try {
					const stats = statSync(fullPath);
					isDirectory = stats.isDirectory();
					isFile = stats.isFile();
				} catch {
					// Broken symlink, skip it
					continue;
				}
			}

			const relPath = toPosixPath(relative(root, fullPath));
			const ignorePath = isDirectory ? `${relPath}/` : relPath;
			if (ig.ignores(ignorePath)) {
				continue;
			}

			if (isDirectory) {
				const subResult = loadSkillsFromDirInternal(fullPath, source, false, ig, root);
				skills.push(...subResult.skills);
				diagnostics.push(...subResult.diagnostics);
				continue;
			}

			if (!isFile || !includeRootFiles || !entry.name.endsWith(".md")) {
				continue;
			}

			const result = loadSkillFromFile(fullPath, source);
			if (result.skill) {
				skills.push(result.skill);
			}
			diagnostics.push(...result.diagnostics);
		}
	} catch {}

	return { skills, diagnostics };
}

function loadSkillFromFile(
	filePath: string,
	source: string,
): { skill: Skill | null; diagnostics: ResourceDiagnostic[] } {
	const diagnostics: ResourceDiagnostic[] = [];

	try {
		const rawContent = readFileSync(filePath, "utf-8");
		const { frontmatter } = parseFrontmatter<SkillFrontmatter>(rawContent);
		const skillDir = dirname(filePath);
		const parentDirName = basename(skillDir);

		// Validate description
		const descErrors = validateDescription(frontmatter.description);
		for (const error of descErrors) {
			diagnostics.push({ type: "warning", message: error, path: filePath });
		}

		// Use name from frontmatter, or fall back to parent directory name
		const name = frontmatter.name || parentDirName;

		// Validate name
		const nameErrors = validateName(name, parentDirName);
		for (const error of nameErrors) {
			diagnostics.push({ type: "warning", message: error, path: filePath });
		}

		// Still load the skill even with warnings (unless description is completely missing)
		if (!frontmatter.description || frontmatter.description.trim() === "") {
			return { skill: null, diagnostics };
		}

		return {
			skill: {
				name,
				description: frontmatter.description,
				filePath,
				baseDir: skillDir,
				sourceInfo: createSkillSourceInfo(filePath, skillDir, source),
				disableModelInvocation: frontmatter["disable-model-invocation"] === true,
			},
			diagnostics,
		};
	} catch (error) {
		const message = error instanceof Error ? error.message : "failed to parse skill file";
		diagnostics.push({ type: "warning", message, path: filePath });
		return { skill: null, diagnostics };
	}
}

/**
 * Format skills for inclusion in a system prompt.
 * Uses XML format per Agent Skills standard.
 * See: https://agentskills.io/integrate-skills
 *
 * Skills with disableModelInvocation=true are excluded from the prompt
 * (they can only be invoked explicitly via /skill:name commands).
 */
export function formatSkillsForPrompt(skills: Skill[]): string {
	const visibleSkills = skills.filter((s) => !s.disableModelInvocation);

	if (visibleSkills.length === 0) {
		return "";
	}

	const lines = [
		"\n\nThe following skills provide specialized instructions for specific tasks.",
		"Use the read tool to load a skill's file when the task matches its description.",
		"When a skill file references a relative path, resolve it against the skill directory (parent of SKILL.md / dirname of the path) and use that absolute path in tool commands.",
		"",
		"<available_skills>",
	];

	for (const skill of visibleSkills) {
		lines.push("  <skill>");
		lines.push(`    <name>${escapeXml(skill.name)}</name>`);
		lines.push(`    <description>${escapeXml(skill.description)}</description>`);
		lines.push(`    <location>${escapeXml(skill.filePath)}</location>`);
		lines.push("  </skill>");
	}

	lines.push("</available_skills>");

	return lines.join("\n");
}

function escapeXml(str: string): string {
	return str
		.replace(/&/g, "&amp;")
		.replace(/</g, "&lt;")
		.replace(/>/g, "&gt;")
		.replace(/"/g, "&quot;")
		.replace(/'/g, "&apos;");
}

export interface LoadSkillsOptions {
	/** Working directory for project-local skills. */
	cwd: string;
	/** Agent config directory for global skills. */
	agentDir: string;
	/** Explicit skill paths (files or directories) */
	skillPaths: string[];
	/** Include default skills directories. */
	includeDefaults: boolean;
}

function normalizePath(input: string): string {
	const trimmed = input.trim();
	if (trimmed === "~") return homedir();
	if (trimmed.startsWith("~/")) return join(homedir(), trimmed.slice(2));
	if (trimmed.startsWith("~")) return join(homedir(), trimmed.slice(1));
	return trimmed;
}

function resolveSkillPath(p: string, cwd: string): string {
	const normalized = normalizePath(p);
	return isAbsolute(normalized) ? normalized : resolve(cwd, normalized);
}

/**
 * Load skills from all configured locations.
 * Returns skills and any validation diagnostics.
 */
export function loadSkills(options: LoadSkillsOptions): LoadSkillsResult {
	const { cwd, agentDir, skillPaths, includeDefaults } = options;

	// Resolve agentDir - if not provided, use default from config
	const resolvedAgentDir = agentDir ?? getAgentDir();

	const skillMap = new Map<string, Skill>();
	const realPathSet = new Set<string>();
	const allDiagnostics: ResourceDiagnostic[] = [];
	const collisionDiagnostics: ResourceDiagnostic[] = [];

	function addSkills(result: LoadSkillsResult) {
		allDiagnostics.push(...result.diagnostics);
		for (const skill of result.skills) {
			// Resolve symlinks to detect duplicate files
			const realPath = canonicalizePath(skill.filePath);

			// Skip silently if we've already loaded this exact file (via symlink)
			if (realPathSet.has(realPath)) {
				continue;
			}

			const existing = skillMap.get(skill.name);
			if (existing) {
				collisionDiagnostics.push({
					type: "collision",
					message: `name "${skill.name}" collision`,
					path: skill.filePath,
					collision: {
						resourceType: "skill",
						name: skill.name,
						winnerPath: existing.filePath,
						loserPath: skill.filePath,
					},
				});
			} else {
				skillMap.set(skill.name, skill);
				realPathSet.add(realPath);
			}
		}
	}

	if (includeDefaults) {
		addSkills(loadSkillsFromDirInternal(join(resolvedAgentDir, "skills"), "user", true));
		addSkills(loadSkillsFromDirInternal(resolve(cwd, CONFIG_DIR_NAME, "skills"), "project", true));
	}

	const userSkillsDir = join(resolvedAgentDir, "skills");
	const projectSkillsDir = resolve(cwd, CONFIG_DIR_NAME, "skills");

	const isUnderPath = (target: string, root: string): boolean => {
		const normalizedRoot = resolve(root);
		if (target === normalizedRoot) {
			return true;
		}
		const prefix = normalizedRoot.endsWith(sep) ? normalizedRoot : `${normalizedRoot}${sep}`;
		return target.startsWith(prefix);
	};

	const getSource = (resolvedPath: string): "user" | "project" | "path" => {
		if (!includeDefaults) {
			if (isUnderPath(resolvedPath, userSkillsDir)) return "user";
			if (isUnderPath(resolvedPath, projectSkillsDir)) return "project";
		}
		return "path";
	};

	for (const rawPath of skillPaths) {
		const resolvedPath = resolveSkillPath(rawPath, cwd);
		if (!existsSync(resolvedPath)) {
			allDiagnostics.push({ type: "warning", message: "skill path does not exist", path: resolvedPath });
			continue;
		}

		try {
			const stats = statSync(resolvedPath);
			const source = getSource(resolvedPath);
			if (stats.isDirectory()) {
				addSkills(loadSkillsFromDirInternal(resolvedPath, source, true));
			} else if (stats.isFile() && resolvedPath.endsWith(".md")) {
				const result = loadSkillFromFile(resolvedPath, source);
				if (result.skill) {
					addSkills({ skills: [result.skill], diagnostics: result.diagnostics });
				} else {
					allDiagnostics.push(...result.diagnostics);
				}
			} else {
				allDiagnostics.push({ type: "warning", message: "skill path is not a markdown file", path: resolvedPath });
			}
		} catch (error) {
			const message = error instanceof Error ? error.message : "failed to read skill path";
			allDiagnostics.push({ type: "warning", message, path: resolvedPath });
		}
	}

	return {
		skills: Array.from(skillMap.values()),
		diagnostics: [...allDiagnostics, ...collisionDiagnostics],
	};
}

/**
 * Local Skill Manifest Format - P2 Workstream 5.D
 *
 * Defines the schema for a local skill manifest (skill-manifest.json),
 * which enumerates skills available in a project or workspace and
 * specifies which skills are required for operation.
 */

/**
 * A single skill entry in the manifest.
 */
export interface SkillManifestEntry {
	/** Skill name (must match the skill directory name / frontmatter name) */
	name: string;
	/** Short human-readable description */
	description?: string;
	/** Whether this skill is required for doctor validation */
	required?: boolean;
	/** Skill source type */
	source: SkillSource;
	/** Remote URL (only used when source is "remote") */
	url?: string;
	/** Version constraint (semver string, optional) */
	version?: string;
}

/**
 * Skill source type.
 * - "local": skill is discovered from local filesystem
 * - "builtin": skill is bundled with the agent
 * - "remote": skill is fetched from a remote registry (disabled by default)
 */
export type SkillSource = "local" | "builtin" | "remote";

/**
 * Local skill manifest format.
 *
 * Place a `skill-manifest.json` in the project's config directory
 * (e.g., `.pi/skill-manifest.json`) to declare expected skills.
 */
export interface SkillManifest {
	/** Manifest format version */
	version: 1;
	/** List of skill entries */
	skills: SkillManifestEntry[];
	/** Whether remote skill fetching is enabled (default: false) */
	remoteFetchEnabled?: boolean;
	/** Optional project name */
	projectName?: string;
}

/**
 * Manifest validation error.
 */
export interface ManifestValidationError {
	/** Error type */
	type: "missing_field" | "invalid_field" | "invalid_version" | "remote_not_enabled" | "duplicate_skill";
	/** Human-readable message */
	message: string;
	/** Skill name (if applicable) */
	skillName?: string;
	/** Field path (if applicable) */
	field?: string;
}

/**
 * Manifest validation result.
 */
export interface ManifestValidationResult {
	/** Whether the manifest is valid */
	valid: boolean;
	/** Validation errors */
	errors: ManifestValidationError[];
	/** Validation warnings */
	warnings: ManifestValidationError[];
}

/**
 * Validate a skill manifest.
 *
 * Checks:
 * - Required fields (version, skills)
 * - Version must be 1
 * - Each skill entry must have name and source
 * - No duplicate skill names
 * - Remote skills require remoteFetchEnabled
 * - Name format validation (lowercase, hyphens, digits)
 *
 * @param manifest - Manifest to validate
 * @returns Validation result
 */
export function validateSkillManifest(manifest: Partial<SkillManifest>): ManifestValidationResult {
	const errors: ManifestValidationError[] = [];
	const warnings: ManifestValidationError[] = [];

	if (manifest.version === undefined) {
		errors.push({ type: "missing_field", message: "Manifest version is required", field: "version" });
	} else if (manifest.version !== 1) {
		errors.push({
			type: "invalid_version",
			message: `Manifest version must be 1, got ${manifest.version}`,
			field: "version",
		});
	}

	if (!manifest.skills) {
		errors.push({ type: "missing_field", message: "Manifest skills array is required", field: "skills" });
	} else {
		const seenNames = new Set<string>();
		for (const [index, skill] of manifest.skills.entries()) {
			if (!skill.name) {
				errors.push({
					type: "missing_field",
					message: `Skill at index ${index} is missing name`,
					field: `skills[${index}].name`,
				});
				continue;
			}

			if (seenNames.has(skill.name)) {
				errors.push({
					type: "duplicate_skill",
					message: `Duplicate skill name: "${skill.name}"`,
					skillName: skill.name,
				});
			}
			seenNames.add(skill.name);

			if (!/^[a-z0-9-]+$/.test(skill.name)) {
				errors.push({
					type: "invalid_field",
					message: `Skill name "${skill.name}" contains invalid characters (must be lowercase a-z, 0-9, hyphens only)`,
					skillName: skill.name,
					field: `skills[${index}].name`,
				});
			}

			if (skill.name.startsWith("-") || skill.name.endsWith("-")) {
				errors.push({
					type: "invalid_field",
					message: `Skill name "${skill.name}" must not start or end with a hyphen`,
					skillName: skill.name,
					field: `skills[${index}].name`,
				});
			}

			if (skill.name.includes("--")) {
				errors.push({
					type: "invalid_field",
					message: `Skill name "${skill.name}" must not contain consecutive hyphens`,
					skillName: skill.name,
					field: `skills[${index}].name`,
				});
			}

			if (skill.name.length > 64) {
				errors.push({
					type: "invalid_field",
					message: `Skill name "${skill.name}" exceeds 64 characters`,
					skillName: skill.name,
					field: `skills[${index}].name`,
				});
			}

			if (!skill.source) {
				errors.push({
					type: "missing_field",
					message: `Skill "${skill.name}" is missing source`,
					skillName: skill.name,
					field: `skills[${index}].source`,
				});
			} else if (!["local", "builtin", "remote"].includes(skill.source)) {
				errors.push({
					type: "invalid_field",
					message: `Skill "${skill.name}" has invalid source: "${skill.source}" (must be "local", "builtin", or "remote")`,
					skillName: skill.name,
					field: `skills[${index}].source`,
				});
			}

			if (skill.source === "remote" && !manifest.remoteFetchEnabled) {
				errors.push({
					type: "remote_not_enabled",
					message: `Skill "${skill.name}" uses remote source but remoteFetchEnabled is not set to true`,
					skillName: skill.name,
					field: `skills[${index}].source`,
				});
			}

			if (skill.source === "remote" && !skill.url) {
				warnings.push({
					type: "missing_field",
					message: `Remote skill "${skill.name}" should have a url field`,
					skillName: skill.name,
					field: `skills[${index}].url`,
				});
			}

			if (skill.source !== "remote" && skill.url) {
				warnings.push({
					type: "invalid_field",
					message: `Non-remote skill "${skill.name}" has a url field that will be ignored`,
					skillName: skill.name,
					field: `skills[${index}].url`,
				});
			}
		}
	}

	return { valid: errors.length === 0, errors, warnings };
}

/**
 * Default empty manifest.
 */
export const EMPTY_MANIFEST: SkillManifest = {
	version: 1,
	skills: [],
	remoteFetchEnabled: false,
};

/**
 * Parse a skill manifest from JSON string.
 *
 * Returns the parsed manifest and validation result.
 * On parse failure, returns EMPTY_MANIFEST with a validation error.
 *
 * @param json - JSON string to parse
 * @returns Parsed manifest and validation result
 */
export function parseSkillManifest(json: string): { manifest: SkillManifest; validation: ManifestValidationResult } {
	let parsed: Partial<SkillManifest>;
	try {
		parsed = JSON.parse(json);
	} catch {
		const validation: ManifestValidationResult = {
			valid: false,
			errors: [{ type: "invalid_field", message: "Invalid JSON in skill manifest", field: "root" }],
			warnings: [],
		};
		return { manifest: EMPTY_MANIFEST, validation };
	}

	if (typeof parsed !== "object" || parsed === null || Array.isArray(parsed)) {
		const validation: ManifestValidationResult = {
			valid: false,
			errors: [{ type: "invalid_field", message: "Skill manifest must be a JSON object", field: "root" }],
			warnings: [],
		};
		return { manifest: EMPTY_MANIFEST, validation };
	}

	const validation = validateSkillManifest(parsed);
	if (!validation.valid) {
		return { manifest: EMPTY_MANIFEST, validation };
	}

	return {
		manifest: {
			version: parsed.version!,
			skills: parsed.skills!,
			remoteFetchEnabled: parsed.remoteFetchEnabled ?? false,
			projectName: parsed.projectName,
		},
		validation,
	};
}

/**
 * Skill Registry & Skill Resolver - P2 Workstream 5.D
 *
 * The SkillRegistry lists and validates local skills against a manifest.
 * The SkillResolver recommends skills for workspaces based on requirements.
 */

import { existsSync, readFileSync } from "node:fs";
import { join } from "node:path";
import type { ResourceDiagnostic } from "./diagnostics.js";
import {
	EMPTY_MANIFEST,
	type ManifestValidationResult,
	parseSkillManifest,
	type SkillManifest,
	type SkillManifestEntry,
} from "./skill-manifest.js";
import type { Skill } from "./skills.js";
import { type LoadSkillsResult, loadSkills } from "./skills.js";

const MANIFEST_FILENAME = "skill-manifest.json";

/**
 * Registry entry combining a loaded skill with its manifest metadata.
 */
export interface RegistrySkillEntry {
	/** The loaded skill */
	skill: Skill;
	/** Manifest entry (if skill was declared in manifest) */
	manifestEntry?: SkillManifestEntry;
	/** Whether this skill passes validation */
	valid: boolean;
	/** Validation messages */
	validationMessages: string[];
}

/**
 * Registry result from listing skills.
 */
export interface SkillRegistryResult {
	/** All registered skill entries */
	entries: RegistrySkillEntry[];
	/** Skills that are missing (required by manifest but not found locally) */
	missingSkills: Array<{ entry: SkillManifestEntry; reason: string }>;
	/** Diagnostics from skill loading and validation */
	diagnostics: ResourceDiagnostic[];
	/** The parsed manifest (if found) */
	manifest: SkillManifest;
	/** Manifest validation result */
	manifestValidation: ManifestValidationResult;
}

/**
 * Skill Registry
 *
 * Lists and validates local skills against a skill manifest.
 * Reads the manifest from the project config directory, loads skills
 * from local directories, and reports missing required skills.
 */
export class SkillRegistry {
	private cwd: string;
	private agentDir: string;

	/**
	 * Create a SkillRegistry.
	 *
	 * @param cwd - Working directory for project-local skills
	 * @param agentDir - Agent config directory for global skills
	 */
	constructor(cwd: string, agentDir: string) {
		this.cwd = cwd;
		this.agentDir = agentDir;
	}

	/**
	 * List and validate local skills against the manifest.
	 *
	 * @param options - Options for skill loading
	 * @param options.skillPaths - Additional skill paths to load
	 * @param options.includeDefaults - Whether to include default skill directories
	 * @returns Registry result with entries, missing skills, and diagnostics
	 */
	list(options?: { skillPaths?: string[]; includeDefaults?: boolean }): SkillRegistryResult {
		const skillPaths = options?.skillPaths ?? [];
		const includeDefaults = options?.includeDefaults ?? true;

		// Load the manifest
		const { manifest, manifestValidation } = this.loadManifest();

		// Load all local skills
		const loadResult: LoadSkillsResult = loadSkills({
			cwd: this.cwd,
			agentDir: this.agentDir,
			skillPaths,
			includeDefaults,
		});

		// Build a skill name -> Skill map
		const skillMap = new Map<string, Skill>();
		for (const skill of loadResult.skills) {
			skillMap.set(skill.name, skill);
		}

		// Build registry entries
		const entries: RegistrySkillEntry[] = [];
		const missingSkills: Array<{ entry: SkillManifestEntry; reason: string }> = [];
		const diagnostics: ResourceDiagnostic[] = [...loadResult.diagnostics];

		// Check each manifest entry against loaded skills
		const manifestSkillNames = new Set<string>();

		for (const manifestEntry of manifest.skills) {
			manifestSkillNames.add(manifestEntry.name);
			const skill = skillMap.get(manifestEntry.name);

			if (!skill) {
				// Skill declared in manifest but not found
				if (manifestEntry.required) {
					missingSkills.push({
						entry: manifestEntry,
						reason: `Required skill "${manifestEntry.name}" not found in local skills`,
					});
					diagnostics.push({
						type: "error",
						message: `Required skill "${manifestEntry.name}" is missing`,
						path: this.getManifestPath(),
					});
				} else {
					// Optional missing skill - just a warning
					diagnostics.push({
						type: "warning",
						message: `Optional skill "${manifestEntry.name}" not found in local skills`,
						path: this.getManifestPath(),
					});
				}
				continue;
			}

			// Skill found - validate it against manifest expectations
			const validationMessages: string[] = [];
			let valid = true;

			if (manifestEntry.source === "remote" && !manifest.remoteFetchEnabled) {
				validationMessages.push(`Skill "${manifestEntry.name}" declared as remote but remote fetch is disabled`);
				valid = false;
			}

			if (manifestEntry.description && skill.description !== manifestEntry.description) {
				validationMessages.push(
					`Skill "${manifestEntry.name}" description mismatch: manifest says "${manifestEntry.description}" but skill has "${skill.description}"`,
				);
			}

			entries.push({
				skill,
				manifestEntry,
				valid,
				validationMessages,
			});

			// Remove from skillMap so we can track extras
			skillMap.delete(manifestEntry.name);
		}

		// Add skills that were loaded but not in the manifest
		for (const skill of skillMap.values()) {
			entries.push({
				skill,
				valid: true,
				validationMessages: [],
			});
		}

		return {
			entries,
			missingSkills,
			diagnostics,
			manifest,
			manifestValidation,
		};
	}

	/**
	 * Validate that all required skills are present.
	 *
	 * @param options - Options for skill loading
	 * @returns True if all required skills are present
	 */
	validate(options?: { skillPaths?: string[]; includeDefaults?: boolean }): {
		valid: boolean;
		missingRequired: Array<{ entry: SkillManifestEntry; reason: string }>;
	} {
		const result = this.list(options);
		return {
			valid: result.missingSkills.length === 0,
			missingRequired: result.missingSkills,
		};
	}

	/**
	 * Get the path to the skill manifest file.
	 *
	 * @returns Path to skill-manifest.json
	 */
	getManifestPath(): string {
		// Check project config dir first
		const projectManifest = join(this.cwd, ".pi", MANIFEST_FILENAME);
		if (existsSync(projectManifest)) {
			return projectManifest;
		}

		// Fall back to agent dir
		const agentManifest = join(this.agentDir, MANIFEST_FILENAME);
		if (existsSync(agentManifest)) {
			return agentManifest;
		}

		// Default to project config path (even if it doesn't exist)
		return projectManifest;
	}

	/**
	 * Load the skill manifest from the project or agent config directory.
	 *
	 * @returns Parsed manifest and validation result
	 */
	private loadManifest(): { manifest: SkillManifest; manifestValidation: ManifestValidationResult } {
		const manifestPath = this.getManifestPath();

		if (!existsSync(manifestPath)) {
			// No manifest found - return empty manifest
			return {
				manifest: EMPTY_MANIFEST,
				manifestValidation: { valid: true, errors: [], warnings: [] },
			};
		}

		try {
			const content = readFileSync(manifestPath, "utf-8");
			const { manifest, validation: manifestValidation } = parseSkillManifest(content);
			return { manifest, manifestValidation };
		} catch (error) {
			const message = error instanceof Error ? error.message : "Failed to read skill manifest";
			return {
				manifest: EMPTY_MANIFEST,
				manifestValidation: {
					valid: false,
					errors: [{ type: "invalid_field", message, field: "root" }],
					warnings: [],
				},
			};
		}
	}
}

/**
 * Skill recommendation for a workspace.
 */
export interface SkillRecommendation {
	/** Recommended skill */
	skill: Skill;
	/** Reason for recommendation */
	reason: string;
	/** Relevance score (0-1) */
	relevance: number;
}

/**
 * Skill Resolver
 *
 * Recommends skills for workspaces based on:
 * - Workspace capabilities and file patterns
 * - Keyword matching between workspace description and skill descriptions
 * - Required skills from the manifest
 */
export class SkillResolver {
	private registry: SkillRegistry;

	/**
	 * Create a SkillResolver.
	 *
	 * @param cwd - Working directory
	 * @param agentDir - Agent config directory
	 */
	constructor(cwd: string, agentDir: string) {
		this.registry = new SkillRegistry(cwd, agentDir);
	}

	/**
	 * Recommend skills for a workspace.
	 *
	 * @param workspace - Workspace specification with id, title, and optional capabilities
	 * @param options - Options for skill loading
	 * @returns Recommended skills sorted by relevance
	 */
	recommend(
		workspace: { id: string; title: string; keywords?: string[] },
		options?: {
			skillPaths?: string[];
			includeDefaults?: boolean;
		},
	): SkillRecommendation[] {
		const result = this.registry.list(options);
		const recommendations: SkillRecommendation[] = [];

		// Collect keywords from workspace title and explicit keywords
		const workspaceKeywords = this.extractKeywords(workspace.title);
		if (workspace.keywords) {
			workspaceKeywords.push(...workspace.keywords.map((k) => k.toLowerCase()));
		}

		for (const entry of result.entries) {
			if (!entry.valid) {
				continue;
			}

			const skillKeywords = this.extractKeywords(entry.skill.description);
			const skillNameKeywords = this.extractKeywords(entry.skill.name);

			// Calculate relevance score
			let relevance = 0;
			const matchReasons: string[] = [];

			// Check for required skills from manifest
			if (entry.manifestEntry?.required) {
				relevance = 1.0;
				matchReasons.push("Required by manifest");
			}

			// Keyword matching
			if (relevance < 1.0) {
				for (const wk of workspaceKeywords) {
					for (const sk of [...skillKeywords, ...skillNameKeywords]) {
						if (wk === sk) {
							relevance += 0.3;
							matchReasons.push(`Keyword match: "${wk}"`);
						} else if (sk.includes(wk) || wk.includes(sk)) {
							relevance += 0.1;
							matchReasons.push(`Partial keyword match: "${wk}" ~ "${sk}"`);
						}
					}
				}
			}

			// Cap relevance at 1.0
			relevance = Math.min(relevance, 1.0);

			// Only recommend if there's some relevance
			if (relevance > 0) {
				recommendations.push({
					skill: entry.skill,
					reason: matchReasons.length > 0 ? matchReasons.join("; ") : "Available skill",
					relevance,
				});
			}
		}

		// Sort by relevance descending
		recommendations.sort((a, b) => b.relevance - a.relevance);

		return recommendations;
	}

	/**
	 * Get the underlying SkillRegistry.
	 *
	 * @returns The skill registry
	 */
	getRegistry(): SkillRegistry {
		return this.registry;
	}

	/**
	 * Extract lowercase keywords from a text string.
	 *
	 * Splits on whitespace and punctuation, filters out common stop words
	 * and very short tokens.
	 *
	 * @param text - Text to extract keywords from
	 * @returns Array of lowercase keywords
	 */
	private extractKeywords(text: string): string[] {
		const stopWords = new Set([
			"a",
			"an",
			"the",
			"and",
			"or",
			"but",
			"in",
			"on",
			"at",
			"to",
			"for",
			"of",
			"with",
			"by",
			"from",
			"is",
			"are",
			"was",
			"were",
			"be",
			"been",
			"being",
			"have",
			"has",
			"had",
			"do",
			"does",
			"did",
			"will",
			"would",
			"could",
			"should",
			"may",
			"might",
			"this",
			"that",
			"these",
			"those",
		]);

		return text
			.toLowerCase()
			.replace(/[()[]{},.;:!?]/g, " ")
			.split(/[^a-z0-9-]+/)
			.filter((token) => token.length > 1 && !stopWords.has(token));
	}
}

