/**
 * Database types for the execution persistence layer.
 *
 * Mirrors the execution hierarchy from the architecture plan:
 * Project → PlanExecution → WorkspaceExecution → JournalEvent / WorkspaceLog
 */

/**
 * Project entity
 */
