/**
 * Create a self-modification firewall instance.
 *
 * @param cwd - Working directory for resolving relative paths
 * @param isAutonomous - Whether the agent is in autonomous mode
 * @param customProtectedSystems - Additional user-defined protected systems
 * @returns SelfModificationFirewall instance
 */
export function createSelfModificationFirewall(
	cwd: string,
	isAutonomous: boolean = false,
	customProtectedSystems?: ProtectedSystem[],
): SelfModificationFirewall {
	return new SelfModificationFirewall({ cwd, isAutonomous, customProtectedSystems });
}

/**
 * Unsafe Suggestion Guard - P8.D
 *
 * Flags and prevents unsafe suggestions from proceeding. Safeguards
 * against suggestions that would modify protected systems, perform
 * destructive operations, bypass approval gates, or violate safety
 * policies.
 *
 * Acceptance Criteria:
 * - Unsafe suggestions are flagged and cannot proceed.
 * - Each unsafe suggestion includes a reason and explanation.
 * - Enhanced approval can be required for borderline unsafe suggestions.
 */

import type { DetectionResult, UnsafeCheckResult, UnsafeReason } from "./detection-types.js";

// ---------------------------------------------------------------------------
// Built-in Unsafe Patterns
// ---------------------------------------------------------------------------

/**
 * A pattern that identifies potentially unsafe suggestions.
 */
interface UnsafePattern {
	/** The reason this pattern is unsafe */
	reason: UnsafeReason;
	/** Pattern to match against title/description */
	pattern: RegExp;
	/** Whether suggestions matching this pattern are blocked entirely */
	blocked: boolean;
	/** Whether enhanced approval is needed (beyond normal approval) */
	requiresEnhancedApproval: boolean;
	/** Human-readable explanation */
	explanation: string;
}

/**
 * Built-in unsafe patterns.
 *
 * These are hardcoded patterns that identify clearly unsafe suggestions.
 * They match against detection titles and descriptions.
 */
const BUILT_IN_UNSAFE_PATTERNS: UnsafePattern[] = [
	{
		reason: "modifies_protected_system",
		pattern: /modify\s+(the\s+)?(planner|executor|validator|firewall|policy|safety|queue)/i,
		blocked: true,
		requiresEnhancedApproval: true,
		explanation:
			"Suggestions that modify planner, executor, validator, firewall, policy, safety, or queue systems are unsafe and require explicit self-modification approval.",
	},
	{
		reason: "destructive_operation",
		pattern: /(delete|remove|destroy|wipe|clear|truncate)\s+(all|entire|every)\s+(file|data|record|log|backup)/i,
		blocked: true,
		requiresEnhancedApproval: true,
		explanation: "Suggestions involving destructive operations on entire datasets are blocked.",
	},
	{
		reason: "bypasses_approval",
		pattern: /(bypass|skip|ignore|disable)\s+(approval|review|gate|check|validation)/i,
		blocked: true,
		requiresEnhancedApproval: true,
		explanation: "Suggestions that bypass approval, review, or validation gates are blocked.",
	},
	{
		reason: "modifies_executor_state",
		pattern: /(directly\s+)?(modify|mutate|change|alter)\s+(execution|executor)\s+(state|status|log)/i,
		blocked: true,
		requiresEnhancedApproval: true,
		explanation:
			"Suggestions that directly mutate executor state are blocked. State transitions must go through the executor.",
	},
	{
		reason: "modifies_queue",
		pattern: /(modify|mutate|reorder|clear)\s+(the\s+)?(integration\s+)?queue/i,
		blocked: false,
		requiresEnhancedApproval: true,
		explanation: "Suggestions that modify the integration queue require enhanced approval.",
	},
	{
		reason: "bypasses_validation",
		pattern: /(skip|bypass|disable)\s+(validation|testing)/i,
		blocked: false,
		requiresEnhancedApproval: true,
		explanation: "Suggestions that skip or disable validation require enhanced approval.",
	},
	{
		reason: "modifies_security_config",
		pattern: /(modify|change|disable|weaken)\s+(security|auth|permission|access\s+control)/i,
		blocked: true,
		requiresEnhancedApproval: true,
		explanation: "Suggestions that modify security configuration are blocked.",
	},
	{
		reason: "modifies_auth_config",
		pattern: /(modify|change|expose|share)\s+(api[_-]?key|token|credential|secret|password)/i,
		blocked: true,
		requiresEnhancedApproval: true,
		explanation: "Suggestions involving API keys, tokens, credentials, or secrets are blocked.",
	},
	{
		reason: "exceeds_scope",
		pattern: /refactor\s+(entire|whole|all)\s+(project|codebase|application|system)/i,
		blocked: false,
		requiresEnhancedApproval: true,
		explanation: "Suggestions to refactor the entire project require enhanced approval.",
	},
];

// ---------------------------------------------------------------------------
// Protected System Patterns
// ---------------------------------------------------------------------------

/**
 * Patterns that identify pi's own protected source code and configuration.
 * Mirroring the self-modification firewall's protected systems (P8.F).
 */
const PROTECTED_SYSTEM_PATTERNS: Array<{ name: string; patterns: string[] }> = [
	{
		name: "Pi Source Code",
		patterns: ["packages/**/*"],
	},
	{
		name: "Pi Agent Configuration",
		patterns: [".pi/agent/**/*"],
	},
	{
		name: "Pi Project Configuration",
		patterns: [".pi/**/*.json", ".pi/**/*.md"],
	},
	{
		name: "Execution System",
		patterns: ["packages/coding-agent/src/core/executor*", "packages/coding-agent/src/core/plan-queue-runner*"],
	},
	{
		name: "Safety System",
		patterns: ["packages/coding-agent/src/core/safety*", "packages/coding-agent/src/core/write-gate*"],
	},
];

// ---------------------------------------------------------------------------
// Detection-Level Unsafe Checks
// ---------------------------------------------------------------------------

/**
 * Built-in category-level unsafe rules.
 *
 * Certain detection categories are inherently unsafe and always
 * require enhanced approval, even if the individual suggestion
 * doesn't match a specific unsafe pattern.
 */
const CATEGORY_UNSAFE_RULES: Record<string, { blocked: boolean; requiresEnhancedApproval: boolean }> = {
	security_concern: { blocked: false, requiresEnhancedApproval: true },
};

// ---------------------------------------------------------------------------
// UnsafeSuggestionGuard
// ---------------------------------------------------------------------------

/**
 * Guards against unsafe suggestions.
 *
 * Checks detections against built-in unsafe patterns, protected
 * system patterns, and category-level rules. Provides methods to
 * check individual detections, filter unsafe results, and block
 * unsafe suggestions from proceeding.
 */
export class UnsafeSuggestionGuard {
	/** Custom unsafe patterns (in addition to built-in) */
	private customPatterns: UnsafePattern[] = [];

	/**
	 * Add a custom unsafe pattern.
	 *
	 * @param pattern - The unsafe pattern configuration
	 */
	addCustomPattern(pattern: Omit<UnsafePattern, "reason"> & { reason: UnsafeReason }): void {
		this.customPatterns.push(pattern as UnsafePattern);
	}

	/**
	 * Check a detection for unsafe characteristics.
	 *
	 * Returns an UnsafeCheckResult that indicates whether the
	 * detection is unsafe, why, and whether it's blocked.
	 *
	 * @param detection - The detection to check
	 * @returns Unsafe check result
	 */
	check(detection: DetectionResult): UnsafeCheckResult {
		const reasons: UnsafeReason[] = [];
		let blocked = false;
		let requiresEnhancedApproval = false;
		const explanations: string[] = [];

		// Check built-in patterns
		for (const pattern of BUILT_IN_UNSAFE_PATTERNS) {
			if (pattern.pattern.test(detection.title) || pattern.pattern.test(detection.description)) {
				reasons.push(pattern.reason);
				if (pattern.blocked) blocked = true;
				if (pattern.requiresEnhancedApproval) requiresEnhancedApproval = true;
				explanations.push(pattern.explanation);
			}
		}

		// Check custom patterns
		for (const pattern of this.customPatterns) {
			if (pattern.pattern.test(detection.title) || pattern.pattern.test(detection.description)) {
				reasons.push(pattern.reason);
				if (pattern.blocked) blocked = true;
				if (pattern.requiresEnhancedApproval) requiresEnhancedApproval = true;
				explanations.push(pattern.explanation);
			}
		}

		// Check category-level rules
		const categoryRule = CATEGORY_UNSAFE_RULES[detection.category];
		if (categoryRule) {
			if (categoryRule.blocked) blocked = true;
			if (categoryRule.requiresEnhancedApproval) requiresEnhancedApproval = true;
			if (categoryRule.blocked || categoryRule.requiresEnhancedApproval) {
				explanations.push(
					`Detections in category "${detection.category}" require ${categoryRule.requiresEnhancedApproval ? "enhanced approval" : "review"}.`,
				);
			}
		}

		// Check affected paths against protected systems
		if (detection.affectedPaths && detection.affectedPaths.length > 0) {
			for (const affectedPath of detection.affectedPaths) {
				for (const system of PROTECTED_SYSTEM_PATTERNS) {
					for (const pattern of system.patterns) {
						if (this.matchGlob(affectedPath, pattern)) {
							if (!reasons.includes("modifies_protected_system")) {
								reasons.push("modifies_protected_system");
							}
							blocked = true;
							requiresEnhancedApproval = true;
							explanations.push(
								`Affected path "${affectedPath}" matches protected system "${system.name}" (pattern: ${pattern}). Modifications to protected systems are blocked.`,
							);
						}
					}
				}
			}
		}

		const isUnsafe = reasons.length > 0;

		return {
			isUnsafe,
			reasons,
			explanation: explanations.join("\n"),
			blocked,
			requiresEnhancedApproval,
		};
	}

	/**
	 * Filter detections, separating safe from unsafe ones.
	 *
	 * @param detections - Detections to filter
	 * @returns Filtered results with safe, unsafe, and blocked lists
	 */
	filter(detections: DetectionResult[]): {
		safe: DetectionResult[];
		unsafe: DetectionResult[];
		blocked: DetectionResult[];
		checkResults: Record<string, UnsafeCheckResult>;
	} {
		const safe: DetectionResult[] = [];
		const unsafe: DetectionResult[] = [];
		const blocked: DetectionResult[] = [];
		const checkResults: Record<string, UnsafeCheckResult> = {};

		for (const detection of detections) {
			const result = this.check(detection);
			checkResults[detection.id] = result;

			if (result.isUnsafe) {
				unsafe.push(detection);
				if (result.blocked) {
					blocked.push(detection);
				}
			} else {
				safe.push(detection);
			}
		}

		return { safe, unsafe, blocked, checkResults };
	}

	/**
	 * Assert that a detection is safe to proceed.
	 *
	 * Throws an error if the detection is unsafe and blocked.
	 * If the detection is unsafe but not blocked (requires enhanced
	 * approval), returns the check result without throwing.
	 *
	 * @param detection - The detection to check
	 * @throws Error if the detection is unsafe and blocked
	 * @returns UnsafeCheckResult
	 */
	assertSafe(detection: DetectionResult): UnsafeCheckResult {
		const result = this.check(detection);

		if (result.blocked) {
			throw new Error(
				`Unsafe suggestion blocked: ${detection.title}\n` +
					`Reasons: ${result.reasons.join(", ")}\n` +
					`Explanation: ${result.explanation}`,
			);
		}

		if (result.isUnsafe && result.requiresEnhancedApproval) {
			// Not blocked, but requires enhanced approval - return result without throwing
		}

		return result;
	}

	/**
	 * Simple glob matching for protected system patterns.
	 *
	 * Supports ** (match any number of directories) and * (match
	 * within a single path segment).
	 */
	private matchGlob(filePath: string, pattern: string): boolean {
		// Convert glob pattern to regex
		let regexStr = "";
		let i = 0;

		while (i < pattern.length) {
			const ch = pattern[i];

			if (ch === "*" && i + 1 < pattern.length && pattern[i + 1] === "*") {
				// ** matches everything
				regexStr += ".*";
				i += 2;
			} else if (ch === "*") {
				// * matches non-slash characters
				regexStr += "[^/]*";
				i++;
			} else {
				// Escape special regex characters
				regexStr += ch.replace(/[.+?^${}()|[\]\\]/g, "\\$&");
				i++;
			}
		}

		try {
			const regex = new RegExp(`^${regexStr}$`);
			return regex.test(filePath);
		} catch {
			return false;
		}
	}
}

/**
 * Create an unsafe suggestion guard instance.
 *
 * @returns Unsafe suggestion guard instance
 */
export function createUnsafeSuggestionGuard(): UnsafeSuggestionGuard {
	return new UnsafeSuggestionGuard();
}

/**
 * Governance Ledger - P9.G7
 *
 * Central audit trail that wires together all G1-G6 components into a
 * single coherent ledger. Every governance-relevant event across the
 * remediation lifecycle is recorded here, providing an immutable record
 * for audit, compliance, and post-mortem analysis.
 *
 * G1-G6 Component Events:
 *   G1 (Remediation Runtime) — State transitions, scan events
 *   G2 (Proposal/Execution DB) — Proposal submissions, execution records,
 *        revision history
 *   G3 (Approval & Budget) — Approval events, change requests,
 *        self-modification approvals, budget snapshots, approval chains
 *   G4 (Dry-Run & Validation) — Dry-run assumptions, validation outcomes,
 *        validation failures
 *   G5 (Budget Enforcer / Policy Engine) — Budget summaries, policy checks,
 *        autonomy classifications, blast-radius controls
 *   G6 (Safety Doctor / Execution Simulator / Integration Queue) —
 *        Safety reports, simulation forecasts, queue audit entries
 *
 * The completion gate (P4.6.1) requires a complete ledger entry before
 * marking any workspace or plan done.
 */

// ---------------------------------------------------------------------------
// Source Identifiers
// ---------------------------------------------------------------------------

/**
 * Known component sources that write to the governance ledger.
 */
export type LedgerSource =
	| "g1_remediation_runtime"
	| "g2_proposal_db"
	| "g3_approval_budget"
	| "g4_dry_run_validation"
	| "g5_budget_policy_engine"
	| "g6_safety_simulation_queue"
	| "g7_governance_ledger";

/**
 * Human-readable label for each ledger source.
 */
export const LEDGER_SOURCE_LABELS: Record<LedgerSource, string> = {
	g1_remediation_runtime: "G1 — Remediation Runtime",
	g2_proposal_db: "G2 — Proposal/Execution DB",
	g3_approval_budget: "G3 — Approval & Budget Recording",
	g4_dry_run_validation: "G4 — Dry-Run & Validation Recording",
	g5_budget_policy_engine: "G5 — Budget Enforcer & Policy Engine",
	g6_safety_simulation_queue: "G6 — Safety, Simulation & Queue",
	g7_governance_ledger: "G7 — Governance Ledger",
};

// ---------------------------------------------------------------------------
// Event Types
// ---------------------------------------------------------------------------

/**
 * Top-level categories for ledger events.
 */
export type LedgerEventCategory =
	| "state_transition"
	| "proposal"
	| "execution_record"
	| "revision"
	| "approval"
	| "change_request"
	| "self_modification"
	| "budget_snapshot"
	| "dry_run"
	| "validation"
	| "validation_failure"
	| "policy_check"
	| "autonomy_classification"
	| "safety_report"
	| "simulation_forecast"
	| "queue_audit"
	| "completion_gate";

/**
 * Severity level for a ledger event.
 */
export type LedgerEventSeverity = "info" | "warning" | "error" | "critical";

// ---------------------------------------------------------------------------
// Core Types
// ---------------------------------------------------------------------------

/**
 * A single entry in the governance ledger.
 * Every event from G1-G6 is normalized into this shape.
 */
export interface LedgerEntry {
	/** Unique entry ID (monotonic within each ledger instance) */
	id: string;
	/** Timestamp (ISO 8601) */
	timestamp: string;
	/** Which component originated this event */
	source: LedgerSource;
	/** Event category */
	category: LedgerEventCategory;
	/** Severity level */
	severity: LedgerEventSeverity;
	/** Human-readable summary */
	summary: string;
	/** Optional plan execution ID */
	planExecId?: string;
	/** Optional workspace ID */
	workspaceId?: string;
	/** Optional detail payload (JSON-serialisable) */
	detail?: Record<string, unknown>;
}

/**
 * Completion gate ledger entry.
 * Recorded when a workspace or plan passes through the completion gate.
 */
export interface CompletionGateRecord {
	/** The ledger entry for this gate event */
	entry: LedgerEntry;
	/** Whether the gate was passed */
	passed: boolean;
	/** Block reasons if not passed */
	blockReasons: string[];
	/** Workspace IDs evaluated (for plan-level gates) */
	workspaceIds?: string[];
}

/**
 * Summary of all ledger entries.
 */
export interface LedgerSummary {
	/** Total entries recorded */
	totalEntries: number;
	/** Entry count by source */
	bySource: Partial<Record<LedgerSource, number>>;
	/** Entry count by category */
	byCategory: Partial<Record<LedgerEventCategory, number>>;
	/** Entry count by severity */
	bySeverity: Partial<Record<LedgerEventSeverity, number>>;
	/** Entries with errors or critical severity */
	criticalEntries: number;
	/** Whether a completion gate entry exists and passed */
	completionGatePassed: boolean;
	/** Timestamp of the first entry */
	firstEntryAt?: string;
	/** Timestamp of the last entry */
	lastEntryAt?: string;
}

/**
 * Complete governance ledger snapshot for persistence and display.
 */
export interface GovernanceLedgerSnapshot {
	/** All entries in the ledger */
	entries: LedgerEntry[];
	/** Current summary */
	summary: LedgerSummary;
	/** Completion gate record if evaluated */
	completionGate?: CompletionGateRecord;
	/** When the ledger was created */
	createdAt: string;
	/** When the ledger was last updated */
	updatedAt: string;
}

// ---------------------------------------------------------------------------
// Governance Ledger
// ---------------------------------------------------------------------------

let _entryCounter = 0;

/**
 * Central governance ledger that collects audit events from G1-G6
 * components and enforces completion gate requirements.
 *
 * The ledger maintains an ordered, immutable list of entries. Each entry
 * carries metadata about its origin source, category, and severity for
 * filtering and reporting.
 */
export class GovernanceLedger {
	private _entries: LedgerEntry[] = [];
	private _completionGate?: CompletionGateRecord;
	private readonly _createdAt: string;

	constructor() {
		this._createdAt = new Date().toISOString();
	}

	// -----------------------------------------------------------------------
	// Accessors
	// -----------------------------------------------------------------------

	/** All recorded entries (immutable view) */
	get entries(): ReadonlyArray<LedgerEntry> {
		return this._entries;
	}

	/** Current ledger summary */
	get summary(): LedgerSummary {
		return this.computeSummary();
	}

	/** Completion gate record, if evaluated */
	get completionGate(): CompletionGateRecord | undefined {
		return this._completionGate;
	}

	/** When the ledger was created */
	get createdAt(): string {
		return this._createdAt;
	}

	/** Whether the ledger has a passing completion gate record */
	get hasPassedCompletionGate(): boolean {
		return this._completionGate?.passed === true;
	}

	// -----------------------------------------------------------------------
	// Recording
	// -----------------------------------------------------------------------

	/**
	 * Record a new entry in the ledger.
	 *
	 * @param source - Component source
	 * @param category - Event category
	 * @param severity - Severity level
	 * @param summary - Human-readable summary
	 * @param options - Optional metadata (planExecId, workspaceId, detail)
	 * @returns The created ledger entry
	 */
	record(
		source: LedgerSource,
		category: LedgerEventCategory,
		severity: LedgerEventSeverity,
		summary: string,
		options?: {
			planExecId?: string;
			workspaceId?: string;
			detail?: Record<string, unknown>;
		},
	): LedgerEntry {
		_entryCounter++;
		const entry: LedgerEntry = {
			id: `ledger-${Date.now()}-${_entryCounter}`,
			timestamp: new Date().toISOString(),
			source,
			category,
			severity,
			summary,
			planExecId: options?.planExecId,
			workspaceId: options?.workspaceId,
			detail: options?.detail,
		};

		this._entries.push(entry);
		return entry;
	}

	/**
	 * Record a state transition event (G1).
	 */
	recordStateTransition(
		from: string,
		to: string,
		reason: string,
		options?: { planExecId?: string; workspaceId?: string },
	): LedgerEntry {
		return this.record("g1_remediation_runtime", "state_transition", "info", `State transition: ${from} -> ${to}`, {
			planExecId: options?.planExecId,
			workspaceId: options?.workspaceId,
			detail: { from, to, reason },
		});
	}

	/**
	 * Record a proposal event (G2).
	 */
	recordProposal(
		action: "submitted" | "approved" | "rejected" | "updated",
		proposalId: string,
		summary: string,
		options?: { planExecId?: string; workspaceId?: string; detail?: Record<string, unknown> },
	): LedgerEntry {
		return this.record("g2_proposal_db", "proposal", "info", summary, {
			planExecId: options?.planExecId,
			workspaceId: options?.workspaceId,
			detail: { proposalId, action, ...options?.detail },
		});
	}

	/**
	 * Record an execution record event (G2).
	 */
	recordExecutionRecord(
		action: "started" | "completed" | "failed",
		executionId: string,
		summary: string,
		options?: { planExecId?: string; workspaceId?: string; detail?: Record<string, unknown> },
	): LedgerEntry {
		return this.record("g2_proposal_db", "execution_record", action === "failed" ? "error" : "info", summary, {
			planExecId: options?.planExecId,
			workspaceId: options?.workspaceId,
			detail: { executionId, action, ...options?.detail },
		});
	}

	/**
	 * Record an approval event (G3).
	 */
	recordApproval(
		type: "planning" | "execution" | "change_request" | "self_modification",
		decision: "approved" | "rejected" | "requested",
		summary: string,
		options?: {
			planExecId?: string;
			workspaceId?: string;
			reviewer?: string;
			proposalId?: string;
			budgetSnapshot?: Record<string, unknown>;
			detail?: Record<string, unknown>;
		},
	): LedgerEntry {
		const severity: LedgerEventSeverity = decision === "rejected" ? "warning" : "info";
		return this.record("g3_approval_budget", "approval", severity, summary, {
			planExecId: options?.planExecId,
			workspaceId: options?.workspaceId,
			detail: {
				approvalType: type,
				decision,
				reviewer: options?.reviewer,
				proposalId: options?.proposalId,
				budgetSnapshot: options?.budgetSnapshot,
				...options?.detail,
			},
		});
	}

	/**
	 * Record a budget snapshot (G3/G5).
	 */
	recordBudgetSnapshot(
		budgetSummary: Record<string, unknown>,
		summary: string,
		options?: { planExecId?: string; workspaceId?: string },
	): LedgerEntry {
		return this.record("g5_budget_policy_engine", "budget_snapshot", "info", summary, {
			planExecId: options?.planExecId,
			workspaceId: options?.workspaceId,
			detail: { budgetSummary },
		});
	}

	/**
	 * Record a dry-run event (G4).
	 */
	recordDryRun(
		status: "started" | "completed" | "failed",
		summary: string,
		options?: {
			planExecId?: string;
			workspaceId?: string;
			totalProposals?: number;
			mutationsPredicted?: number;
			detail?: Record<string, unknown>;
		},
	): LedgerEntry {
		const severity: LedgerEventSeverity = status === "failed" ? "error" : "info";
		return this.record("g4_dry_run_validation", "dry_run", severity, summary, {
			planExecId: options?.planExecId,
			workspaceId: options?.workspaceId,
			detail: {
				status,
				totalProposals: options?.totalProposals,
				mutationsPredicted: options?.mutationsPredicted,
				...options?.detail,
			},
		});
	}

	/**
	 * Record a validation outcome (G4).
	 */
	recordValidation(
		outcome: "passed" | "failed" | "skipped",
		testName: string,
		summary: string,
		options?: { planExecId?: string; workspaceId?: string; detail?: Record<string, unknown> },
	): LedgerEntry {
		const severity: LedgerEventSeverity = outcome === "failed" ? "error" : outcome === "skipped" ? "warning" : "info";
		return this.record("g4_dry_run_validation", "validation", severity, summary, {
			planExecId: options?.planExecId,
			workspaceId: options?.workspaceId,
			detail: { outcome, testName, ...options?.detail },
		});
	}

	/**
	 * Record a validation failure (G4).
	 */
	recordValidationFailure(
		errorMessage: string,
		context: Record<string, unknown>,
		summary: string,
		options?: { planExecId?: string; workspaceId?: string },
	): LedgerEntry {
		return this.record("g4_dry_run_validation", "validation_failure", "error", summary, {
			planExecId: options?.planExecId,
			workspaceId: options?.workspaceId,
			detail: { errorMessage, context },
		});
	}

	/**
	 * Record a policy check (G5).
	 */
	recordPolicyCheck(
		policyName: string,
		passed: boolean,
		isBlocking: boolean,
		summary: string,
		options?: { planExecId?: string; workspaceId?: string; detail?: Record<string, unknown> },
	): LedgerEntry {
		const severity: LedgerEventSeverity = !passed && isBlocking ? "critical" : !passed ? "warning" : "info";
		return this.record("g5_budget_policy_engine", "policy_check", severity, summary, {
			planExecId: options?.planExecId,
			workspaceId: options?.workspaceId,
			detail: { policyName, passed, isBlocking, ...options?.detail },
		});
	}

	/**
	 * Record an autonomy classification (G5).
	 */
	recordAutonomyClassification(
		level: string,
		riskLevel: string,
		summary: string,
		options?: { planExecId?: string; workspaceId?: string; detail?: Record<string, unknown> },
	): LedgerEntry {
		return this.record("g5_budget_policy_engine", "autonomy_classification", "info", summary, {
			planExecId: options?.planExecId,
			workspaceId: options?.workspaceId,
			detail: { autonomyLevel: level, riskLevel, ...options?.detail },
		});
	}

	/**
	 * Record a safety report (G6).
	 */
	recordSafetyReport(
		issueCount: number,
		criticalCount: number,
		summary: string,
		options?: { planExecId?: string; workspaceId?: string; detail?: Record<string, unknown> },
	): LedgerEntry {
		const severity: LedgerEventSeverity = criticalCount > 0 ? "critical" : issueCount > 0 ? "warning" : "info";
		return this.record("g6_safety_simulation_queue", "safety_report", severity, summary, {
			planExecId: options?.planExecId,
			workspaceId: options?.workspaceId,
			detail: { issueCount, criticalCount, ...options?.detail },
		});
	}

	/**
	 * Record a simulation forecast (G6).
	 */
	recordSimulationForecast(
		totalBatches: number,
		estimatedUtilization: number,
		summary: string,
		options?: { planExecId?: string; workspaceId?: string; detail?: Record<string, unknown> },
	): LedgerEntry {
		return this.record("g6_safety_simulation_queue", "simulation_forecast", "info", summary, {
			planExecId: options?.planExecId,
			workspaceId: options?.workspaceId,
			detail: { totalBatches, estimatedUtilization, ...options?.detail },
		});
	}

	/**
	 * Record a queue audit entry (G6).
	 */
	recordQueueAudit(
		action: string,
		workspaceId: string | undefined,
		summary: string,
		options?: { planExecId?: string; detail?: Record<string, unknown> },
	): LedgerEntry {
		return this.record("g6_safety_simulation_queue", "queue_audit", "info", summary, {
			planExecId: options?.planExecId,
			workspaceId,
			detail: { queueAction: action, ...options?.detail },
		});
	}

	/**
	 * Record a change request event (G3).
	 */
	recordChangeRequest(
		action: "submitted" | "approved" | "rejected",
		requestId: string,
		summary: string,
		options?: { planExecId?: string; workspaceId?: string; detail?: Record<string, unknown> },
	): LedgerEntry {
		const severity: LedgerEventSeverity = action === "rejected" ? "warning" : "info";
		return this.record("g3_approval_budget", "change_request", severity, summary, {
			planExecId: options?.planExecId,
			workspaceId: options?.workspaceId,
			detail: { requestId, action, ...options?.detail },
		});
	}

	/**
	 * Record a self-modification event (G3).
	 */
	recordSelfModification(
		approved: boolean,
		affectedPaths: string[],
		summary: string,
		options?: { planExecId?: string; workspaceId?: string; detail?: Record<string, unknown> },
	): LedgerEntry {
		const severity: LedgerEventSeverity = approved ? "warning" : "critical";
		return this.record("g3_approval_budget", "self_modification", severity, summary, {
			planExecId: options?.planExecId,
			workspaceId: options?.workspaceId,
			detail: { approved, affectedPaths, ...options?.detail },
		});
	}

	// -----------------------------------------------------------------------
	// Completion Gate
	// -----------------------------------------------------------------------

	/**
	 * Record a completion gate evaluation.
	 *
	 * This MUST be called before marking any workspace or plan complete.
	 * The completion gate requires a complete ledger entry to proceed.
	 *
	 * @param passed - Whether the gate passed
	 * @param blockReasons - Reasons the gate blocked (empty if passed)
	 * @param options - Optional context
	 * @returns The completion gate record
	 */
	recordCompletionGate(
		passed: boolean,
		blockReasons: string[] = [],
		options?: {
			planExecId?: string;
			workspaceId?: string;
			workspaceIds?: string[];
		},
	): CompletionGateRecord {
		const entry = this.record(
			"g7_governance_ledger",
			"completion_gate",
			passed ? "info" : "error",
			passed
				? "Completion gate passed — all checks satisfied"
				: `Completion gate blocked: ${blockReasons.join("; ")}`,
			{
				planExecId: options?.planExecId,
				workspaceId: options?.workspaceId,
				detail: {
					passed,
					blockReasons,
					workspaceIds: options?.workspaceIds,
				},
			},
		);

		this._completionGate = {
			entry,
			passed,
			blockReasons,
			workspaceIds: options?.workspaceIds,
		};

		return this._completionGate;
	}

	/**
	 * Check whether a plan can proceed through the completion gate.
	 * Requires at least one ledger entry (a "complete entry") and
	 * that no blocking conditions exist.
	 *
	 * @param _options - Optional context (planExecId, workspaceId, workspaceIds)
	 *   for recording context in the completion gate entry if one is created.
	 * @returns Object with passed flag and block reasons
	 */
	checkCompletionGate(_options?: { planExecId?: string; workspaceId?: string; workspaceIds?: string[] }): {
		passed: boolean;
		blockReasons: string[];
	} {
		const blockReasons: string[] = [];

		// Require at least one ledger entry
		if (this._entries.length === 0) {
			blockReasons.push("Governance ledger is empty — no entries recorded");
		}

		// Require no critical errors without a resolution
		const unresolvedCritical = this._entries.filter((e) => e.severity === "critical" || e.severity === "error");
		if (unresolvedCritical.length > 0) {
			blockReasons.push(`Governance ledger has ${unresolvedCritical.length} unresolved error/critical entries`);
		}

		// Require no validation failures without resolution
		const unresolvedFailures = this._entries.filter(
			(e) => e.category === "validation_failure" && e.severity === "error",
		);
		if (unresolvedFailures.length > 0) {
			blockReasons.push(`Governance ledger has ${unresolvedFailures.length} unresolved validation failures`);
		}

		// Require at least one entry from each of G3, G4 if the lifecycle has progressed
		// (This is a soft check - we record it as info but don't block on it)
		const hasApprovalEntries = this._entries.some((e) => e.source === "g3_approval_budget");
		const hasValidationEntries = this._entries.some((e) => e.source === "g4_dry_run_validation");

		if (!hasApprovalEntries) {
			blockReasons.push("No approval entries (G3) recorded in governance ledger");
		}

		if (!hasValidationEntries) {
			blockReasons.push("No validation entries (G4) recorded in governance ledger");
		}

		const passed = blockReasons.length === 0;
		return { passed, blockReasons };
	}

	// -----------------------------------------------------------------------
	// Summary
	// -----------------------------------------------------------------------

	/**
	 * Compute a summary of the current ledger state.
	 */
	computeSummary(): LedgerSummary {
		const bySource: Partial<Record<LedgerSource, number>> = {};
		const byCategory: Partial<Record<LedgerEventCategory, number>> = {};
		const bySeverity: Partial<Record<LedgerEventSeverity, number>> = {};

		let criticalCount = 0;

		for (const entry of this._entries) {
			bySource[entry.source] = (bySource[entry.source] ?? 0) + 1;
			byCategory[entry.category] = (byCategory[entry.category] ?? 0) + 1;
			bySeverity[entry.severity] = (bySeverity[entry.severity] ?? 0) + 1;

			if (entry.severity === "critical" || entry.severity === "error") {
				criticalCount++;
			}
		}

		return {
			totalEntries: this._entries.length,
			bySource,
			byCategory,
			bySeverity,
			criticalEntries: criticalCount,
			completionGatePassed: this._completionGate?.passed === true,
			firstEntryAt: this._entries.length > 0 ? this._entries[0].timestamp : undefined,
			lastEntryAt: this._entries.length > 0 ? this._entries[this._entries.length - 1].timestamp : undefined,
		};
	}

	/**
	 * Take a full snapshot of the ledger.
	 */
	snapshot(): GovernanceLedgerSnapshot {
		return {
			entries: [...this._entries],
			summary: this.computeSummary(),
			completionGate: this._completionGate,
			createdAt: this._createdAt,
			updatedAt: this._entries.length > 0 ? this._entries[this._entries.length - 1].timestamp : this._createdAt,
		};
	}

	/**
	 * Clear all entries (for testing / reset).
	 */
	clear(): void {
		this._entries = [];
		this._completionGate = undefined;
	}
}

// ---------------------------------------------------------------------------
// Factory Function
// ---------------------------------------------------------------------------

/**
 * Create a new governance ledger instance.
 */
export function createGovernanceLedger(): GovernanceLedger {
	return new GovernanceLedger();
}

/**
 * Safety Profiles - P5 Workstream 5.E
 *
 * Defines safety profiles (Strict, Balanced, Full Auto) that control
 * what commands and operations the agent is allowed to execute.
 *
 * Strict (default): Most restrictive. Blocks all dangerous commands,
 *   requires confirmation for any shell execution.
 * Balanced: Allows common development commands, blocks destructive ones,
 *   requires confirmation for deployment/publish operations.
 * Full Auto: Least restrictive. All commands allowed but explicit
 *   confirmation required for destructive operations (git push, rm -rf).
 *
 * ALL profiles block: git push, rm -rf
 */

// =============================================================================
// Types
// =============================================================================

/**
 * Safety profile names.
 *
 * - "strict"    : Maximum safety, confirmation required for most operations
 * - "balanced"  : Moderate safety, common dev operations allowed
 * - "full_auto" : Minimal restrictions, explicit confirmation for destructive ops
 */
export type SafetyProfileName = "strict" | "balanced" | "full_auto";

/**
 * Permission level for a command or operation category.
 *
 * - "blocked"       : Command is completely blocked
 * - "confirm"       : Command requires explicit user confirmation before execution
 * - "allowed"       : Command is allowed without confirmation
 */
export type PermissionLevel = "blocked" | "confirm" | "allowed";

/**
 * Permission rule for a command pattern.
 */
export interface PermissionRule {
	/** Glob or regex pattern for matching commands */
	pattern: string;
	/** Permission level for this pattern */
	level: PermissionLevel;
	/** Human-readable description */
	description: string;
	/** Whether this rule applies to subcommands (default: true) */
	includesSubcommands?: boolean;
}

/**
 * File permission rule for path patterns.
 */
export interface FilePermissionRule {
	/** Glob pattern for matching file paths */
	pattern: string;
	/** Permission level */
	level: PermissionLevel;
	/** Human-readable description */
	description: string;
}

/**
 * Effective permissions computed from a safety profile.
 */
export interface EffectivePermissions {
	/** Profile name */
	profile: SafetyProfileName;
	/** Shell command permission rules */
	commandRules: PermissionRule[];
	/** File access permission rules */
	fileRules: FilePermissionRule[];
	/** Whether shell commands require confirmation by default */
	defaultShellConfirmation: boolean;
	/** Whether file writes require confirmation by default */
	defaultFileWriteConfirmation: boolean;
	/** Whether plan execution requires confirmation */
	planExecutionConfirmation: boolean;
	/** Maximum allowed parallel workspace count (0 = unlimited) */
	maxParallelWorkspaces: number;
	/** Whether Full Auto explicit confirmation is required */
	fullAutoExplicitConfirmation: boolean;
}

/**
 * Result of checking a command against a safety profile.
 */
export interface CommandCheckResult {
	/** Whether the command is allowed */
	allowed: boolean;
	/** Permission level for this command */
	level: PermissionLevel;
	/** Human-readable reason */
	reason: string;
	/** Which rule was matched (if any) */
	matchedRule?: PermissionRule;
}

/**
 * Result of checking a file operation against a safety profile.
 */
export interface FileCheckResult {
	/** Whether the operation is allowed */
	allowed: boolean;
	/** Permission level */
	level: PermissionLevel;
	/** Human-readable reason */
	reason: string;
	/** Which rule was matched (if any) */
	matchedRule?: FilePermissionRule;
}

// =============================================================================
// Globally Blocked Commands (All Profiles)
// =============================================================================

/**
 * Commands that are BLOCKED in ALL safety profiles.
 * These are always dangerous and should never be executed without
 * at minimum explicit confirmation.
 */
export const ALWAYS_BLOCKED_COMMANDS: PermissionRule[] = [
	{
		pattern: "rm -rf",
		level: "blocked",
		description: "Recursive force delete - can destroy entire directories",
	},
	{
		pattern: "rm -fr",
		level: "blocked",
		description: "Recursive force delete (alternate flag order)",
	},
	{
		pattern: "rm --recursive --force",
		level: "blocked",
		description: "Recursive force delete (long flags)",
	},
	{
		pattern: "git push",
		level: "blocked",
		description: "Pushing to remote repository - can affect shared state",
	},
];

/**
 * Additional destructive commands that are blocked in Strict and Balanced
 * profiles but require explicit confirmation in Full Auto.
 */
export const DESTRUCTIVE_COMMANDS: PermissionRule[] = [
