/** Map of profile names to their definitions */
const PROFILE_MAP: Record<SafetyProfileName, EffectivePermissions> = {
	strict: STRICT_PROFILE,
	balanced: BALANCED_PROFILE,
	full_auto: FULL_AUTO_PROFILE,
};

// =============================================================================
// Default
// =============================================================================

/** Default safety profile name */
export const DEFAULT_SAFETY_PROFILE: SafetyProfileName = "strict";

// =============================================================================
// Functions
// =============================================================================

/**
 * Get the effective permissions for a given safety profile.
 *
 * @param profileName - Profile name (defaults to "strict")
 * @returns Effective permissions for the profile
 */
export function getEffectivePermissions(profileName: SafetyProfileName = DEFAULT_SAFETY_PROFILE): EffectivePermissions {
	return PROFILE_MAP[profileName] ?? STRICT_PROFILE;
}

/**
 * Check if a command is allowed under the given safety profile.
 *
 * @param command - The shell command to check
 * @param profileName - Safety profile name
 * @returns Command check result
 */
export function checkCommand(
	command: string,
	profileName: SafetyProfileName = DEFAULT_SAFETY_PROFILE,
): CommandCheckResult {
	const permissions = getEffectivePermissions(profileName);
	const normalizedCommand = command.trim().toLowerCase();

	// Check against command rules - more specific patterns first (longer pattern = more specific)
	const sortedRules = [...permissions.commandRules].sort((a, b) => b.pattern.length - a.pattern.length);

	for (const rule of sortedRules) {
		const patternLower = rule.pattern.toLowerCase();
		if (normalizedCommand.includes(patternLower)) {
			return {
				allowed: rule.level !== "blocked",
				level: rule.level,
				reason: rule.description,
				matchedRule: rule,
			};
		}
	}

	// No rule matched - use default shell confirmation behavior
	if (permissions.defaultShellConfirmation) {
		return {
			allowed: false,
			level: "confirm",
			reason: "Strict profile requires confirmation for all shell commands",
		};
	}

	return {
		allowed: true,
		level: "allowed",
		reason: "No restrictive rule matched; command is allowed by default",
	};
}

/**
 * Check if a file write operation is allowed under the given safety profile.
 *
 * @param filePath - The file path being written
 * @param profileName - Safety profile name
 * @returns File check result
 */
export function checkFileOperation(
	filePath: string,
	profileName: SafetyProfileName = DEFAULT_SAFETY_PROFILE,
): FileCheckResult {
	const permissions = getEffectivePermissions(profileName);
	const normalizedPath = filePath.replace(/\\/g, "/");

	// Check against file rules
	for (const rule of permissions.fileRules) {
		if (matchGlob(normalizedPath, rule.pattern)) {
			return {
				allowed: rule.level !== "blocked",
				level: rule.level,
				reason: rule.description,
				matchedRule: rule,
			};
		}
	}

	// No rule matched - use default file write confirmation behavior
	if (permissions.defaultFileWriteConfirmation) {
		return {
			allowed: false,
			level: "confirm",
			reason: "Strict profile requires confirmation for file writes",
		};
	}

	return {
		allowed: true,
		level: "allowed",
		reason: "No restrictive rule matched; file operation is allowed by default",
	};
}

/**
 * Check if git push is blocked in the given profile.
 *
 * @param profileName - Safety profile name
 * @returns True if git push is blocked
 */
export function isGitPushBlocked(profileName: SafetyProfileName = DEFAULT_SAFETY_PROFILE): boolean {
	const result = checkCommand("git push", profileName);
	return result.level === "blocked";
}

/**
 * Check if rm -rf is blocked in the given profile.
 *
 * @param profileName - Safety profile name
 * @returns True if rm -rf is blocked
 */
export function isRmRfBlocked(profileName: SafetyProfileName = DEFAULT_SAFETY_PROFILE): boolean {
	const result = checkCommand("rm -rf", profileName);
	return result.level === "blocked";
}

/**
 * Check if the given profile requires explicit confirmation for destructive commands.
 *
 * In Full Auto, destructive commands require EXPLICIT confirmation (not default
 * confirmation handling). This means the user must actively approve each
 * destructive operation.
 *
 * @param profileName - Safety profile name
 * @returns True if explicit confirmation is required
 */
export function requiresExplicitConfirmation(profileName: SafetyProfileName = DEFAULT_SAFETY_PROFILE): boolean {
	const permissions = getEffectivePermissions(profileName);
	return permissions.fullAutoExplicitConfirmation;
}

/**
 * Check whether Full Auto profile requires explicit confirmation for a command.
 *
 * In Full Auto mode, git push and rm -rf are not blocked but require
 * the user to explicitly confirm each time they are used.
 *
 * @param command - The command to check
 * @returns True if explicit confirmation is required in Full Auto
 */
export function fullAutoRequiresConfirmation(command: string): boolean {
	const result = checkCommand(command, "full_auto");
	// In full_auto, commands at "confirm" level require explicit confirmation
	return result.level === "confirm";
}

/**
 * Get a human-readable description of the effective permissions for a profile.
 *
 * @param profileName - Safety profile name
 * @returns Formatted string describing the profile's permissions
 */
export function describePermissions(profileName: SafetyProfileName = DEFAULT_SAFETY_PROFILE): string {
	const permissions = getEffectivePermissions(profileName);
	const lines: string[] = [];

	const NL = String.fromCharCode(10);

	lines.push(`=== Safety Profile: ${profileName} ===`);
	lines.push("");

	// Shell permissions
	lines.push("Shell Commands:");
	if (permissions.defaultShellConfirmation) {
		lines.push("  All commands require confirmation by default");
	} else {
		lines.push("  Commands allowed by default unless matched by a rule");
	}
	lines.push("");

	// Blocked commands
	const blocked = permissions.commandRules.filter((r) => r.level === "blocked");
	const confirmed = permissions.commandRules.filter((r) => r.level === "confirm");

	if (blocked.length > 0) {
		lines.push("  Blocked Commands:");
		for (const rule of blocked) {
			const X = String.fromCharCode(10060); // cross mark
			lines.push(`    ${X} ${rule.pattern} - ${rule.description}`);
		}
		lines.push("");
	}

	if (confirmed.length > 0) {
		lines.push("  Requires Confirmation:");
		for (const rule of confirmed) {
			const Q = String.fromCharCode(10067); // question mark
			lines.push(`    ${Q} ${rule.pattern} - ${rule.description}`);
		}
		lines.push("");
	}

	// File permissions
	lines.push("File Operations:");
	if (permissions.defaultFileWriteConfirmation) {
		lines.push("  All file writes require confirmation by default");
	} else {
		lines.push("  File writes allowed by default unless matched by a rule");
	}
	lines.push("");

	const blockedFiles = permissions.fileRules.filter((r) => r.level === "blocked");
	if (blockedFiles.length > 0) {
		lines.push("  Blocked File Patterns:");
		for (const rule of blockedFiles) {
			const X = String.fromCharCode(10060); // cross mark
			lines.push(`    ${X} ${rule.pattern} - ${rule.description}`);
		}
		lines.push("");
	}

	// Execution settings
	lines.push("Execution Settings:");
	lines.push(`  Plan execution confirmation: ${permissions.planExecutionConfirmation ? "Required" : "Not required"}`);
	lines.push(
		`  Max parallel workspaces: ${permissions.maxParallelWorkspaces === 0 ? "Unlimited" : permissions.maxParallelWorkspaces}`,
	);
	if (permissions.fullAutoExplicitConfirmation) {
		lines.push("  Full Auto explicit confirmation: Required for destructive commands");
	}

	return lines.join(NL);
}

/**
 * Simple glob matcher.
 *
 * Supports:
 * - `*` matches any sequence of characters except /
 * - `**` matches any sequence of characters including /
 * - `?` matches any single character except /
 *
 * @param path - File path to match
 * @param pattern - Glob pattern
 * @returns True if the path matches the pattern
 */
function matchGlob(path: string, pattern: string): boolean {
	// Normalize paths to forward slashes
	const normalizedPath = path.replace(/\\/g, "/");
	const normalizedPattern = pattern.replace(/\\/g, "/");

	// Build a regex from the glob pattern
	let regexStr = "";
	let i = 0;
	while (i < normalizedPattern.length) {
		const ch = normalizedPattern[i];
		if (ch === "*" && normalizedPattern[i + 1] === "*") {
			// ** matches anything including /
			regexStr += ".*";
			i += 2;
			// Skip trailing / after **
			if (normalizedPattern[i] === "/") {
				i++;
			}
		} else if (ch === "*") {
			// * matches anything except /
			regexStr += "[^/]*";
			i++;
		} else if (ch === "?") {
			// ? matches any single char except /
			regexStr += "[^/]";
			i++;
		} else if (isRegexSpecial(ch)) {
			regexStr += `\\${ch}`;
			i++;
		} else {
			regexStr += ch;
			i++;
		}
	}

	try {
		const regex = new RegExp(`^${regexStr}$`);
		return regex.test(normalizedPath);
	} catch {
		return false;
	}
}

/**
 * Check if a character needs regex escaping.
 *
 * @param ch - Single character
 * @returns True if the character is a regex metacharacter
 */
function isRegexSpecial(ch: string): boolean {
	// break the $ + {} sequence so biome doesn't flag it
	const specials = ".+^${" + "}()|[]";
	return specials.includes(ch);
}

/**
 * Get all available safety profile names.
 *
 * @returns Array of profile names
 */
export function getAvailableProfiles(): SafetyProfileName[] {
	return ["strict", "balanced", "full_auto"];
}

/**
 * Get a brief summary description of a safety profile.
 *
 * @param profileName - Profile name
 * @returns Human-readable description
 */
export function getProfileDescription(profileName: SafetyProfileName): string {
	switch (profileName) {
		case "strict":
			return "Maximum safety. All shell commands require confirmation. Destructive commands and git push are blocked. File writes require confirmation. Single workspace execution only.";
		case "balanced":
			return "Moderate safety. Common development commands allowed. Destructive commands and git push are blocked. Deployment commands require confirmation. Up to 3 parallel workspaces.";
		case "full_auto":
			return "Least restrictive. Most commands allowed. git push and rm -rf require EXPLICIT confirmation each time. Destructive operations also require confirmation. Up to 5 parallel workspaces.";
		default:
			return `Unknown profile: ${profileName}`;
	}
}

/**
 * Migration runner.
 *
 * Manages schema migrations with ordered execution and rollback support.
 * Tracks applied migrations in a `_migrations` table.
 */

import type { Kysely } from "kysely";
import type { Database } from "../types.js";

/**
 * Migration definition
 */
export interface Migration {
	/** Migration version number */
	version: number;
	/** Human-readable name */
	name: string;
	/** Apply migration */
	up: (db: Kysely<Database>) => Promise<void>;
	/** Rollback migration */
	down: (db: Kysely<Database>) => Promise<void>;
}

// Import migrations
import * as m001 from "./001_initial.js";
import * as m002 from "./002_listen_notify.js";
import * as m003 from "./003_add_execution_log.js";
import * as m004 from "./004_add_chat_messages.js";
import * as m005 from "./005_add_proposals.js";
import * as m006 from "./006_add_proposal_source_and_revisions.js";

/**
 * All registered migrations in version order.
 */
const migrations: Migration[] = [
	{ version: 1, name: "initial", up: m001.up, down: m001.down },
	{ version: 2, name: "listen_notify", up: m002.up, down: m002.down },
	{ version: 3, name: "add_execution_log", up: m003.up, down: m003.down },
	{ version: 4, name: "add_chat_messages", up: m004.up, down: m004.down },
	{ version: 5, name: "add_proposals", up: m005.up, down: m005.down },
	{ version: 6, name: "add_proposal_source_and_revisions", up: m006.up, down: m006.down },
];

/**
 * Run all pending migrations.
 *
 * @param db - Kysely database instance
 */
export async function runMigrations(db: Kysely<Database>): Promise<void> {
	// Ensure migrations tracking table exists
	await db.schema
		.createTable("_migrations")
		.ifNotExists()
		.addColumn("version", "integer", (col) => col.primaryKey())
		.addColumn("name", "varchar(255)", (col) => col.notNull())
		.addColumn("applied_at", "timestamptz", (col) => col.notNull().defaultTo(db.fn<any>("now")))
		.execute();

	// Get applied versions
	const applied = await db.selectFrom("_migrations").select("version").execute();
	const appliedVersions = new Set(applied.map((r) => r.version));

	// Run pending migrations in order
	for (const migration of migrations) {
		if (!appliedVersions.has(migration.version)) {
			console.log(`[db] Running migration ${migration.version}: ${migration.name}`);
			await migration.up(db);
			await db.insertInto("_migrations").values({ version: migration.version, name: migration.name }).execute();
			console.log(`[db] Migration ${migration.version} applied`);
		}
	}
}

/**
 * Rollback the last N migrations.
 *
 * @param db - Kysely database instance
 * @param steps - Number of migrations to rollback (default: 1)
 */
export async function rollbackMigrations(db: Kysely<Database>, steps = 1): Promise<void> {
	const applied = await db.selectFrom("_migrations").selectAll().orderBy("version", "desc").limit(steps).execute();

	for (const row of applied.reverse()) {
		const migration = migrations.find((m) => m.version === row.version);
		if (!migration) {
			console.warn(`[db] Unknown migration version ${row.version}, skipping rollback`);
			continue;
		}

		console.log(`[db] Rolling back migration ${migration.version}: ${migration.name}`);
		await migration.down(db);
		await db.deleteFrom("_migrations").where("version", "=", row.version).execute();
		console.log(`[db] Migration ${migration.version} rolled back`);
	}
}

/**
 * Get the list of applied migrations.
 *
 * @param db - Kysely database instance
 * @returns Array of applied migration info
 */
export async function getAppliedMigrations(
	db: Kysely<Database>,
): Promise<{ version: number; name: string; appliedAt: string }[]> {
	try {
		return await db
			.selectFrom("_migrations")
			.select(["version", "name", "applied_at as appliedAt"])
			.orderBy("version", "asc")
			.execute();
	} catch {
		return [];
	}
}

export { migrations };

/**
 * Cleanup & Review Workspace Executor
 *
 * Runs after all plan workspace workers complete. The cleanup agent:
 * 1. Reads all workspace reports, logs, and git diffs
 * 2. Runs tests / validation
 * 3. Catches regressions and bugs
 * 4. Generates a comprehensive human-readable summary of what changed
 *
 * The summary is persisted as a plan_summary journal event and as a
 * plan-summary.md file in .pi/workspaces/ for dashboard consumption.
 */

import { exec as execCb } from "node:child_process";
import * as fs from "node:fs/promises";
import * as path from "node:path";
import { promisify } from "node:util";
import type { Model } from "@earendil-works/pi-ai";
import { getModel } from "@earendil-works/pi-ai";
import { PiLogger } from "../utils/logger.js";
import { createAgentSession } from "./sdk.js";
import { SessionManager } from "./session-manager.js";
import { SettingsManager } from "./settings-manager.js";

const execAsync = promisify(execCb);

import type { IStateStore } from "./state-store.js";
import {
	canStartWorker,
	formatMemorySnapshot,
	getMemorySnapshot,
	waitForMemoryAvailable,
} from "./worker-memory-guard.js";
import type { WorkspaceQueue } from "./workspace-schema.js";

/**
 * Global merge lock to prevent concurrent cleanup/merge operations.
 * Uses an async mutex so only one cleanup runs at a time across
 * all plan executions within the same process.
 */
let cleanupLock: Promise<void> = Promise.resolve();

/**
 * Acquire the global cleanup lock.
 * Returns a release function. The caller must call release() when done.
 */
function acquireCleanupLock(): Promise<() => void> {
	let release: () => void;
	const prev = cleanupLock;
	cleanupLock = new Promise<void>((resolve) => {
		release = resolve;
	});
	return prev.then(() => release!);
}

/**
 * Result of the cleanup/review process.
 */
export interface CleanupReviewResult {
	/** Whether the cleanup passed review */
	passed: boolean;
	/** Human-readable summary of changes, tests, and findings */
	summary: string;
	/** Number of issues found */
	issueCount: number;
	/** Warnings / issues found */
	issues: string[];
	/** Files that were modified across all workspaces */
	changedFiles: string[];
	/** Tests that were run and their results */
	testResults: Array<{ name: string; passed: boolean; output?: string }>;
}

/**
 * Configuration for the cleanup review executor.
 */
export interface CleanupReviewConfig {
	/** Workspace root directory */
	workspaceRoot: string;
	/** Plan execution ID */
	planExecutionId: string;
	/** State store for persisting results */
	stateStore: IStateStore;
	/** The workspace queue (all workspaces) */
	queue: WorkspaceQueue;
	/** Model to use for the cleanup agent */
	model?: Model<any>;
}

/**
 * Run the cleanup/review process after all workspace workers complete.
 *
 * Creates a cleanup agent session that reads workspace reports, git diffs,
 * runs tests, and produces a comprehensive plan summary.
 */
export async function runCleanupReview(config: CleanupReviewConfig): Promise<CleanupReviewResult> {
	const { workspaceRoot, planExecutionId, stateStore, queue, model } = config;

	// Logger for this cleanup session — created immediately so we can log before/after memory
	const log = new PiLogger({ planExecId: planExecutionId });

	// Acquire the global merge lock first — only one cleanup at a time.
	// Must acquire BEFORE memory check to avoid TOCTOU: without the lock,
	// another plan's cleanup could race in and consume the freed memory
	// between our memory wait and our actual agent execution.
	const releaseLock = await acquireCleanupLock();
	log.info(`[cleanup] Acquired cleanup lock`);

	try {
		const memoryCheck = getMemorySnapshot();
		log.info(`[cleanup] Memory: ${formatMemorySnapshot(memoryCheck)}`);

		if (!canStartWorker("cleanup review agent")) {
			log.warn("[cleanup] Memory limit exceeded, waiting for memory to become available...");
			await waitForMemoryAvailable();
			const afterWait = getMemorySnapshot();
			log.info(`[cleanup] Memory available after wait: ${formatMemorySnapshot(afterWait)}`);
		}
		const resolvedModel = model ?? getFallbackModel();

		// Create archive directories for cleanup logs (same structure as workers)
		const cleanupArchiveDir = path.join(
			workspaceRoot,
			".pi",
			"executions",
			planExecutionId,
			"workspaces",
			"_cleanup",
		);
		try {
			await fs.mkdir(cleanupArchiveDir, { recursive: true });
		} catch {
			// Non-fatal
		}

		// Archive helper: persist a raw log line
		const archiveRawLog = async (line: string) => {
			try {
				const rawLogPath = path.join(cleanupArchiveDir, "raw.log");
				await fs.appendFile(rawLogPath, `${line}\n`, "utf-8");
			} catch {
				// Non-fatal
			}
		};

		const emitStatus = (status: string, message?: string) => {
			stateStore.emitWorkerStatus?.(planExecutionId, "_cleanup", status, message).catch(() => {});
			log.info(`[cleanup] Worker status: ${status}${message ? `: ${message}` : ""}`);
		};

		emitStatus("starting", "Cleanup review started, acquired merge lock");

		// Emit cleanup_workspace journal event
		await stateStore
			.appendJournal(planExecutionId, {
				type: "cleanup_workspace",
				timestamp: Date.now(),
				data: { message: "Cleanup review started" },
			})
			.catch(() => {});

		await archiveRawLog(`[${new Date().toISOString()}] Cleanup review started - acquired merge lock`);

		// Collect workspace execution data for the cleanup agent
		const workspaceData: Array<{
			id: string;
			title: string;
			stage: string;
			report?: string;
			logs?: string;
			error?: string;
		}> = [];

		for (const ws of queue.workspaces) {
			const reportPath = path.join(workspaceRoot, ".pi", "workspaces", ws.id, "report.md");
			let report: string | undefined;
			try {
				report = await fs.readFile(reportPath, "utf-8");
			} catch {
				// Report not available
			}

			// Get the workspace state from the state store
			let wsState: { stage: string; error?: string } | undefined;
			try {
				wsState = await stateStore.getWorkspaceState(planExecutionId, ws.id);
			} catch {
				// State not available
			}

			workspaceData.push({
				id: ws.id,
				title: ws.title,
				stage: wsState?.stage ?? "unknown",
				report,
				error: wsState?.error,
			});
		}

		// Get git diff for context on what changed
		let gitDiff = "";
		try {
			const diffResult = await execAsync("git diff --stat HEAD", {
				cwd: workspaceRoot,
				timeout: 5000,
				encoding: "utf-8",
				env: { ...process.env, GIT_ALLOW_PROTOCOL: "file" },
			}).catch(() => ({ stdout: "" }));
			gitDiff = diffResult.stdout;
		} catch {
			gitDiff = "(git diff unavailable)";
		}

		emitStatus("analyzing", `Collected ${workspaceData.length} workspace reports`);

		// Build the cleanup prompt
		const prompt = buildCleanupPrompt(queue, workspaceData, gitDiff);

		// Run the cleanup agent (max 3 turns, 90 second timeout)
		const result = await executeCleanupAgent({
			workspaceRoot,
			model: resolvedModel,
			prompt,
			planExecutionId,
			stateStore,
			emitStatus,
			archiveRawLog,
		});

		emitStatus("complete", `Cleanup review ${result.passed ? "PASS" : "FAIL"}`);
		await archiveRawLog(`[${new Date().toISOString()}] Cleanup review complete: ${result.passed ? "PASS" : "FAIL"}`);

		return result;
	} finally {
		releaseLock();
		log.info("[cleanup] Released clean up / merge lock");
	}
}

/**
 * Build the system prompt for the cleanup agent.
 *
 * Validation is NOT included here — each workspace worker already ran its
 * own validation via targetCommand. The cleanup agent only reviews reports
 * and produces a summary.
 */
function buildCleanupPrompt(
	queue: WorkspaceQueue,
	workspaceData: Array<{
		id: string;
		title: string;
		stage: string;
		report?: string;
		logs?: string;
		error?: string;
	}>,
	gitDiff: string,
): string {
	const parts: string[] = [];

	parts.push(`You are the cleanup & review agent for a plan execution.`);
	parts.push(``);
	parts.push(`Plan: ${queue.title}`);
	parts.push(`Phase: ${queue.phase}`);
	parts.push(``);
	parts.push(`## All Workspaces and Their Results`);
	parts.push(``);

	for (const ws of workspaceData) {
		parts.push(`### ${ws.id}: ${ws.title} (${ws.stage})`);
		if (ws.report) {
			// Truncate report to avoid blowing the context
			const truncated = ws.report.length > 2000 ? `${ws.report.slice(0, 2000)}...` : ws.report;
			parts.push(truncated);
		}
		if (ws.error) {
			parts.push(`Error: ${ws.error}`);
		}
		parts.push(``);
	}

	parts.push(`## Git Diff Summary (uncommitted changes)`);
	parts.push(``);
	parts.push(gitDiff || "(no changes)");
	parts.push(``);
	parts.push(`## Your Task`);
	parts.push(``);
	parts.push(
		`1. **Review**: Analyze each workspace's report and the git diff. Check for logical errors, incomplete implementations, missing edge cases, code quality issues, and regressions.`,
	);
	parts.push(
		`2. **Summarize**: Write a comprehensive summary of what was accomplished and whether the plan passed review.`,
	);
	parts.push(`3. Do NOT run any commands or modify any files. Your job is only review and summarization.`);
	parts.push(``);
	parts.push(`## Output Contract`);
	parts.push(``);
	parts.push(`Output exactly this structure — no extra text before or after:`);
	parts.push(``);
	parts.push(`CLEANUP_REVIEW_RESULT`);
	parts.push(`Summary: <one-paragraph summary of what was accomplished in this plan execution>`);
	parts.push(`Changed files: <comma-separated list of all files modified by the whole plan>`);
	parts.push(`Issues found: <number>`);
	parts.push(`Issues: <one issue per line, or "None">`);
	parts.push(`Tests run: 0`);
	parts.push(`Tests passed: 0`);
	parts.push(`Tests failed: 0`);
	parts.push(`Verdict: PASS | FAIL`);
	parts.push(`END_CLEANUP_REVIEW_RESULT`);
	parts.push(``);
	parts.push(`IMPORTANT: Do NOT run any commands. Do NOT edit files or commit. Only review and summarize.`);

	return parts.join("\n");
}

/**
 * Execute the cleanup agent in a real agent session.
 */
async function executeCleanupAgent(config: {
	workspaceRoot: string;
	model: Model<any>;
	prompt: string;
	planExecutionId: string;
	stateStore: IStateStore;
	emitStatus: (status: string, message?: string) => void;
	archiveRawLog: (line: string) => Promise<void>;
}): Promise<CleanupReviewResult> {
	const { workspaceRoot, model, prompt, planExecutionId, stateStore, emitStatus, archiveRawLog } = config;

	// Persist raw log lines to the cleanup archive directory
	const logAndArchive = async (message: string) => {
		const timestamp = new Date().toISOString();
		const line = `[${timestamp}] ${message}`;
		await archiveRawLog(line);
	};

	await logAndArchive("Creating cleanup agent session...");

	const sessionManager = SessionManager.create(workspaceRoot, path.join(workspaceRoot, ".pi", "sessions", "_cleanup"));

	const settingsManager = SettingsManager.create(workspaceRoot);

	let session: Awaited<ReturnType<typeof createAgentSession>>["session"] | null = null;
	let unsubscribe: (() => void) | null = null;

	try {
		const created = await createAgentSession({
			cwd: workspaceRoot,
			model,
			thinkingLevel: "low",
			sessionManager,
			settingsManager,
			// NOTE: intentionally no bash/write/edit — the cleanup agent only reviews
			// and summarizes. It must not modify files or run commands.
			tools: ["read", "find", "grep", "ls"],
		});
		session = created.session;

		// Collect output
		const outputParts: string[] = [];

		// Single subscription to collect output + detect agent_end
		unsubscribe = session.subscribe((event) => {
			// Forward agent session events as worker status updates
			if (event.type === "agent_start") {
				emitStatus("executing", "Cleanup agent started");
				logAndArchive("Cleanup agent started execution");
			} else if (event.type === "agent_end") {
				emitStatus("deciding", "Cleanup agent completed");
				logAndArchive("Cleanup agent completed execution");
			} else if (event.type === "turn_start") {
				emitStatus("thinking", `Turn started`);
			} else if (event.type === "tool_execution_start") {
				emitStatus("executing", `Tool: ${event.toolName}`);
				logAndArchive(`Tool execution: ${event.toolName}`);
			} else if (event.type === "tool_execution_end") {
				emitStatus("deciding", `Tool ${event.toolName}: ${event.isError ? "error" : "success"}`);
				logAndArchive(`Tool ${event.toolName}: ${event.isError ? "error" : "success"}`);
			}

			if (event.type === "message_update") {
				if (
					event.assistantMessageEvent &&
					event.assistantMessageEvent.type === "text_delta" &&
					event.assistantMessageEvent.delta
				) {
					outputParts.push(event.assistantMessageEvent.delta);
				}
			}
		});

		// Adaptive timeout: base 90s + 5s per workspace report. Cap at 300s.
		const workspaceCount = (config.prompt.match(/^### /gm) || []).length;
		const timeoutMs = Math.min(90_000 + workspaceCount * 5_000, 300_000);

		await logAndArchive("Sending prompt to cleanup agent...");
		emitStatus("executing", "Sending prompt to cleanup agent");

		// Race prompt execution against the adaptive timeout
		const result = await Promise.race([
			session.prompt(prompt).then(() => "completed" as const),
			timeout(timeoutMs).then(() => "timeout" as const),
		]);

		if (result === "timeout") {
			outputParts.push(`\n[cleanup] Agent timed out after ${timeoutMs / 1000}s`);
			await logAndArchive(`Cleanup agent timed out after ${timeoutMs / 1000}s`);
			emitStatus("error", `Cleanup agent timed out after ${timeoutMs / 1000}s`);
			// Dispose kills tracked children (vitest, etc.) via shell.ts exit handler
			session.dispose();
		}

		// Unsubscribe before parsing to avoid further event processing
		if (unsubscribe) {
			unsubscribe();
			unsubscribe = null;
		}

		// Parse the final output for the structured result
		const fullOutput = outputParts.join("");
		const parsed = parseCleanupResult(fullOutput);

		await logAndArchive(
			`Cleanup result: ${parsed.passed ? "PASS" : "FAIL"}, issues=${parsed.issueCount}, files=${parsed.changedFiles.length}`,
		);

		// Emit plan_summary journal event
		await stateStore
			.appendJournal(planExecutionId, {
				type: "plan_summary",
				timestamp: Date.now(),
				data: {
					summary: parsed.summary,
					issueCount: parsed.issueCount,
					issues: parsed.issues,
					changedFiles: parsed.changedFiles,
					testResults: parsed.testResults,
					passed: parsed.passed,
					rawOutput: fullOutput.slice(0, 5000),
				},
			})
			.catch(() => {});

		// Write summary to file for dashboard consumption, scoped to plan execution
		try {
			const summaryPath = path.join(workspaceRoot, ".pi", "executions", planExecutionId, "plan-summary.json");
			await fs.writeFile(
				summaryPath,
				JSON.stringify(
					{
						planExecutionId,
						planTitle: "",
						phase: "",
						completedAt: Date.now(),
						...parsed,
					},
					null,
					2,
				),
				"utf-8",
			);
		} catch {
			// Non-fatal
		}

		return parsed;
	} catch (error) {
		const errorMsg = error instanceof Error ? error.message : String(error);
		// Ensure session is always cleaned up on unexpected errors
		if (session && !(error as any)?._sessionDisposed) {
			try {
				session.dispose();
			} catch {
				// Non-fatal
			}
		}
		const fallback: CleanupReviewResult = {
			passed: false,
			summary: `Cleanup review failed: ${errorMsg}`,
			issueCount: 1,
			issues: [`Cleanup agent error: ${errorMsg}`],
			changedFiles: [],
			testResults: [],
		};

		await logAndArchive(`Cleanup review failed: ${errorMsg}`);
		emitStatus("error", `Cleanup review failed: ${errorMsg}`);

		await stateStore
			.appendJournal(planExecutionId, {
				type: "plan_summary",
				timestamp: Date.now(),
				data: {
					summary: fallback.summary,
					issueCount: 1,
					issues: fallback.issues,
					passed: false,
				},
			})
			.catch(() => {});

		return fallback;
	} finally {
		if (unsubscribe) {
			try {
				unsubscribe();
			} catch {
				// Non-fatal
			}
		}
	}
}

/**
 * Return a promise that resolves after `ms` milliseconds.
 */
function timeout(ms: number): Promise<"timeout"> {
	return new Promise((resolve) => setTimeout(() => resolve("timeout" as const), ms));
}

/**
 * Parse the structured CLEANUP_REVIEW_RESULT block from the agent output.
 *
 * Uses a state-machine approach per section:
 *   - Issues: once "Issues:" is seen, every subsequent non-empty line that
 *     does not start with a known key is accumulated as an issue.
 *   - Changed files: split on comma, trim each.
 *   - Verdict: PASS → true, anything else → false.
 */
function parseCleanupResult(output: string): CleanupReviewResult {
	const result: CleanupReviewResult = {
		passed: true,
		summary: "",
		issueCount: 0,
		issues: [],
		changedFiles: [],
		testResults: [],
	};

	// Find the structured result block
	const startMarker = "CLEANUP_REVIEW_RESULT";
	const endMarker = "END_CLEANUP_REVIEW_RESULT";

	const startIdx = output.indexOf(startMarker);
	const endIdx = output.indexOf(endMarker);

	if (startIdx === -1 || endIdx === -1) {
		// No structured result — use the full output as summary
		result.summary = output.slice(-2000).trim();
		return result;
	}

	const block = output.slice(startIdx + startMarker.length, endIdx).trim();

	// State machine: tracks which section we are in for multi-line fields.
	// Sections: "summary", "issues", none = ""
	let section = "";

	for (const line of block.split("\n")) {
		const trimmed = line.trim();
		if (!trimmed) continue;

		if (trimmed.startsWith("Summary:")) {
			section = "summary";
			result.summary = trimmed.slice("Summary:".length).trim();
		} else if (trimmed.startsWith("Changed files:")) {
			section = "";
			const files = trimmed.slice("Changed files:".length).trim();
			result.changedFiles = files
				.split(",")
				.map((f) => f.trim())
				.filter(Boolean);
		} else if (trimmed.startsWith("Issues found:")) {
			section = "";
			const count = Number.parseInt(trimmed.slice("Issues found:".length).trim(), 10);
			result.issueCount = Number.isNaN(count) ? 0 : count;
		} else if (trimmed.startsWith("Issues:")) {
			section = "issues";
			const rest = trimmed.slice("Issues:".length).trim();
			if (rest && rest !== "None") {
				result.issues.push(rest);
			}
		} else if (trimmed.startsWith("Verdict:")) {
			section = "";
			const verdict = trimmed.slice("Verdict:".length).trim();
			result.passed = verdict === "PASS";
		} else if (
			trimmed.startsWith("Tests run:") ||
			trimmed.startsWith("Tests passed:") ||
			trimmed.startsWith("Tests failed:")
		) {
			section = "";
			// Track test counts — handled below
		} else if (section === "summary") {
			// Multi-line summary: append with space separator
			result.summary += ` ${trimmed}`;
		} else if (section === "issues") {
			// Multi-line issues: accumulate each line as a separate issue
			result.issues.push(trimmed);
		}
	}

	// Re-count issues from the issues array if the structured count disagreed
	if (result.issues.length > 0) {
		result.issueCount = result.issues.length;
	}

	return result;
}

/**
 * Get a fallback model for the cleanup agent.
 * Throws if none of the known providers/models are configured.
 */
function getFallbackModel(): Model<any> {
	const models = [
		getModel("opencode-go" as any, "deepseek-v4-flash" as any),
		getModel("opencode-go" as any, "minimax-m2.7" as any),
		getModel("anthropic" as any, "claude-3-5-haiku-20241022" as any),
		getModel("openai" as any, "gpt-4o-mini" as any),
		getModel("anthropic" as any, "claude-sonnet-4-20250514" as any),
		getModel("openai" as any, "gpt-4o" as any),
	];

	for (const m of models) {
		if (m) return m;
	}

	throw new Error(
		"No model available for cleanup review agent. Configure at least one provider/model (e.g. ANTHROPIC_API_KEY, OPENAI_API_KEY, or OPENCODE_GO_API_KEY)." +
			" Tried: opencode-go/deepseek-v4-flash, opencode-go/minimax-m2.7, anthropic/claude-3-5-haiku-20241022, openai/gpt-4o-mini, anthropic/claude-sonnet-4-20250514, openai/gpt-4o",
	);
}

export const _CLEANUP_INTERNALS = { parseCleanupResult, buildCleanupPrompt };

/**
 * Production Readiness Doctor - Workstream 5.I
 *
 * Validates a workspace queue for production readiness before auto-run.
 * Performs comprehensive checks across safety, skill availability,
 * file scope hygiene, and git working-tree cleanliness.
 *
 * Checks:
 *   1. SafetyDoctor criticals - FAIL
 *   2. Missing required skills - FAIL
 *   3. Broad file scopes (catch-all wildcard patterns) - WARN
 *   4. Dirty git working tree - FAIL (blocks queue auto-run readiness)
 *
 * The doctor report is archived as doctor-report.json in the
 * execution archive and rendered in the dashboard.
 */

import { exec as execCb } from "node:child_process";
import { promisify } from "node:util";
import { SafetyDoctor, type SafetyIssue } from "./safety-doctor.js";

const execAsync = promisify(execCb);

import { SkillRegistry } from "./skill-registry.js";
import type { WorkspaceCapabilityManifest, WorkspaceQueue } from "./workspace-schema.js";

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

/**
 * Overall production readiness verdict.
 */
export type ProductionReadinessVerdict = "PASS" | "WARN" | "FAIL";

/**
 * Category of a production readiness check.
 */
export type ProductionReadinessCategory = "safety" | "skills" | "file_scope" | "git_tree" | "schema" | "plan_metadata";

/**
 * A single production readiness check result.
 */
export interface ProductionReadinessCheck {
	/** Unique check name */
	name: string;
	/** Category this check belongs to */
	category: ProductionReadinessCategory;
	/** PASS / WARN / FAIL */
	status: ProductionReadinessVerdict;
	/** Human-readable summary */
	message: string;
	/** Optional additional details */
	details?: string;
	/** Workspace ID this check relates to (if applicable) */
	workspaceId?: string;
}

/**
 * Full production readiness doctor report.
 */
export interface ProductionReadinessReport {
	/** Overall verdict: PASS if no FAILs, WARN if no FAIL but at least one WARN, FAIL otherwise */
	verdict: ProductionReadinessVerdict;
	/** All individual checks */
	checks: ProductionReadinessCheck[];
	/** Quick-access grouped by category */
	byCategory: Record<ProductionReadinessCategory, ProductionReadinessCheck[]>;
	/** Count of PASS checks */
	passCount: number;
	/** Count of WARN checks */
	warnCount: number;
	/** Count of FAIL checks */
	failCount: number;
	/** Whether the queue is ready for auto-run (PASS or WARN with no dirty-tree FAIL) */
	autoRunReady: boolean;
	/** Timestamp (ISO 8601) */
	timestamp: string;
}

// ---------------------------------------------------------------------------
// Broad-scope patterns
// ---------------------------------------------------------------------------

/**
 * Patterns considered "broad" (too permissive for production).
 * A workspace that can edit catch-all patterns
 * risks cross-workspace file conflicts in parallel execution.
 */
const BROAD_SCOPE_PATTERNS: RegExp[] = [
	/^[*]*$/, // "*" or "**"
	/^[*]+[/][*]*$/, // "*/" catch-all etc.
	/^[.]?[*]+$/, // ".*"  (hidden files wildcard)
	/^[/]?[*]+$/, // "/*"
];

/**
 * Determine whether a file-scope pattern is "broad" (overly permissive).
 *
 * @param pattern - Glob pattern from canEdit / canRun
 * @returns True if the pattern is considered broad
 */
export function isBroadScope(pattern: string): boolean {
	const trimmed = pattern.trim();
	if (trimmed === "") return false;
	for (const re of BROAD_SCOPE_PATTERNS) {
		if (re.test(trimmed)) return true;
	}
	// Also flag patterns that are root catch-all
	if (trimmed === "." || trimmed === "./" || trimmed === "/") return true;
	return false;
}

// ---------------------------------------------------------------------------
// Git helpers
// ---------------------------------------------------------------------------

/**
 * Check whether the git working tree has uncommitted changes.
 *
 * @param cwd - Working directory (repository root)
 * @returns True if there are uncommitted changes, false if clean or not a git repo
 */
export async function isGitDirty(cwd: string): Promise<boolean> {
	try {
		const { stdout } = await execAsync("git status --porcelain", {
			cwd,
			encoding: "utf-8",
			timeout: 5000,
		});
		return stdout.trim().length > 0;
	} catch {
		// Not a git repo or git not available - treat as clean
		return false;
	}
}

/**
 * Check whether the directory is inside a git repository.
 *
 * @param cwd - Working directory
 * @returns True if inside a git repo
 */
export async function isGitRepo(cwd: string): Promise<boolean> {
	try {
		await execAsync("git rev-parse --is-inside-work-tree", {
			cwd,
			encoding: "utf-8",
			timeout: 5000,
		});
		return true;
	} catch {
		return false;
	}
}

// ---------------------------------------------------------------------------
// Production Readiness Doctor
// ---------------------------------------------------------------------------

/**
 * Production Readiness Doctor
 *
 * Validates a workspace queue is ready for production auto-run.
 * Checks safety, skills, file scopes, and git working-tree cleanliness.
 */
export class ProductionReadinessDoctor {
	private safetyDoctor: SafetyDoctor;

	constructor() {
		this.safetyDoctor = new SafetyDoctor();
	}

	/**
	 * Run all production readiness checks against a workspace queue.
	 *
	 * @param queue - Workspace queue to validate
	 * @param cwd - Project root working directory
	 * @param agentDir - Agent configuration directory
	 * @param options - Optional overrides
	 * @param options.skillPaths - Additional skill paths to search
	 * @param options.includeDefaultSkills - Whether to include default skill directories (default true)
	 * @param options.skipGitCheck - Skip the git dirty-tree check (useful in CI)
	 * @returns Full production readiness report
	 */
	async run(
		queue: WorkspaceQueue,
		cwd: string,
		agentDir: string,
		options?: {
			skillPaths?: string[];
			includeDefaultSkills?: boolean;
			skipGitCheck?: boolean;
			/** P4.6.2: Optional parse metadata for workstream/workspace count checks */
			parseMetadata?: {
				parsedSource: string;
				markdownWorkstreamCount: number | null;
				missingWorkspaceLabels: string[];
			};
		},
	): Promise<ProductionReadinessReport> {
		const checks: ProductionReadinessCheck[] = [];

		// 1. Safety checks
		checks.push(...this.checkSafety(queue));

		// 2. Skill availability
		checks.push(...this.checkSkills(cwd, agentDir, options));

		// 3. File scope hygiene
		checks.push(...this.checkFileScopes(queue));

		// 4. Git working-tree cleanliness
		if (!options?.skipGitCheck) {
			checks.push(...(await this.checkGitTree(cwd)));
		}

		// 5. Schema / structure sanity
		checks.push(...this.checkSchema(queue));

		// 6. P4.6.2: Plan metadata consistency
		if (options?.parseMetadata) {
			checks.push(...this.checkPlanMetadata(queue, options.parseMetadata));
		}

		return this.buildReport(checks);
	}

	/**
	 * Run safety checks by delegating to SafetyDoctor.
	 *
	 * Critical safety issues map to FAIL, warnings to WARN,
	 * and an overall-clean safety state to PASS.
	 *
	 * @param queue - Workspace queue
	 * @returns Production readiness checks from safety validation
	 */
	checkSafety(queue: WorkspaceQueue): ProductionReadinessCheck[] {
		const checks: ProductionReadinessCheck[] = [];

		const report = this.safetyDoctor.validateQueue(queue);

		if (report.critical.length > 0) {
			checks.push({
				name: "Safety Critical Issues",
				category: "safety",
				status: "FAIL",
				message: `${report.critical.length} critical safety issue(s) found`,
				details: report.critical.map((i: SafetyIssue) => `[${i.type}] ${i.message}`).join("; "),
			});
		} else {
			checks.push({
				name: "Safety Critical Issues",
				category: "safety",
				status: "PASS",
				message: "No critical safety issues",
			});
		}

		if (report.warnings.length > 0) {
			checks.push({
				name: "Safety Warnings",
				category: "safety",
				status: "WARN",
				message: `${report.warnings.length} safety warning(s) found`,
				details: report.warnings.map((i: SafetyIssue) => `[${i.type}] ${i.message}`).join("; "),
			});
		} else {
			checks.push({
				name: "Safety Warnings",
				category: "safety",
				status: "PASS",
				message: "No safety warnings",
			});
		}

		return checks;
	}

	/**
	 * Check that all required skills are available.
	 *
	 * Missing required skills produce a FAIL since the queue
	 * cannot be executed without them.
	 *
	 * @param cwd - Working directory
	 * @param agentDir - Agent config directory
	 * @param options - Skill loading options
	 * @returns Production readiness checks for skill availability
	 */
	checkSkills(
		cwd: string,
		agentDir: string,
		options?: { skillPaths?: string[]; includeDefaultSkills?: boolean },
	): ProductionReadinessCheck[] {
		const checks: ProductionReadinessCheck[] = [];

		try {
			const registry = new SkillRegistry(cwd, agentDir);
			const validation = registry.validate({
				skillPaths: options?.skillPaths,
				includeDefaults: options?.includeDefaultSkills ?? true,
			});

			if (validation.missingRequired.length > 0) {
				const names = validation.missingRequired.map((m) => `"${m.entry.name}"`).join(", ");
				checks.push({
					name: "Required Skills Available",
					category: "skills",
					status: "FAIL",
					message: `${validation.missingRequired.length} required skill(s) missing: ${names}`,
					details: validation.missingRequired.map((m) => m.reason).join("; "),
				});
			} else {
				checks.push({
					name: "Required Skills Available",
					category: "skills",
					status: "PASS",
					message: "All required skills are available",
				});
			}
		} catch (error) {
			const msg = error instanceof Error ? error.message : String(error);
			checks.push({
				name: "Required Skills Available",
				category: "skills",
				status: "FAIL",
				message: `Skill registry error: ${msg}`,
			});
		}

		return checks;
	}

	/**
	 * Check file scopes for broad/overly-permissive patterns.
	 *
	 * Workspaces that declare canEdit catch-all patterns
	 * risk cross-workspace file conflicts in parallel execution.
	 * These produce WARN (not FAIL) since they may be intentional.
	 *
	 * @param queue - Workspace queue
	 * @returns Production readiness checks for file scope hygiene
	 */
	checkFileScopes(queue: WorkspaceQueue): ProductionReadinessCheck[] {
		const checks: ProductionReadinessCheck[] = [];
		const broadScopes: Array<{ workspaceId: string; patterns: string[] }> = [];

		for (const workspace of queue.workspaces) {
			if (!workspace.capabilities) continue;

			const broad = this.findBroadPatterns(workspace.id, workspace.capabilities);
			if (broad.length > 0) {
				broadScopes.push({ workspaceId: workspace.id, patterns: broad });
			}
		}

		if (broadScopes.length > 0) {
			const details = broadScopes.map((b) => `${b.workspaceId}: ${b.patterns.join(", ")}`).join("; ");
			checks.push({
				name: "File Scope Hygiene",
				category: "file_scope",
				status: "WARN",
				message: `${broadScopes.length} workspace(s) have broad file scopes`,
				details: `Broad patterns found: ${details}`,
			});
		} else {
			checks.push({
				name: "File Scope Hygiene",
				category: "file_scope",
				status: "PASS",
				message: "All file scopes are appropriately scoped",
			});
		}

		return checks;
	}

	/**
	 * Check git working-tree cleanliness.
	 *
	 * A dirty working tree (uncommitted changes) FAILs queue
	 * auto-run readiness because auto-run may auto-commit and
	 * the uncommitted changes could conflict or be lost.
	 *
	 * @param cwd - Project root directory
	 * @returns Production readiness check for git tree status
	 */
	async checkGitTree(cwd: string): Promise<ProductionReadinessCheck[]> {
		const checks: ProductionReadinessCheck[] = [];

		if (!(await isGitRepo(cwd))) {
			checks.push({
				name: "Git Working Tree",
				category: "git_tree",
				status: "PASS",
				message: "Not a git repository - tree check skipped",
			});
			return checks;
		}

		if (await isGitDirty(cwd)) {
			checks.push({
				name: "Git Working Tree",
				category: "git_tree",
				status: "FAIL",
				message: "Dirty working tree - uncommitted changes detected",
				details:
					"Auto-run cannot safely proceed with uncommitted changes. " +
					"Commit or stash your changes before running the queue.",
			});
		} else {
			checks.push({
				name: "Git Working Tree",
				category: "git_tree",
				status: "PASS",
				message: "Working tree is clean",
			});
		}

		return checks;
	}

	/**
	 * Basic schema/structure sanity checks for the queue.
	 *
	 * Checks:
	 * - Every workspace has a title
	 * - Every workspace has at least one acceptance criterion (WARN if missing)
	 *
	 * @param queue - Workspace queue
	 * @returns Production readiness checks for schema validity
	 */
	checkSchema(queue: WorkspaceQueue): ProductionReadinessCheck[] {
		const checks: ProductionReadinessCheck[] = [];

		// Workspace title presence
		const missingTitles = queue.workspaces.filter((w) => !w.title || w.title.trim() === "");
		if (missingTitles.length > 0) {
			const ids = missingTitles.map((w) => w.id).join(", ");
			checks.push({
				name: "Workspace Titles",
				category: "schema",
				status: "FAIL",
				message: `${missingTitles.length} workspace(s) missing title: ${ids}`,
			});
		} else {
			checks.push({
				name: "Workspace Titles",
				category: "schema",
				status: "PASS",
				message: "All workspaces have titles",
			});
		}

		// Acceptance criteria presence
		const missingCriteria = queue.workspaces.filter(
			(w) => !w.acceptanceCriteria || w.acceptanceCriteria.length === 0,
		);
		if (missingCriteria.length > 0) {
			const ids = missingCriteria.map((w) => w.id).join(", ");
			checks.push({
				name: "Acceptance Criteria",
				category: "schema",
				status: "WARN",
				message: `${missingCriteria.length} workspace(s) lack acceptance criteria: ${ids}`,
				details: "Acceptance criteria help validate workspace completion",
			});
		} else {
			checks.push({
				name: "Acceptance Criteria",
				category: "schema",
				status: "PASS",
				message: "All workspaces have acceptance criteria",
			});
		}

		return checks;
	}

	/**
	 * Build the final report from all checks.
	 *
	 * @param checks - All production readiness checks
	 * @returns Complete production readiness report
	 */
	private buildReport(checks: ProductionReadinessCheck[]): ProductionReadinessReport {
		const passCount = checks.filter((c) => c.status === "PASS").length;
		const warnCount = checks.filter((c) => c.status === "WARN").length;
		const failCount = checks.filter((c) => c.status === "FAIL").length;

		// Overall verdict
		let verdict: ProductionReadinessVerdict;
		if (failCount > 0) {
			verdict = "FAIL";
		} else if (warnCount > 0) {
			verdict = "WARN";
		} else {
			verdict = "PASS";
		}

		// Group by category
		const categories: ProductionReadinessCategory[] = [
			"safety",
			"skills",
			"file_scope",
			"git_tree",
			"schema",
			"plan_metadata",
		];
		const byCategory = {} as Record<ProductionReadinessCategory, ProductionReadinessCheck[]>;
		for (const cat of categories) {
			byCategory[cat] = checks.filter((c) => c.category === cat);
		}

		// Auto-run readiness: PASS or WARN overall, AND no dirty-tree FAIL
		const hasDirtyTreeFail = checks.some((c) => c.category === "git_tree" && c.status === "FAIL");
		const autoRunReady = verdict !== "FAIL" && !hasDirtyTreeFail;

		return {
			verdict,
			checks,
			byCategory,
			passCount,
			warnCount,
			failCount,
			autoRunReady,
			timestamp: new Date().toISOString(),
		};
	}

	/**
	 * P4.6.2: Check plan metadata consistency.
	 *
	 * Warns when Part 1 markdown defines a different number of workstreams
	 * than Part 3 JSON defines executable workspaces.
	 * Also reports missing workspace labels.
	 *
	 * @param queue - Workspace queue
	 * @param metadata - Parse metadata from plan parser
	 * @returns Production readiness checks for plan metadata consistency
	 */
	checkPlanMetadata(
		queue: WorkspaceQueue,
		metadata: { parsedSource: string; markdownWorkstreamCount: number | null; missingWorkspaceLabels: string[] },
	): ProductionReadinessCheck[] {
		const checks: ProductionReadinessCheck[] = [];

		// Check parsed source
		checks.push({
			name: "Plan Parsed Source",
			category: "plan_metadata",
			status: "PASS",
			message: `Plan metadata parsed from: ${metadata.parsedSource}`,
		});

		// Check workstream/workspace count consistency
		if (metadata.markdownWorkstreamCount !== null && metadata.markdownWorkstreamCount !== queue.workspaces.length) {
			checks.push({
				name: "Workstream/Workspace Count Consistency",
				category: "plan_metadata",
				status: "WARN",
				message:
					`Part 1 defines ${metadata.markdownWorkstreamCount} workstream(s) but Part 3 JSON defines ${queue.workspaces.length} executable workspace(s). ` +
					`Pi will execute only the ${queue.workspaces.length} JSON workspace(s).`,
			});
		} else {
			checks.push({
				name: "Workstream/Workspace Count Consistency",
				category: "plan_metadata",
				status: "PASS",
				message: "Markdown workstream count matches JSON workspace count",
			});
		}

		// Check for missing workspace labels
		if (metadata.missingWorkspaceLabels.length > 0) {
			checks.push({
				name: "Missing Workspace Entries",
				category: "plan_metadata",
				status: "WARN",
				message: `Markdown workstream(s) without JSON workspace entry: ${metadata.missingWorkspaceLabels.join(", ")}`,
			});
		} else {
			checks.push({
				name: "Missing Workspace Entries",
				category: "plan_metadata",
				status: "PASS",
				message: "All markdown workstreams have JSON workspace entries",
			});
		}

		return checks;
	}

	/**
	 * Find broad patterns in a workspace's capabilities.
	 *
	 * @param _workspaceId - Workspace ID (for logging)
	 * @param capabilities - Workspace capability manifest
	 * @returns Array of broad pattern strings
	 */
	private findBroadPatterns(_workspaceId: string, capabilities: WorkspaceCapabilityManifest): string[] {
		const broad: string[] = [];
		for (const pattern of capabilities.canEdit) {
			if (isBroadScope(pattern)) {
				broad.push(pattern);
			}
		}
		return broad;
	}
}

