	protectedPaths: Set<string>,
	blocked: boolean = true,
): (filePaths: string[]) => SelfModificationCheckResult[] {
	return (filePaths: string[]) =>
		filePaths.map((fp) => {
			const normalized = fp.replace(/\\/g, "/");
			const isProtected = protectedPaths.has(normalized);
