/**
 * Orchestrator Types - P11.B
 *
 * Core type definitions for the always-on orchestrator daemon:
 * lifecycle states, scan configuration, scheduler records, health status,
 * and policy event reporting.
 *
 * No platform enums or types should be redefined here — import from
 * the canonical platform module instead.
 *
 * @packageDocumentation
 */

import type { AuditLevel, PlatformComponent } from "../platform/types.js";

// ---------------------------------------------------------------------------
// Orchestrator Lifecycle
// ---------------------------------------------------------------------------

/**
 * Lifecycle state of the orchestrator daemon.
 */
export type OrchestratorState =
	| "stopped" // Not running
	| "starting" // Transitioning to running
	| "running" // Actively scanning and monitoring
	| "pausing" // Transitioning to paused (graceful stop of active scans)
	| "paused" // Suspended — no scans, but retained configuration
	| "stopping" // Transitioning to stopped
	| "failed"; // Unrecoverable error

/**
 * Human-readable labels for each orchestrator state.
 */
export const ORCHESTRATOR_STATE_LABELS: Record<OrchestratorState, string> = {
	stopped: "Stopped",
	starting: "Starting",
	running: "Running",
	pausing: "Pausing",
	paused: "Paused",
	stopping: "Stopping",
	failed: "Failed",
};

// ---------------------------------------------------------------------------
// Orchestrator Status
// ---------------------------------------------------------------------------

/**
 * Full orchestrator status snapshot for API/state-store consumption.
 */
export interface OrchestratorStatus {
	/** Current lifecycle state */
	state: OrchestratorState;
	/** ISO-8601 timestamp when orchestrator started */
	startedAt: string | null;
	/** ISO-8601 timestamp of last state change */
	lastStateChangeAt: string | null;
	/** ISO-8601 timestamp of last completed scan cycle */
	lastScanCycleAt: string | null;
	/** Number of scan cycles completed since start */
	scanCycleCount: number;
	/** Total number of scan errors since start */
	totalScanErrors: number;
	/** Whether the orchestrator is healthy */
	healthy: boolean;
	/** Current health check detail */
	healthDetail: string;
	/** Scan scheduler snapshot */
	scheduler: SchedulerSnapshot;
	/** Mutation guard snapshot */
	mutationGuard: MutationGuardSnapshot;
	/** Version of the orchestrator */
	version: string;
	/** Component identifier */
	component: PlatformComponent;
}

// ---------------------------------------------------------------------------
// Scan Configuration
// ---------------------------------------------------------------------------

/**
 * Type of scan the orchestrator can perform.
 */
export type ScanType =
	| "repo_health" // Scan repository health signals
	| "run_history" // Scan recent plan run history
	| "queue" // Scan plan queue depth and state
	| "dashboard_metrics" // Collect dashboard metric snapshots
	| "proposal_refresh"; // Refresh stale proposals

/**
 * Human-readable labels for each scan type.
 */
export const SCAN_TYPE_LABELS: Record<ScanType, string> = {
	repo_health: "Repository Health",
	run_history: "Run History",
	queue: "Queue",
	dashboard_metrics: "Dashboard Metrics",
	proposal_refresh: "Proposal Refresh",
};

/**
 * Cadence configuration for a single scan type.
 */
export interface ScanCadence {
	/** Interval in milliseconds between scans */
	intervalMs: number;
	/** Whether this scan type is enabled */
	enabled: boolean;
	/** Maximum number of consecutive failures before disabling */
	maxConsecutiveFailures: number;
	/** Base delay for exponential backoff on failure (ms) */
	backoffBaseMs: number;
	/** Maximum backoff delay (ms) */
	backoffMaxMs: number;
}

/**
 * Full scan configuration for the orchestrator.
 */
export interface ScanConfig {
	/** Cadence for each scan type */
	cadences: Record<ScanType, ScanCadence>;
	/** Rate limit: max scans per minute across all types */
	maxScansPerMinute: number;
	/** Token budget: max token cost per scan cycle */
	maxTokensPerCycle: number;
	/** Default project scan cadence override (ms) */
	defaultProjectCadenceMs?: number;
}

// ---------------------------------------------------------------------------
// Scan Record (Scheduler)
// ---------------------------------------------------------------------------

/**
 * Outcome of a single scan execution.
 */
export type ScanOutcome = "success" | "skipped" | "failed" | "over_rate_limit" | "over_budget";

/**
 * A single scan record kept by the scheduler.
 */
export interface ScanRecord {
	/** Scan type */
	type: ScanType;
	/** When the scan was started (ISO-8601) */
	startedAt: string;
	/** When the scan completed (ISO-8601, null if still running) */
	completedAt: string | null;
	/** Duration in milliseconds */
	durationMs: number | null;
	/** Outcome of the scan */
	outcome: ScanOutcome;
	/** Human-readable skip/fail reason */
	reason?: string;
	/** Error message if failed */
	error?: string;
	/** Token cost of the scan (if tracked) */
	tokenCost?: number;
}

// ---------------------------------------------------------------------------
// Scheduler State
// ---------------------------------------------------------------------------

/**
 * Snapshot of the scan scheduler state.
 */
export interface SchedulerSnapshot {
	/** Last scan start time per type (ISO-8601 or null) */
	lastScan: Record<ScanType, string | null>;
	/** Next scheduled scan time per type (ISO-8601 or null) */
	nextScan: Record<ScanType, string | null>;
	/** Recent scan records (most recent first, max 100) */
	recentScans: ScanRecord[];
	/** Consecutive failure count per type */
	consecutiveFailures: Record<ScanType, number>;
	/** Current backoff delay per type (ms) */
	backoffDelays: Record<ScanType, number>;
	/** Total scans completed per type */
	totalScans: Record<ScanType, number>;
	/** Total failures per type */
	totalFailures: Record<ScanType, number>;
	/** Total skips per type */
	totalSkips: Record<ScanType, number>;
}

// ---------------------------------------------------------------------------
// Mutation Guard
// ---------------------------------------------------------------------------

/**
 * Category of blocked mutation.
 */
export type MutationCategory =
	| "code_write"
	| "code_delete"
	| "queue_mutate"
	| "state_mutate"
	| "protected_system"
	| "execution_graph";

/**
 * A policy event recorded when a mutation is blocked.
 */
export interface PolicyEvent {
	/** Unique event ID */
	id: string;
	/** ISO-8601 timestamp */
	timestamp: string;
	/** Category of the blocked mutation */
	category: MutationCategory;
	/** What was attempted */
	attempt: string;
	/** Target path or resource */
	target: string;
	/** Source component that attempted the mutation */
	source: string;
	/** Severity level */
	severity: AuditLevel;
	/** Human-readable detail */
	detail: string;
}

/**
 * Snapshot of the mutation guard state.
 */
export interface MutationGuardSnapshot {
	/** Total blocked mutations since start */
	totalBlocked: number;
	/** Count by category */
	byCategory: Record<MutationCategory, number>;
	/** Recent policy events (most recent first, max 50) */
	recentEvents: PolicyEvent[];
	/** Whether mutation blocking is active */
	blockingActive: boolean;
}

// ---------------------------------------------------------------------------
// Default Configuration
// ---------------------------------------------------------------------------

/**
 * Default scan cadence configuration.
 */
export const DEFAULT_SCAN_CADENCES: Record<ScanType, ScanCadence> = {
	repo_health: {
		intervalMs: 5 * 60 * 1000, // 5 minutes
		enabled: true,
		maxConsecutiveFailures: 3,
		backoffBaseMs: 30_000, // 30 seconds
		backoffMaxMs: 30 * 60 * 1000, // 30 minutes
	},
	run_history: {
		intervalMs: 10 * 60 * 1000, // 10 minutes
		enabled: true,
		maxConsecutiveFailures: 3,
		backoffBaseMs: 60_000, // 1 minute
		backoffMaxMs: 30 * 60 * 1000, // 30 minutes
	},
	queue: {
		intervalMs: 2 * 60 * 1000, // 2 minutes
		enabled: true,
		maxConsecutiveFailures: 5,
		backoffBaseMs: 30_000, // 30 seconds
		backoffMaxMs: 15 * 60 * 1000, // 15 minutes
	},
	dashboard_metrics: {
		intervalMs: 15 * 60 * 1000, // 15 minutes
		enabled: true,
		maxConsecutiveFailures: 3,
		backoffBaseMs: 60_000, // 1 minute
		backoffMaxMs: 30 * 60 * 1000, // 30 minutes
	},
	proposal_refresh: {
		intervalMs: 30 * 60 * 1000, // 30 minutes
		enabled: true,
		maxConsecutiveFailures: 3,
		backoffBaseMs: 60_000, // 1 minute
		backoffMaxMs: 60 * 60 * 1000, // 60 minutes
	},
};

/**
 * Default scan configuration.
 */
export const DEFAULT_SCAN_CONFIG: ScanConfig = {
	cadences: DEFAULT_SCAN_CADENCES,
	maxScansPerMinute: 20,
	maxTokensPerCycle: 100_000,
	defaultProjectCadenceMs: 15 * 60 * 1000, // 15 minutes
};

/**
 * Mutation Guard - P11.B
 *
 * Blocks mutation attempts from unauthorised components and logs them
 * as policy events. The orchestrator must never mutate code, queue state,
 * protected systems, or execution graphs directly.
 *
 * Every blocked mutation is recorded with category, target, source, and
 * severity for audit trail and dashboard visibility.
 *
 * @packageDocumentation
 */

import { randomUUID } from "node:crypto";
import { AuditLevel, PlatformComponent } from "../platform/types.js";
import { PiLogger } from "../utils/logger.js";
import type {
	MutationCategory,
	MutationGuardSnapshot,
	PolicyEvent,
} from "./orchestrator-types.js";

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------

/** Maximum number of recent policy events retained in memory. */
const MAX_RECENT_EVENTS = 50;

/** Default source component when not specified. */
const DEFAULT_SOURCE = PlatformComponent.CodingAgent;

/**
 * Path patterns considered "protected systems" — mutations to these
 * are always blocked with critical severity.
 */
const PROTECTED_PATH_PATTERNS: RegExp[] = [
	/\.pi\/(settings|agent|skills)\//,
	/packages\/(agent|ai|tui)\/src\//,
	/node_modules\//,
];

// ---------------------------------------------------------------------------
// MutationGuard
// ---------------------------------------------------------------------------

/**
 * Mutation guard that intercepts and blocks mutation attempts.
 *
 * The guard categorises each attempt and logs it as a policy event.
 * It never allows mutations — it only records them for audit.
 *
 * AC4: Mutation attempts are blocked and logged as policy events.
 */
export class MutationGuard {
	private _events: PolicyEvent[] = [];
	private _byCategory = new Map<MutationCategory, number>();
	private readonly _log: PiLogger;

	constructor(context?: Record<string, unknown>) {
		this._log = new PiLogger({ component: "mutation-guard", ...context });
	}

	// -----------------------------------------------------------------------
	// Accessors
	// -----------------------------------------------------------------------

	/** Total blocked mutations. */
	get totalBlocked(): number {
		return this._events.length;
	}

	/** Whether blocking is active (always true for the orchestrator). */
	get blockingActive(): boolean {
		return true;
	}

	/** Recent policy events (immutable view, newest first). */
	get recentEvents(): ReadonlyArray<PolicyEvent> {
		return this._events;
	}

	// -----------------------------------------------------------------------
	// Blocking
	// -----------------------------------------------------------------------

	/**
	 * Record and log a blocked mutation attempt.
	 *
	 * @param category - Category of the blocked mutation
	 * @param attempt - Description of what was attempted
	 * @param target - Target path or resource
	 * @param options - Additional options
	 * @returns The created policy event
	 */
	block(
		category: MutationCategory,
		attempt: string,
		target: string,
		options?: {
			source?: string;
			severity?: AuditLevel;
			detail?: string;
		},
	): PolicyEvent {
		const source = options?.source ?? DEFAULT_SOURCE;
		const severity = options?.severity ?? this.resolveSeverity(category, target);

		const event: PolicyEvent = {
			id: `policy-${randomUUID()}`,
			timestamp: new Date().toISOString(),
			category,
			attempt,
			target,
			source,
			severity,
			detail: options?.detail ?? `Blocked ${category} mutation at ${target}`,
		};

		// Record event
		this._events.unshift(event);
		if (this._events.length > MAX_RECENT_EVENTS) {
			this._events.pop();
		}

		// Update category counts
		this._byCategory.set(category, (this._byCategory.get(category) ?? 0) + 1);

		// Log the policy event
		const logLevel = severity === AuditLevel.Critical ? "error" : severity === AuditLevel.Warn ? "warn" : "info";
		this._log[logLevel](`POLICY EVENT [${category}] ${attempt} -> ${target}`, {
			eventId: event.id,
			severity,
			source,
		});

		return event;
	}

	/**
	 * Check if a path is protected (matches protected system patterns).
	 *
	 * @param path - Path to check
	 * @returns True if the path is protected
	 */
	isProtectedPath(path: string): boolean {
		return PROTECTED_PATH_PATTERNS.some((pattern) => pattern.test(path));
	}

	/**
	 * Attempt a mutation — always blocked and logged.
	 * This is the primary API that the orchestrator calls before any mutation.
	 *
	 * @param category - Category of the attempted mutation
	 * @param attempt - Description of what was attempted
	 * @param target - Target path or resource
	 * @param options - Additional options
	 * @returns Always returns false (mutation blocked)
	 */
	tryMutate(
		category: MutationCategory,
		attempt: string,
		target: string,
		options?: {
			source?: string;
			severity?: AuditLevel;
			detail?: string;
		},
	): boolean {
		this.block(category, attempt, target, options);
		return false; // Always blocked
	}

	/**
	 * Classify a path into a mutation category.
	 *
	 * @param path - Target path to classify
	 * @returns The most specific mutation category
	 */
	classifyPath(path: string): MutationCategory {
		if (this.isProtectedPath(path)) {
			return "protected_system";
		}
		if (/\.(ts|js|tsx|jsx|json|md|css|html)$/i.test(path)) {
			return "code_write";
		}
		if (/\/queue\//.test(path) || /queue\.json$/.test(path)) {
			return "queue_mutate";
		}
		if (/\.pi\//.test(path)) {
			return "state_mutate";
		}
		if (/dependency|dag|graph|batch/i.test(path)) {
			return "execution_graph";
		}
		return "code_write";
	}

	// -----------------------------------------------------------------------
	// Snapshot
	// -----------------------------------------------------------------------

	/**
	 * Get a snapshot of the mutation guard state.
	 */
	snapshot(): MutationGuardSnapshot {
		const byCategory: Record<string, number> = {};
		for (const [cat, count] of this._byCategory) {
			byCategory[cat] = count;
		}

		return {
			totalBlocked: this.totalBlocked,
			byCategory: byCategory as Record<MutationCategory, number>,
			recentEvents: this._events.slice(0, MAX_RECENT_EVENTS),
			blockingActive: this.blockingActive,
		};
	}

	/**
	 * Clear all recorded events (for testing / reset).
	 */
	clear(): void {
		this._events = [];
		this._byCategory.clear();
	}

	// -----------------------------------------------------------------------
	// Internals
	// -----------------------------------------------------------------------

	/**
	 * Resolve the severity level for a blocked mutation.
	 * Protected system mutations are always critical.
	 */
	private resolveSeverity(category: MutationCategory, target: string): AuditLevel {
		if (this.isProtectedPath(target) || category === "protected_system") {
			return AuditLevel.Critical;
		}
		if (category === "execution_graph" || category === "queue_mutate" || category === "state_mutate") {
			return AuditLevel.Error;
		}
		return AuditLevel.Warn;
	}
}

