	mergedCount?: number;

	/**
	 * Number of workspaces that failed or were blocked.
	 */
	failedCount?: number;

	/**
	 * Number of workspaces with merge conflicts.
	 */
	conflictCount?: number;

	/**
	 * Risk model adjustments derived from queue outcomes.
