/**
 * Extension Lifecycle API Routes — P11.J
 *
 * Provides REST API for extension lifecycle management: install, update,
 * rollback, enable/disable, and health check.
 *
 * All mutating operations are logged to an audit trail under
 * `.pi/extensions/audit.json` for accountability.
 *
 * Endpoints:
 *   GET    /api/extensions                 List installed extensions with status
 *   GET    /api/extensions/health          Health check for all extensions
 *   POST   /api/extensions/install         Install a new extension/package
 *   POST   /api/extensions/update          Update extension(s)
 *   POST   /api/extensions/rollback        Rollback an extension to previous version
 *   POST   /api/extensions/enable          Enable an extension within a package
 *   POST   /api/extensions/disable         Disable an extension within a package
 */

import { existsSync, mkdirSync } from "node:fs";
import { cp, readFile, rm, writeFile } from "node:fs/promises";
import { join, resolve } from "node:path";
import { DefaultPackageManager, type PackageManager, type PackageSource } from "@earendil-works/pi-coding-agent";
import type { FastifyInstance } from "fastify";
import { getSettingsManager, getWorkspaceRoot } from "./state-store-provider.js";

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------

