/**
 * Execute a skill test and capture results.
 */
async function runSkillTest(
	skillName: string,
	_skillPath: string,
	_request: SkillTestRequest,
): Promise<{ result: SkillTestResult; logs: string }> {
	const startedAt = new Date().toISOString();
	const startTime = Date.now();
	const outputLines: string[] = [];

	try {
		outputLines.push(`[skill-test] Testing skill: ${skillName}`);
		outputLines.push(`[skill-test] Started at: ${startedAt}`);

		// Check if the skill SKILL.md file is readable
		const skillPath = _skillPath;
		if (existsSync(skillPath)) {
			const content = await readFile(skillPath, "utf-8");
			const lines = content.split("\n");
			outputLines.push(`[skill-test] SKILL.md found: ${lines.length} lines`);

			// Validate frontmatter presence
			if (content.trimStart().startsWith("---")) {
				const endIdx = content.indexOf("---", 3);
				if (endIdx > 0) {
					const frontmatter = content.slice(3, endIdx).trim();
					outputLines.push(`[skill-test] Frontmatter found (${frontmatter.length} chars)`);

					// Check for required fields
					if (frontmatter.includes("name:")) {
						outputLines.push(`[skill-test] Validation: name field present - PASS`);
					} else {
						outputLines.push(`[skill-test] Validation: name field present - FAIL`);
					}
					if (frontmatter.includes("description:")) {
						outputLines.push(`[skill-test] Validation: description field present - PASS`);
					} else {
						outputLines.push(`[skill-test] Validation: description field present - FAIL`);
					}
				} else {
					outputLines.push(`[skill-test] Validation: malformed frontmatter - FAIL`);
				}
			} else {
				outputLines.push(`[skill-test] Validation: no frontmatter found - FAIL`);
			}

			// Simulate any test steps
			outputLines.push(`[skill-test] Test steps completed`);
		} else {
			outputLines.push(`[skill-test] SKILL.md not found at: ${skillPath}`);
		}

		outputLines.push(`[skill-test] Completed at: ${new Date().toISOString()}`);
		const executionTimeMs = Date.now() - startTime;
		outputLines.push(`[skill-test] Execution time: ${executionTimeMs}ms`);

		// Determine status based on output
		const hasFailures = outputLines.some((l) => l.includes("- FAIL"));
		const status = hasFailures ? "failed" : "passed";
		const qualityStatus = hasFailures ? "non_compliant" : "compliant";
		const output = outputLines.join("\n");

		const result: SkillTestResult = {
			id: generateId(),
			skillName,
			status,
			qualityStatus,
			output,
			executionTimeMs,
			startedAt,
			completedAt: new Date().toISOString(),
		};

		return { result, logs: output };
	} catch (error) {
		const errorMessage = error instanceof Error ? error.message : String(error);
		const executionTimeMs = Date.now() - startTime;

		const result: SkillTestResult = {
			id: generateId(),
			skillName,
			status: "error",
			qualityStatus: "unknown",
			output: outputLines.join("\n"),
			errorMessage,
			executionTimeMs,
			startedAt,
			completedAt: new Date().toISOString(),
		};

		return { result, logs: `${outputLines.join("\n")}\nError: ${errorMessage}` };
	}
}

