export async function registerSkillRoutes(
	fastify: FastifyInstance,
	getPiDir: () => string,
	_getWorkspaceRoot: () => string,
): Promise<void> {
	const piDir = getPiDir();
	const workspaceRoot = _getWorkspaceRoot();

	// -----------------------------------------------------------------------
	// POST /api/skills/install — Install a skill
	// -----------------------------------------------------------------------
	fastify.post<{
		Body: SkillInstallRequest;
	}>("/api/skills/install", async (request, reply) => {
		try {
			const { name, description, version, source, url, content, path } = request.body;

			if (!name || !/^[a-z0-9-]+$/.test(name)) {
				return reply.code(400).send({
					success: false,
					error: "Invalid skill name. Use lowercase letters, numbers, and hyphens only.",
				});
			}

			const skillDir = join(getSkillsDir(), name);
			mkdirSync(skillDir, { recursive: true });

			const skillFilePath = join(skillDir, "SKILL.md");

			if (content) {
				// Install from provided content
				await writeFile(skillFilePath, content, "utf-8");
			} else if (path && existsSync(path)) {
				// Install from a file path
				const fileContent = await readFile(path, "utf-8");
				await writeFile(skillFilePath, fileContent, "utf-8");
			} else if (url) {
				// Install from a URL (validate it's a URL)
				if (!url.startsWith("http://") && !url.startsWith("https://")) {
					return reply.code(400).send({
						success: false,
						error: "Invalid URL. Must start with http:// or https://",
					});
				}
				try {
					const response = await fetch(url);
					if (!response.ok) {
						return reply.code(400).send({
							success: false,
							error: `Failed to fetch skill from URL: ${response.status} ${response.statusText}`,
						});
					}
					const text = await response.text();
					await writeFile(skillFilePath, text, "utf-8");
				} catch (fetchError) {
					return reply.code(400).send({
						success: false,
						error: `Failed to fetch skill from URL: ${fetchError instanceof Error ? fetchError.message : String(fetchError)}`,
					});
				}
			} else {
				// Create a minimal skill from the provided metadata
				const skillContent = `---
name: ${name}
description: ${description ?? "No description provided"}
${version ? `version: ${version}` : ""}
---

# ${name}

${description ?? "No description provided."}
`;
				await writeFile(skillFilePath, skillContent, "utf-8");
			}

			const installation = {
				id: generateId(),
				name,
				description: description ?? "Installed skill",
				version: version ?? "1.0.0",
				source: source ?? "api",
				url,
				skillPath: skillFilePath,
				installedAt: new Date().toISOString(),
			};

			memoryInstallations.push(installation);

			// Persist to DB if available
			try {
				const backend = detectStateStoreBackend();
				if (backend === "postgres") {
					const { getKysely, SkillInstallationRepository } = await import("@earendil-works/pi-db");
					const db = getKysely();
					const repo = new SkillInstallationRepository(db);
					await repo.create({
						name,
						description: description ?? null,
						version: version ?? null,
						source: source ?? "api",
						url: url ?? null,
						skill_path: skillFilePath,
						installed_at: new Date().toISOString(),
						updated_at: new Date().toISOString(),
					});
				}
			} catch {
				// Fall back to in-memory
			}

			return reply.code(201).send({
				success: true,
				installation,
			});
		} catch (error) {
			fastify.log.error({ error }, "Failed to install skill");
			return reply.code(500).send({
				success: false,
				error: "Failed to install skill",
				message: String(error),
			});
		}
	});

	// -----------------------------------------------------------------------
	// GET /api/skills — List installed skills
	// -----------------------------------------------------------------------
	fastify.get("/api/skills", async (_request, reply) => {
		try {
			const registry = new SkillRegistry(workspaceRoot || process.cwd(), piDir);
			const result = registry.list({ includeDefaults: true });

			return reply.send({
				success: true,
				skills: result.entries.map((e) => ({
					name: e.skill.name,
					description: e.skill.description,
					filePath: e.skill.filePath,
					valid: e.valid,
					required: e.manifestEntry?.required ?? false,
					manifestSource: e.manifestEntry?.source,
				})),
				diagnostics: result.diagnostics,
				count: result.entries.length,
			});
		} catch (error) {
			fastify.log.error({ error }, "Failed to list skills");
			return reply.code(500).send({
				success: false,
				error: "Failed to list skills",
				message: String(error),
			});
		}
	});

	// -----------------------------------------------------------------------
	// GET /api/skills/:name — Get skill details
	// -----------------------------------------------------------------------
	fastify.get<{
		Params: { name: string };
	}>("/api/skills/:name", async (request, reply) => {
		try {
			const { name } = request.params;
			const registry = new SkillRegistry(workspaceRoot || process.cwd(), piDir);
			const result = registry.list({ includeDefaults: true });
			const entry = result.entries.find((e) => e.skill.name === name);

			if (!entry) {
				return reply.code(404).send({
					success: false,
					error: `Skill "${name}" not found`,
				});
			}

			let content: string | undefined;
			try {
				content = await readFile(entry.skill.filePath, "utf-8");
			} catch {
				// File may not be readable
			}

			return reply.send({
				success: true,
				skill: {
					name: entry.skill.name,
					description: entry.skill.description,
					filePath: entry.skill.filePath,
					baseDir: entry.skill.baseDir,
					valid: entry.valid,
					validationMessages: entry.validationMessages,
					required: entry.manifestEntry?.required ?? false,
					disableModelInvocation: entry.skill.disableModelInvocation,
					content,
				},
			});
		} catch (error) {
			fastify.log.error({ error }, "Failed to get skill details");
			return reply.code(500).send({
				success: false,
				error: "Failed to get skill details",
				message: String(error),
			});
		}
	});

	// -----------------------------------------------------------------------
	// DELETE /api/skills/:name — Uninstall a skill
	// -----------------------------------------------------------------------
	fastify.delete<{
		Params: { name: string };
	}>("/api/skills/:name", async (request, reply) => {
		try {
			const { name } = request.params;
			const skillDir = join(getSkillsDir(), name);

			if (!existsSync(skillDir)) {
				return reply.code(404).send({
					success: false,
					error: `Skill "${name}" not found`,
				});
			}

			const { rm } = await import("node:fs/promises");
			await rm(skillDir, { recursive: true, force: true });

			// Remove from in-memory
			memoryInstallations = memoryInstallations.filter((i) => i.name !== name);

			// Remove from DB if available
			try {
				const backend = detectStateStoreBackend();
				if (backend === "postgres") {
					const { getKysely, SkillInstallationRepository } = await import("@earendil-works/pi-db");
					const db = getKysely();
					const repo = new SkillInstallationRepository(db);
					await repo.deleteByName(name);
				}
			} catch {
				// Fall back to in-memory
			}

			return reply.send({
				success: true,
				message: `Skill "${name}" uninstalled`,
			});
		} catch (error) {
			fastify.log.error({ error }, "Failed to uninstall skill");
			return reply.code(500).send({
				success: false,
				error: "Failed to uninstall skill",
				message: String(error),
			});
		}
	});

	// -----------------------------------------------------------------------
	// POST /api/skills/:name/test — Test a skill (captures logs and quality status)
	// -----------------------------------------------------------------------
	fastify.post<{
		Params: { name: string };
		Body: SkillTestRequest;
	}>("/api/skills/:name/test", async (request, reply) => {
		try {
			const { name } = request.params;
			const registry = new SkillRegistry(workspaceRoot || process.cwd(), piDir);
			const result = registry.list({ includeDefaults: true });
			const entry = result.entries.find((e) => e.skill.name === name);

			if (!entry) {
				return reply.code(404).send({
					success: false,
					error: `Skill "${name}" not found`,
				});
