	// POST /api/skills/:name/invoke — Invoke a skill (denied invocations produce audit events)
	// -----------------------------------------------------------------------
	fastify.post<{
		Params: { name: string };
		Body: SkillInvokeRequest;
	}>("/api/skills/:name/invoke", async (request, reply) => {
		try {
			const { name } = request.params;
			const { args, actor, planExecutionId, workspaceId } = request.body ?? {};

			const registry = new SkillRegistry(workspaceRoot || process.cwd(), piDir);
			const listResult = registry.list({ includeDefaults: true });
			const entry = listResult.entries.find((e) => e.skill.name === name);

			if (!entry) {
				return reply.code(404).send({
					success: false,
					error: `Skill "${name}" not found`,
				});
			}

			// Check if skill is blocked by policy (simulate policy check)
			// Skills with disableModelInvocation or whose invocation is denied by policy
			if (entry.skill.disableModelInvocation) {
				const auditEvent = createDeniedAuditEvent(
					name,
					"invoke",
					`Skill "${name}" has disableModelInvocation set and cannot be invoked`,
					actor,
					"policy-skill-disabled",
					"protected",
					planExecutionId,
					workspaceId,
				);
				await persistAuditEvent(auditEvent);

				const result: SkillInvocationResult = {
					success: false,
					denied: true,
					deniedReason: `Skill "${name}" has disableModelInvocation set and cannot be invoked`,
					auditEvent,
				};

				return reply.code(403).send(result);
			}

			// Check for required manifest verification
			if (entry.manifestEntry?.required && !entry.valid) {
				const auditEvent = createDeniedAuditEvent(
					name,
					"invoke",
					`Required skill "${name}" failed validation and cannot be invoked`,
					actor,
					"policy-skill-invalid",
					"protected",
					planExecutionId,
					workspaceId,
				);
				await persistAuditEvent(auditEvent);

				const result: SkillInvocationResult = {
					success: false,
					denied: true,
					deniedReason: `Required skill "${name}" failed validation`,
					auditEvent,
				};

				return reply.code(403).send(result);
			}

			// If skill is denied access_protected_paths, check for protected args
			if (args?.accessProtectedPaths === true || args?.modifyManifest === true) {
				const auditEvent = createDeniedAuditEvent(
					name,
					"invoke",
					`Skill "${name}" attempted protected operation: ${args?.accessProtectedPaths ? "access_protected_paths" : "modify_manifest"}`,
					actor,
					"policy-skill-access-protected",
					"mutates_protected",
					planExecutionId,
					workspaceId,
				);
				await persistAuditEvent(auditEvent);

				const result: SkillInvocationResult = {
					success: false,
					denied: true,
					deniedReason: `Skill "${name}" denied: protected operation requires approval`,
					auditEvent,
				};

				return reply.code(403).send(result);
			}

			// Invoke the skill (read its content)
			let skillContent: string;
			try {
				skillContent = await readFile(entry.skill.filePath, "utf-8");
			} catch (readError) {
				return reply.code(500).send({
					success: false,
					error: `Failed to read skill file: ${readError instanceof Error ? readError.message : String(readError)}`,
				});
			}

			// Return the skill content as invocation result
			const invocationResult: SkillInvocationResult = {
				success: true,
				output: skillContent,
			};

			return reply.send({
				success: true,
				invocation: invocationResult,
			});
		} catch (error) {
			fastify.log.error({ error }, "Failed to invoke skill");
			return reply.code(500).send({
				success: false,
				error: "Failed to invoke skill",
				message: String(error),
			});
		}
	});

