/**
 * Register extension lifecycle API routes on the Fastify instance.
 */
export async function registerExtensionRoutes(fastify: FastifyInstance): Promise<void> {
	const packageManager = createPackageManager();

	// -----------------------------------------------------------------------
	// GET /api/extensions — List installed extensions
	// -----------------------------------------------------------------------
	fastify.get("/api/extensions", async (_request, reply) => {
		try {
			const configuredPackages = packageManager.listConfiguredPackages();
			const extensions: ExtensionInfo[] = [];

			for (const pkg of configuredPackages) {
				const installedPath = pkg.installedPath;
				const source = pkg.source;
				const type = isLocalPathSource(source)
					? "local"
					: source.startsWith("npm:") || source.startsWith("git:") || source.includes("/")
						? "package"
						: "unknown";

				const backupExists = await hasBackup(source);

				extensions.push({
					source,
					scope: pkg.scope,
					type,
					installedPath,
					enabled: !pkg.filtered,
					filtered: pkg.filtered,
					hasRollbackBackup: backupExists,
				});
			}

			return { extensions, count: extensions.length };
		} catch (error) {
			fastify.log.error({ error }, "Failed to list extensions");
			return reply.code(500).send({
				error: "Failed to list extensions",
				code: "INTERNAL_ERROR",
				detail: error instanceof Error ? error.message : String(error),
			} satisfies ExtensionApiError);
		}
	});

	// -----------------------------------------------------------------------
	// GET /api/extensions/health — Health check for all extensions
	// -----------------------------------------------------------------------
	fastify.get("/api/extensions/health", async (_request, reply) => {
		try {
			const configuredPackages = packageManager.listConfiguredPackages();
			const healthResults: ExtensionHealth[] = [];

			for (const pkg of configuredPackages) {
				const installedPath = pkg.installedPath;
				const installed = installedPath ? existsSync(installedPath) : false;
				let version: string | undefined;
				let error: string | undefined;

				if (installed) {
					try {
						version = await readVersion(installedPath);
					} catch (e) {
						error = e instanceof Error ? e.message : String(e);
					}
				}

				healthResults.push({
					source: pkg.source,
					healthy: installed,
					installed,
					version,
					error,
				});
			}

			const allHealthy = healthResults.every((h) => h.healthy);

			return {
				status: allHealthy ? "healthy" : "degraded",
				extensions: healthResults,
				healthy: allHealthy,
				total: healthResults.length,
				unhealthy: healthResults.filter((h) => !h.healthy).length,
			};
		} catch (error) {
			fastify.log.error({ error }, "Extension health check failed");
			return reply.code(500).send({
				error: "Health check failed",
				code: "HEALTH_CHECK_ERROR",
				detail: error instanceof Error ? error.message : String(error),
			} satisfies ExtensionApiError);
		}
	});

	// -----------------------------------------------------------------------
	// POST /api/extensions/install — Install a new extension
	// -----------------------------------------------------------------------
	fastify.post<{
		Body: {
			source: string;
			local?: boolean;
		};
	}>("/api/extensions/install", async (request, reply) => {
		const { source, local } = request.body as { source?: string; local?: boolean };

		if (!source) {
			return reply.code(400).send({
				error: "Missing required field: source",
				code: "MISSING_SOURCE",
			} satisfies ExtensionApiError);
		}

		try {
			// Policy check
			const policy = await checkExtensionPolicy(source);
			if (!policy.allowed) {
				await appendAuditEntry({
					timestamp: Date.now(),
					action: "install",
					source,
					scope: local ? "project" : "user",
					success: false,
					error: policy.reason,
				});
				return reply.code(policy.severity === "warning" ? 400 : 403).send({
					error: policy.reason ?? "Policy check failed",
					code: "POLICY_DENIED",
					detail: policy.reason ?? "Policy check failed",
				} satisfies ExtensionApiError);
			}

			await packageManager.installAndPersist(source, { local });

			await appendAuditEntry({
				timestamp: Date.now(),
				action: "install",
				source,
				scope: local ? "project" : "user",
				success: true,
				detail: `Installed from ${source}`,
			});

			return {
				success: true,
				source,
				message: `Installed ${source}`,
			};
		} catch (error) {
			const errorMessage = error instanceof Error ? error.message : String(error);

			await appendAuditEntry({
				timestamp: Date.now(),
				action: "install",
				source,
				scope: local ? "project" : "user",
				success: false,
				error: errorMessage,
			});

			// Structured error responses for different failure modes
			if (errorMessage.includes("package.json") || errorMessage.includes("manifest")) {
				return reply.code(400).send({
					error: "Invalid extension manifest",
					code: "INVALID_MANIFEST",
					detail: errorMessage,
				} satisfies ExtensionApiError);
			}
			if (
				errorMessage.includes("permission") ||
				errorMessage.includes("denied") ||
				errorMessage.includes("EACCES")
			) {
				return reply.code(403).send({
					error: "Permission denied",
					code: "PERMISSION_DENIED",
					detail: errorMessage,
				} satisfies ExtensionApiError);
			}
			if (
				errorMessage.includes("version") ||
				errorMessage.includes("incompatible") ||
				errorMessage.includes("not found")
			) {
				return reply.code(400).send({
					error: "Incompatible extension version",
					code: "INCOMPATIBLE_VERSION",
					detail: errorMessage,
				} satisfies ExtensionApiError);
			}

			fastify.log.error({ error, source }, "Failed to install extension");
			return reply.code(500).send({
				error: `Failed to install extension: ${errorMessage}`,
				code: "INSTALL_ERROR",
				detail: errorMessage,
			} satisfies ExtensionApiError);
		}
	});

	// -----------------------------------------------------------------------
	// POST /api/extensions/update — Update extension(s)
	// -----------------------------------------------------------------------
	fastify.post<{
		Body: {
			source?: string;
		};
	}>("/api/extensions/update", async (request, reply) => {
		const { source } = request.body as { source?: string };

		try {
			// Create backups before updating
			if (source) {
				// Back up a single extension
				const configuredPackages = packageManager.listConfiguredPackages();
				const pkg = configuredPackages.find(
					(p) => p.source === source || p.source.endsWith(source) || source.endsWith(p.source),
				);
				if (pkg?.installedPath) {
					await createBackup(source, pkg.installedPath);
				}
			} else {
				// Back up all updatable extensions
				const configuredPackages = packageManager.listConfiguredPackages();
				for (const pkg of configuredPackages) {
					if (pkg.installedPath) {
						await createBackup(pkg.source, pkg.installedPath);
					}
				}
			}

			await packageManager.update(source);

			await appendAuditEntry({
				timestamp: Date.now(),
				action: "update",
				source: source ?? "all",
				scope: "user",
				success: true,
				detail: source ? `Updated ${source}` : "Updated all extensions",
			});

			return {
				success: true,
				source: source ?? "all",
				message: source ? `Updated ${source}` : "Updated all extensions",
			};
		} catch (error) {
			const errorMessage = error instanceof Error ? error.message : String(error);

			await appendAuditEntry({
				timestamp: Date.now(),
				action: "update",
				source: source ?? "all",
				scope: "user",
				success: false,
				error: errorMessage,
			});

			if (errorMessage.includes("not installed") || errorMessage.includes("not found")) {
				return reply.code(404).send({
					error: `Extension not found: ${source ?? "unknown"}`,
					code: "NOT_FOUND",
					detail: errorMessage,
				} satisfies ExtensionApiError);
			}

			fastify.log.error({ error, source }, "Failed to update extension");
			return reply.code(500).send({
				error: `Failed to update extension: ${errorMessage}`,
				code: "UPDATE_ERROR",
				detail: errorMessage,
			} satisfies ExtensionApiError);
		}
	});

	// -----------------------------------------------------------------------
	// POST /api/extensions/rollback — Rollback an extension
	// -----------------------------------------------------------------------
	fastify.post<{
		Body: {
			source: string;
		};
	}>("/api/extensions/rollback", async (request, reply) => {
		const { source } = request.body as { source?: string };

		if (!source) {
			return reply.code(400).send({
				error: "Missing required field: source",
				code: "MISSING_SOURCE",
			} satisfies ExtensionApiError);
		}

		try {
			const backupAvailable = await hasBackup(source);

			if (!backupAvailable) {
				// No backup available — disable the extension safely instead
				const configuredPackages = packageManager.listConfiguredPackages();
				const pkg = configuredPackages.find(
					(p) => p.source === source || p.source.endsWith(source) || source.endsWith(p.source),
				);

				if (pkg) {
					// Remove from settings gracefully
					const removed = packageManager.removeSourceFromSettings(source, {
						local: pkg.scope === "project",
					});
					if (removed) {
						await appendAuditEntry({
							timestamp: Date.now(),
							action: "rollback",
							source,
							scope: pkg.scope,
							success: true,
							detail: "No rollback backup available; disabled extension as safe fallback",
						});
						return {
							success: true,
							source,
							message: `No rollback backup available for ${source}. Extension has been disabled as a safe fallback.`,
							fallback: "disabled",
						};
					}
				}

				return reply.code(400).send({
					error: `No rollback backup available for ${source} and could not disable the extension`,
					code: "ROLLBACK_UNAVAILABLE",
					detail: `No backup found for ${sanitizeSourceKey(source)}${BACKUP_SUFFIX}`,
				} satisfies ExtensionApiError);
			}

			// Find the installed path for this source
			const configuredPackages = packageManager.listConfiguredPackages();
			const pkg = configuredPackages.find(
				(p) => p.source === source || p.source.endsWith(source) || source.endsWith(p.source),
			);

			if (!pkg || !pkg.installedPath) {
				return reply.code(404).send({
					error: `Extension not found: ${source}`,
					code: "NOT_FOUND",
				} satisfies ExtensionApiError);
			}

			if (!existsSync(pkg.installedPath)) {
				return reply.code(404).send({
					error: `Extension installation not found at: ${pkg.installedPath}`,
					code: "NOT_FOUND",
				} satisfies ExtensionApiError);
			}

			// Perform rollback: replace current installation with backup
			const backupPath = getBackupPath(source);

			// Remove current installation
			await rm(pkg.installedPath, { recursive: true, force: true });

			// Restore backup to installation path
			await cp(backupPath, pkg.installedPath, { recursive: true });

			// Clean up the backup
			await rm(backupPath, { recursive: true, force: true });

			await appendAuditEntry({
				timestamp: Date.now(),
				action: "rollback",
				source,
				scope: pkg.scope,
				success: true,
				detail: `Rolled back ${source} to previous version`,
			});

			return {
				success: true,
				source,
				message: `Rolled back ${source} to previous version`,
				fallback: "restored",
			};
		} catch (error) {
			const errorMessage = error instanceof Error ? error.message : String(error);

			await appendAuditEntry({
				timestamp: Date.now(),
				action: "rollback",
				source,
				scope: "user",
				success: false,
				error: errorMessage,
			});

			fastify.log.error({ error, source }, "Failed to rollback extension");
			return reply.code(500).send({
				error: `Failed to rollback extension: ${errorMessage}`,
				code: "ROLLBACK_ERROR",
				detail: errorMessage,
			} satisfies ExtensionApiError);
		}
	});

	// -----------------------------------------------------------------------
	// POST /api/extensions/enable — Enable an extension within a package
	// -----------------------------------------------------------------------
	fastify.post<{
		Body: {
			source: string;
			extensionPath?: string;
		};
	}>("/api/extensions/enable", async (request, reply) => {
		const { source, extensionPath } = request.body as { source?: string; extensionPath?: string };

		if (!source) {
			return reply.code(400).send({
				error: "Missing required field: source",
				code: "MISSING_SOURCE",
			} satisfies ExtensionApiError);
		}

		try {
			const settingsManager = getSettingsManager();
			const globalSettings = settingsManager.getGlobalSettings();
			const projectSettings = settingsManager.getProjectSettings();

			// Find the package in settings
			let found = false;
			let scope: "user" | "project" = "user";

			const updatePackages = (packages: PackageSource[]): PackageSource[] =>
				packages.map((pkg): PackageSource => {
					if (typeof pkg === "object" && pkg.source === source) {
						found = true;
						if (extensionPath) {
							// Enable specific extension by removing it from the filter
							const currentExtensions = pkg.extensions ?? [];
							if (currentExtensions.includes(extensionPath)) {
								// If all extensions are filtered, modifying the filter enables it
								return {
									...pkg,
									extensions: currentExtensions.filter((e) => e !== extensionPath),
								};
							}
						} else {
							// Enable all extensions — remove filter
							const { extensions: _ext, ...rest } = pkg;
							return rest;
						}
					}
					return pkg;
				});

			// Try project settings first
			const updatedProjectPackages = updatePackages(projectSettings.packages ?? []);
			if (found) {
				scope = "project";
				settingsManager.setProjectPackages(updatedProjectPackages);
			} else {
				const updatedGlobalPackages = updatePackages(globalSettings.packages ?? []);
				if (found) {
					scope = "user";
					settingsManager.setPackages(updatedGlobalPackages);
				}
			}

			if (!found) {
				return reply.code(404).send({
					error: `Package not found: ${source}`,
					code: "NOT_FOUND",
				} satisfies ExtensionApiError);
			}

			await appendAuditEntry({
				timestamp: Date.now(),
				action: "enable",
				source,
				scope,
				success: true,
				detail: extensionPath
					? `Enabled extension ${extensionPath} in package ${source}`
					: `Enabled all extensions in package ${source}`,
			});

			return {
				success: true,
				source,
				extensionPath: extensionPath ?? "all",
				message: extensionPath
					? `Enabled ${extensionPath} in package ${source}`
					: `Enabled all extensions in package ${source}`,
			};
		} catch (error) {
			const errorMessage = error instanceof Error ? error.message : String(error);
			fastify.log.error({ error, source }, "Failed to enable extension");
			return reply.code(500).send({
				error: `Failed to enable extension: ${errorMessage}`,
				code: "ENABLE_ERROR",
				detail: errorMessage,
			} satisfies ExtensionApiError);
		}
	});

	// -----------------------------------------------------------------------
	// POST /api/extensions/disable — Disable an extension within a package
	// -----------------------------------------------------------------------
	fastify.post<{
		Body: {
			source: string;
			extensionPath?: string;
		};
	}>("/api/extensions/disable", async (request, reply) => {
		const { source, extensionPath } = request.body as { source?: string; extensionPath?: string };

		if (!source) {
			return reply.code(400).send({
				error: "Missing required field: source",
				code: "MISSING_SOURCE",
			} satisfies ExtensionApiError);
		}

		try {
			const settingsManager = getSettingsManager();
			const globalSettings = settingsManager.getGlobalSettings();
			const projectSettings = settingsManager.getProjectSettings();

			let found = false;
			let scope: "user" | "project" = "user";

			const updatePackages = (packages: PackageSource[]): PackageSource[] =>
				packages.map((pkg): PackageSource => {
					if (typeof pkg === "object" && pkg.source === source) {
						found = true;
						const currentExtensions = pkg.extensions ?? [];
						if (extensionPath && !currentExtensions.includes(extensionPath)) {
							return {
								...pkg,
								extensions: [...currentExtensions, extensionPath],
							};
						}
						// If no specific extension path, disable by converting to filtered form
						return pkg;
					}
					if (typeof pkg === "string" && pkg === source) {
						found = true;
						if (extensionPath) {
							return { source: pkg, extensions: [extensionPath] };
						}
						// If string form (all enabled), convert to object form with empty extensions to disable all
						return { source: pkg, extensions: [] };
					}
					return pkg;
				});

			// Try project settings first
			const updatedProjectPackages = updatePackages(projectSettings.packages ?? []);
			if (found) {
				scope = "project";
				settingsManager.setProjectPackages(updatedProjectPackages);
			} else {
				const updatedGlobalPackages = updatePackages(globalSettings.packages ?? []);
				if (found) {
					scope = "user";
					settingsManager.setPackages(updatedGlobalPackages);
				}
			}

			if (!found) {
				return reply.code(404).send({
					error: `Package not found: ${source}`,
					code: "NOT_FOUND",
				} satisfies ExtensionApiError);
			}

			await appendAuditEntry({
				timestamp: Date.now(),
				action: "disable",
				source,
				scope,
				success: true,
				detail: extensionPath
					? `Disabled extension ${extensionPath} in package ${source}`
					: `Disabled all extensions in package ${source}`,
			});

			return {
				success: true,
				source,
				extensionPath: extensionPath ?? "all",
				message: extensionPath
					? `Disabled ${extensionPath} in package ${source}`
					: `Disabled all extensions in package ${source}`,
			};
		} catch (error) {
			const errorMessage = error instanceof Error ? error.message : String(error);
			fastify.log.error({ error, source }, "Failed to disable extension");
			return reply.code(500).send({
				error: `Failed to disable extension: ${errorMessage}`,
				code: "DISABLE_ERROR",
				detail: errorMessage,
			} satisfies ExtensionApiError);
		}
	});
}

/**
 * ProposalCard — A single proposal card for the Lead Agent Dashboard (P8.G / P9.F).
 *
 * Displays proposal title, phase, separate planning and execution approval
 * gates, evidence summary, and approval requirements. Clicking a card opens
 * the detail view.
 *
 * Acceptance Criteria (P9.F):
 * - Dashboard shows planning approval and execution approval as separate gates (AC1)
 * - Makes approval requirements clear (AC3)
 */

import type { ApprovalGateStatus, ProposalResponse } from "../types";

// ---------------------------------------------------------------------------
// Styling tokens (matching App.tsx)
// ---------------------------------------------------------------------------

const BORD = "border-[#E8E6E1] dark:border-[#333]";
const SURF = "bg-white dark:bg-[#1E1E1E]";
const TXT = "text-stone-800 dark:text-stone-200";
const MUT = "text-stone-400 dark:text-stone-500";
const ACC_BG = "bg-[#EBF2FF] dark:bg-[#1A2A44]";

// ---------------------------------------------------------------------------
// Gate status badge configs
// ---------------------------------------------------------------------------

const GATE_CONFIG: Record<
	ApprovalGateStatus,
	{ label: string; color: string; bg: string; darkColor: string; darkBg: string }
> = {
	pending: {
		label: "Pending",
		color: "text-amber-600",
		bg: "bg-amber-50",
		darkColor: "dark:text-amber-400",
		darkBg: "dark:bg-amber-900/30",
	},
	approved: {
		label: "Approved",
		color: "text-emerald-600",
		bg: "bg-emerald-50",
		darkColor: "dark:text-emerald-400",
		darkBg: "dark:bg-emerald-900/30",
	},
	rejected: {
		label: "Rejected",
		color: "text-red-600",
		bg: "bg-red-50",
		darkColor: "dark:text-red-400",
		darkBg: "dark:bg-red-900/30",
	},
	changes_requested: {
		label: "Changes Req.",
		color: "text-purple-600",
		bg: "bg-purple-50",
		darkColor: "dark:text-purple-400",
		darkBg: "dark:bg-purple-900/30",
	},
};

function getGateConfig(status: ApprovalGateStatus) {
	return GATE_CONFIG[status] ?? GATE_CONFIG.pending;
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function formatTimestamp(ts: number): string {
	return new Date(ts).toLocaleString(undefined, {
		month: "short",
		day: "numeric",
		hour: "2-digit",
		minute: "2-digit",
	});
}

function evidenceSummary(evidence: ProposalResponse["evidence"]): string[] {
	const lines: string[] = [];

	const plannerOutput = evidence.plannerOutput ?? {};
	const queue = evidence.queue ?? {};

	// Workspace count from queue
	const workspaces = (queue as any).workspaces;
	if (Array.isArray(workspaces)) {
		lines.push(`${workspaces.length} workspace(s)`);
	}

	// Parallelism from planner output
	const parallelism = (plannerOutput as any).predictedParallelism;
	if (parallelism) {
		lines.push(
			`Parallelism: ${parallelism.effective ?? "?"}/${parallelism.requested ?? "?"}`,
		);
	}

	// Warnings/suggestions
	const warnings = (plannerOutput as any).plannerWarnings;
	const suggestions = (plannerOutput as any).plannerSuggestions;
	if (Array.isArray(warnings) && warnings.length > 0) {
		lines.push(`${warnings.length} warning(s)`);
	}
	if (Array.isArray(suggestions) && suggestions.length > 0) {
		lines.push(`${suggestions.length} suggestion(s)`);
	}

	// Optimization proposals
	const optimizations = evidence.optimizationProposals;
	if (Array.isArray(optimizations) && optimizations.length > 0) {
		lines.push(`${optimizations.length} optimization(s)`);
	}

	if (lines.length === 0) {
		lines.push("No evidence summary available");
	}

	return lines;
}

// ---------------------------------------------------------------------------
// Component
// ---------------------------------------------------------------------------

interface ProposalCardProps {
	proposal: ProposalResponse;
	selected: boolean;
	onClick: () => void;
}

export function ProposalCard({ proposal, selected, onClick }: ProposalCardProps) {
	const evidenceLines = evidenceSummary(proposal.evidence);
	const auditCount = proposal.auditTrail.length;
	const lastAction =
		auditCount > 0
			? proposal.auditTrail[auditCount - 1]
			: null;

	const planCfg = getGateConfig(proposal.planningApproval.status);
	const execCfg = getGateConfig(proposal.executionApproval.status);

	return (
		<button
			onClick={onClick}
			className={`w-full text-left border-b ${BORD} transition-colors ${
				selected
					? `${ACC_BG}`
					: `${SURF} hover:bg-stone-50 dark:hover:bg-[#2A2A2A]`
			}`}
		>
			<div className="px-4 py-3">
				{/* Header row: title + dry-run/budget summary */}
				<div className="flex items-start justify-between gap-2 mb-1">
					<h3 className={`text-sm font-semibold ${TXT} truncate flex-1 min-w-0`}>
						{proposal.title}
					</h3>
					{proposal.dryRunStatus === "passed" && proposal.budgetState === "valid" && (
						<span className="shrink-0 text-[9px] font-medium text-emerald-600 dark:text-emerald-400 bg-emerald-50 dark:bg-emerald-900/20 px-1.5 py-0.5 rounded-full border border-emerald-200 dark:border-emerald-800">
							Ready to execute
						</span>
					)}
				</div>

				{/* P9.F AC1: Separate planning and execution approval gates */}
				<div className="flex items-center gap-2 mb-1.5">
					<span
						className={`inline-flex items-center gap-1 shrink-0 text-[9px] font-medium px-1.5 py-0.5 rounded-full ${planCfg.color} ${planCfg.bg} ${planCfg.darkColor} ${planCfg.darkBg} border ${BORD}`}
					>
						Plan: {planCfg.label}
					</span>
					<span
						className={`inline-flex items-center gap-1 shrink-0 text-[9px] font-medium px-1.5 py-0.5 rounded-full ${execCfg.color} ${execCfg.bg} ${execCfg.darkColor} ${execCfg.darkBg} border ${BORD}`}
					>
						Exec: {execCfg.label}
					</span>
					{proposal.selfModificationApproval.status === "approved" && (
						<span className="inline-flex items-center gap-1 shrink-0 text-[9px] font-medium px-1.5 py-0.5 rounded-full text-blue-600 dark:text-blue-400 bg-blue-50 dark:bg-blue-900/20 border border-blue-200 dark:border-blue-800">
							Self-mod OK
						</span>
					)}
				</div>

				{/* Phase + submission time */}
				<div className="flex items-center gap-2 mb-1.5">
					<span className={`text-[10px] font-mono ${MUT}`}>
						{proposal.phase}
					</span>
					<span className={`text-[10px] ${MUT}`}>
						{formatTimestamp(proposal.submittedAt)}
					</span>
					{proposal.actionedAt && (
						<span className={`text-[10px] ${MUT}`}>
							· actioned {formatTimestamp(proposal.actionedAt)}
						</span>
					)}
					{/* Dry-run + budget indicators */}
					<span className={`text-[9px] ${proposal.dryRunStatus === "passed" ? "text-emerald-500" : "text-stone-400"}`}>
						Dry-run: {proposal.dryRunStatus}
					</span>
					<span className={`text-[9px] ${proposal.budgetState === "valid" ? "text-emerald-500" : "text-stone-400"}`}>
						Budget: {proposal.budgetState}
					</span>
				</div>

				{/* Evidence summary */}
				<div className="flex flex-wrap gap-1.5 mb-1.5">
					{evidenceLines.map((line, i) => (
						<span
							key={i}
							className={`text-[10px] px-1.5 py-0.5 rounded ${MUT} bg-stone-50 dark:bg-[#2A2A2A] border ${BORD}`}
						>
							{line}
						</span>
					))}
				</div>

				{/* Audit trail summary */}
				{lastAction && (
					<div className={`text-[10px] ${MUT} flex items-center gap-1`}>
						<span>
							{lastAction.action === "submitted"
								? "Submitted"
								: lastAction.action === "approved" ||
										lastAction.action === "approved_for_planning" ||
										lastAction.action === "approved_for_execution"
									? "Approved"
									: lastAction.action === "self_modification_approved"
										? "Self-mod approved"
										: ""}{" "}
							{lastAction.actor !== "system" ? `by ${lastAction.actor}` : ""}
						</span>
						{lastAction.reason && (
							<span className="truncate">· "{lastAction.reason}"</span>
						)}
					</div>
				)}

				{/* Approval gates summary for pending proposals */}
				{proposal.planningApproval.status !== "approved" && (
					<div className={`mt-1.5 text-[10px] text-amber-600 dark:text-amber-400 bg-amber-50 dark:bg-amber-900/20 px-2 py-1 rounded ${BORD} border`}>
						Requires planning approval before execution
					</div>
				)}

				{/* Rejection reason */}
				{proposal.planningApproval.status === "rejected" && proposal.rejectionReason && (
					<div
						className={`mt-1.5 text-[10px] text-red-600 dark:text-red-400 bg-red-50 dark:bg-red-900/20 px-2 py-1 rounded ${BORD} border`}
					>
						Reason: {proposal.rejectionReason}
					</div>
				)}
			</div>
		</button>
	);
}

interface StatCardProps {
  icon: React.ElementType;
  label: string;
  value: string;
  accent?: boolean;
  /** Optional sublabel explaining the formula or source of the value. */
  sublabel?: string;
}

export function StatCard({ icon: Icon, label, value, accent = false, sublabel }: StatCardProps) {
  return (
    <div className="flex flex-col gap-2 p-4 rounded-xl border border-[#E8E6E1] dark:border-[#333] bg-white dark:bg-[#1E1E1E]">
      <div className={`flex items-center gap-1.5 ${accent ? "text-blue-600 dark:text-blue-400" : "text-stone-400 dark:text-stone-500"}`}>
        <Icon size={13} strokeWidth={1.8} />
        <span className="text-[10px] font-semibold tracking-widest uppercase">{label}</span>
      </div>
      <p className="text-xl font-semibold text-stone-800 dark:text-stone-200 tracking-tight leading-none">{value}</p>
      {sublabel && <p className="text-[9px] text-stone-400 dark:text-stone-500 leading-none">{sublabel}</p>}
    </div>
  );
}

