export function useWorktreeCleanup() {
	const queryClient = useQueryClient();

	const bulkCleanupMutation = useMutation({
		mutationFn: postWorktreeCleanup,
		onSuccess: () => {
			queryClient.invalidateQueries({ queryKey: ["scale", "worktrees"] });
		},
