	// -----------------------------------------------------------------------
	// GET /api/skills/audit-events — List skill audit events (denied invocations)
	// -----------------------------------------------------------------------
	fastify.get<{
		Querystring: {
			skillName?: string;
			action?: string;
			verdict?: string;
			planExecutionId?: string;
			workspaceId?: string;
			limit?: number;
			offset?: number;
		};
	}>("/api/skills/audit-events", async (request, reply) => {
		try {
			const { skillName, action, verdict, planExecutionId, workspaceId, limit, offset } = request.query;

			let events: SkillAuditEvent[] = [];

			const backend = detectStateStoreBackend();
			if (backend === "postgres") {
				try {
					const { getKysely, SkillAuditEventRepository } = await import("@earendil-works/pi-db");
					const db = getKysely();
					const repo = new SkillAuditEventRepository(db);
					const dbEvents = await repo.list({
						skill_name: skillName,
						action,
						verdict,
						plan_execution_id: planExecutionId,
						workspace_id: workspaceId,
						limit: limit ? Number(limit) : undefined,
						offset: offset ? Number(offset) : undefined,
					});
					events = dbEvents.map((e) => ({
						id: e.id,
						skillName: e.skill_name,
						action: e.action,
						verdict: e.verdict,
						reason: e.reason ?? "",
						actor: e.actor ?? undefined,
						policyRuleId: e.policy_rule_id ?? undefined,
						protectionLevel: e.protection_level ?? undefined,
						planExecutionId: e.plan_execution_id ?? undefined,
						workspaceId: e.workspace_id ?? undefined,
						occurredAt: e.occurred_at,
					}));
				} catch {
					events = memoryAuditEvents;
				}
			} else {
				events = memoryAuditEvents;

				// Apply filters
				if (skillName) events = events.filter((e) => e.skillName === skillName);
				if (action) events = events.filter((e) => e.action === action);
				if (verdict) events = events.filter((e) => e.verdict === verdict);
				if (planExecutionId) events = events.filter((e) => e.planExecutionId === planExecutionId);
				if (workspaceId) events = events.filter((e) => e.workspaceId === workspaceId);
			}

			const resolvedLimit = limit ? Number(limit) : 50;
			const resolvedOffset = offset ? Number(offset) : 0;
			const paginated = events.slice(resolvedOffset, resolvedOffset + resolvedLimit);

			return reply.send({
				success: true,
				events: paginated,
				count: paginated.length,
				total: events.length,
			});
		} catch (error) {
			fastify.log.error({ error }, "Failed to list skill audit events");
			return reply.code(500).send({
				success: false,
				error: "Failed to list skill audit events",
				message: String(error),
			});
		}
	});
