/** Extension status returned by the API. */
export interface ExtensionInfo {
	source: string;
	scope: "user" | "project";
	type: "package" | "local" | "unknown";
	installedPath?: string;
	enabled: boolean;
	filtered: boolean;
	hasRollbackBackup: boolean;
	error?: string;
}

/** Audit entry for extension lifecycle operations. */
export interface AuditEntry {
	timestamp: number;
	action: "install" | "update" | "rollback" | "enable" | "disable" | "remove";
	source: string;
	scope: "user" | "project";
	success: boolean;
	detail?: string;
	error?: string;
}

/** Health check result for a single extension. */
export interface ExtensionHealth {
	source: string;
	healthy: boolean;
	installed: boolean;
	version?: string;
	error?: string;
}

/** Result of a permission/validation policy check. */
export interface PolicyCheckResult {
	allowed: boolean;
	reason?: string;
	severity?: "error" | "warning";
}

/** Structured error response. */
export interface ExtensionApiError {
	error: string;
	code: string;
	detail?: string;
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/**
 * Get the .pi directory path.
 */
function getPiDir(): string {
	return resolve(getWorkspaceRoot(), ".pi");
}

/**
 * Get the audit log file path.
 */
function getAuditPath(): string {
	return join(getPiDir(), AUDIT_LOG_PATH);
}

/**
 * Get the backups directory path.
 */
function getBackupDir(): string {
	const dir = join(getPiDir(), "extensions", "backups");
	if (!existsSync(dir)) {
		mkdirSync(dir, { recursive: true });
	}
	return dir;
}

/**
 * Ensure the extensions metadata directory exists.
 */
function ensureExtensionsDir(): void {
	const dir = join(getPiDir(), "extensions");
	if (!existsSync(dir)) {
		mkdirSync(dir, { recursive: true });
	}
}

/**
 * Create a PackageManager instance from the shared settings manager.
 */
function createPackageManager(): PackageManager {
	const workspaceRoot = getWorkspaceRoot();
	const agentDir = resolve(workspaceRoot, ".pi");
	const settingsManager = getSettingsManager();
	return new DefaultPackageManager({
		cwd: workspaceRoot,
		agentDir,
		settingsManager,
	});
}

/**
 * Append an audit entry to the audit log.
 */
async function appendAuditEntry(entry: AuditEntry): Promise<void> {
	ensureExtensionsDir();
	const auditPath = getAuditPath();
	let entries: AuditEntry[] = [];
	try {
		const content = await readFile(auditPath, "utf-8");
		entries = JSON.parse(content);
	} catch {
		// File doesn't exist or is invalid, start fresh
	}
	entries.push(entry);
	await writeFile(auditPath, JSON.stringify(entries, null, 2), "utf-8");
}

