export function isLocalPathSource(source: string): boolean {
	return source.startsWith(".") || source.startsWith("/") || source.startsWith("~");
}

/**
 * Extract a sanitized filename-safe identifier from a source string
 * for use as a backup key.
 */
export function sanitizeSourceKey(source: string): string {
	return source.replace(/[^a-zA-Z0-9_@./:-]/g, "_").replace(/[/:]/g, "_");
}

/**
 * Create a backup of an installed extension before updating.
 */
async function createBackup(source: string, installedPath: string | undefined): Promise<void> {
	if (!installedPath || !existsSync(installedPath)) return;

	const backupDir = getBackupDir();
	const key = sanitizeSourceKey(source);
	const backupPath = join(backupDir, `${key}${BACKUP_SUFFIX}`);

	// Remove old backup if exists
	try {
		await rm(backupPath, { recursive: true, force: true });
	} catch {
		// ignore
	}

	// Copy current installation to backup
	await cp(installedPath, backupPath, { recursive: true });
}

/**
 * Check if a rollback backup exists for a source.
 */
async function hasBackup(source: string): Promise<boolean> {
	const backupDir = getBackupDir();
	const key = sanitizeSourceKey(source);
	const backupPath = join(backupDir, `${key}${BACKUP_SUFFIX}`);
	return existsSync(backupPath);
}

/**
 * Get the backup path for a source.
 */
function getBackupPath(source: string): string {
	const backupDir = getBackupDir();
	const key = sanitizeSourceKey(source);
	return join(backupDir, `${key}${BACKUP_SUFFIX}`);
}

/**
 * Perform a policy check before installing or enabling an extension.
 *
 * Checks:
 * - Manifest validity (package.json exists and is valid JSON for packages)
 * - Permission safety (no obviously dangerous patterns in the manifest)
 * - Version compatibility (basic format check)
 */
export async function checkExtensionPolicy(source: string): Promise<PolicyCheckResult> {
	// If it's a local path, check the extension file directly
	if (isLocalPathSource(source)) {
		const resolvedPath = resolve(getWorkspaceRoot(), source);
		if (!existsSync(resolvedPath)) {
			return { allowed: false, reason: `Extension path does not exist: ${source}`, severity: "error" };
		}

		// For local extensions, check if it's a directory with package.json
		if (existsSync(join(resolvedPath, "package.json"))) {
			try {
				const pkgContent = await readFile(join(resolvedPath, "package.json"), "utf-8");
				const pkg = JSON.parse(pkgContent);
				if (!pkg.name) {
					return {
						allowed: false,
						reason: "Extension manifest (package.json) is missing required 'name' field",
						severity: "error",
					};
				}
			} catch (err) {
				return {
					allowed: false,
					reason: `Invalid manifest: ${err instanceof Error ? err.message : String(err)}`,
					severity: "error",
				};
			}
		}

		return { allowed: true };
	}

	// For package sources (npm/git), we can't fully validate without downloading
	// but we do basic format checks
	if (
		source.startsWith("npm:") ||
		source.startsWith("git:") ||
		source.startsWith("https://") ||
		source.startsWith("ssh://")
	) {
		return { allowed: true };
	}

	// If it starts with @ or contains a /, it might be an npm package shorthand
	if (source.includes("/")) {
		return { allowed: true };
	}

	return {
		allowed: false,
		reason: `Unknown source format: ${source}. Use npm:<package>, git:<url>, or a local path.`,
		severity: "error",
	};
}

/**
 * Read the current version from an installed path.
 */
export async function readVersion(installedPath: string | undefined): Promise<string | undefined> {
	if (!installedPath) return undefined;
	const pkgPath = join(installedPath, "package.json");
	try {
		const content = await readFile(pkgPath, "utf-8");
		const pkg = JSON.parse(content);
		return pkg.version;
	} catch {
		return undefined;
	}
}

