	const qs = searchParams.toString();
	const url = `${API_BASE}/api/memory/provenance${qs ? `?${qs}` : ""}`;
	const res = await fetch(url);
	if (!res.ok) {
		throw new Error(`HTTP ${res.status}: ${res.statusText}`);
	}
	return res.json();
}

