export { AuditEventRepository } from "./audit-event.js";
export { JournalEventRepository } from "./journal.js";
export { MemoryVectorRepository } from "./memory-vector.js";
export { PlanExecutionRepository } from "./plan-execution.js";
export { PlanRevisionRepository } from "./plan-revision.js";
export { ProjectRepository } from "./project.js";
export { ProposalRepository } from "./proposal.js";
export { ProposalRubricRepository } from "./proposal-rubric.js";
export { ProposalScoreRepository } from "./proposal-score.js";
export { WorkspaceExecutionRepository } from "./workspace-execution.js";
export { WorkspaceLogRepository } from "./workspace-log.js";

/**
 * Proposal repository.
 *
 * Provides CRUD operations for proposals backed by PostgreSQL.
 * Supports the Proposal Inbox (P8.B) with persistence, audit trail,
 * and approval gating.
 */

import type { Kysely } from "kysely";
import type { Database, NewProposal, Proposal, ProposalUpdate } from "../types.js";

/**
 * Filter options for listing proposals.
 */
export interface ProposalFilter {
	status?: string;
	phase?: string;
	limit?: number;
	offset?: number;
}

/**
 * Source artifact descriptor.
 *
 * Represents an artifact (file, report, etc.) that serves as
 * the source evidence for a proposal (P8 output before plan generation).
 */
export interface SourceArtifact {
	/** Path to the source artifact file */
	path: string;
	/** Human-readable label */
	label: string;
	/** Artifact type (e.g., "remediation-plan", "dag", "risk-report") */
	type: string;
	/** Size in bytes (optional) */
	size?: number;
	/** Content hash for integrity checking (optional) */
	hash?: string;
	/** ISO timestamp when the artifact was recorded */
	recorded_at: string;
}

/**
 * Proposal repository
 */
export class ProposalRepository {
	constructor(private db: Kysely<Database>) {}

	/**
	 * Create a new proposal.
	 *
	 * @param data - Proposal data
	 * @returns Created proposal
	 */
	async create(data: NewProposal): Promise<Proposal> {
		return this.db.insertInto("proposals").values(data).returningAll().executeTakeFirstOrThrow();
	}

	/**
	 * Find proposal by ID.
	 *
	 * @param id - Proposal UUID
	 * @returns Proposal or undefined
	 */
	async findById(id: string): Promise<Proposal | undefined> {
		return this.db.selectFrom("proposals").selectAll().where("id", "=", id).executeTakeFirst();
	}

	/**
	 * Find proposal by unique proposal key.
	 *
	 * @param proposalKey - Proposal key (e.g., "prop-xxx-yyy")
	 * @returns Proposal or undefined
	 */
	async findByKey(proposalKey: string): Promise<Proposal | undefined> {
		return this.db.selectFrom("proposals").selectAll().where("proposal_key", "=", proposalKey).executeTakeFirst();
	}

	/**
	 * List proposals for a project.
	 *
	 * @param projectId - Project UUID
	 * @param filter - Optional filter criteria
	 * @returns Array of proposals
	 */
	async listByProject(projectId: string, filter?: ProposalFilter): Promise<Proposal[]> {
		let query = this.db.selectFrom("proposals").selectAll().where("project_id", "=", projectId);

		if (filter?.status) {
			query = query.where("status", "=", filter.status);
		}
		if (filter?.phase) {
			query = query.where("phase", "=", filter.phase);
		}

		const limit = filter?.limit ?? 50;
		const offset = filter?.offset ?? 0;

		return query.orderBy("submitted_at", "desc").limit(limit).offset(offset).execute();
	}

	/**
	 * List all proposals across projects.
	 *
	 * @param filter - Optional filter criteria
	 * @returns Array of proposals
	 */
	async listAll(filter?: ProposalFilter): Promise<Proposal[]> {
		let query = this.db.selectFrom("proposals").selectAll();

		if (filter?.status) {
			query = query.where("status", "=", filter.status);
		}
		if (filter?.phase) {
			query = query.where("phase", "=", filter.phase);
		}

		const limit = filter?.limit ?? 100;
		const offset = filter?.offset ?? 0;

		return query.orderBy("submitted_at", "desc").limit(limit).offset(offset).execute();
	}

	/**
	 * Update a proposal.
	 *
	 * @param id - Proposal UUID
	 * @param data - Fields to update
	 * @returns Updated proposal
	 */
	async update(id: string, data: ProposalUpdate): Promise<Proposal | undefined> {
		return this.db
			.updateTable("proposals")
			.set({ ...data, updated_at: new Date().toISOString() })
			.where("id", "=", id)
			.returningAll()
			.executeTakeFirst();
	}

	/**
	 * Update proposal status.
	 *
	 * @param id - Proposal UUID
	 * @param status - New status
	 * @returns Updated proposal
	 */
	async updateStatus(id: string, status: string): Promise<Proposal | undefined> {
		const update: ProposalUpdate = { status };
		if (status === "approved" || status === "rejected") {
			update.actioned_at = new Date().toISOString();
		}
		return this.update(id, update);
	}

	/**
	 * Record source artifacts for a proposal (AC 1: record P8 output before plan generation).
	 *
	 * Adds source artifacts and sets the source_recorded_at timestamp.
	 * This should be called before any plan is generated from the proposal.
	 *
	 * @param id - Proposal UUID
	 * @param artifacts - Array of source artifact descriptors
	 * @returns Updated proposal
	 */
	async recordSourceArtifacts(id: string, artifacts: SourceArtifact[]): Promise<Proposal | undefined> {
		const now = new Date().toISOString();
		return this.db
			.updateTable("proposals")
			.set({
				source_artifacts: JSON.stringify(artifacts) as any,
				source_recorded_at: now,
				updated_at: now,
			})
			.where("id", "=", id)
			.returningAll()
			.executeTakeFirst();
	}

	/**
	 * Get source artifacts for a proposal.
	 *
	 * @param id - Proposal UUID
	 * @returns Array of source artifacts or undefined if proposal not found
	 */
	async getSourceArtifacts(id: string): Promise<SourceArtifact[] | undefined> {
		const proposal = await this.findById(id);
		return proposal?.source_artifacts as SourceArtifact[] | undefined;
	}

	/**
	 * Check if source artifacts have been recorded for a proposal.
	 *
	 * @param id - Proposal UUID
	 * @returns True if source artifacts are recorded
	 */
	async hasSourceArtifacts(id: string): Promise<boolean> {
		const proposal = await this.findById(id);
		return proposal?.source_recorded_at != null;
	}

	/**
	 * Count proposals matching optional filters.
	 *
	 * @param projectId - Optional project UUID
	 * @param status - Optional status filter
	 * @returns Count of matching proposals
	 */
	async count(projectId?: string, status?: string): Promise<number> {
		let query = this.db.selectFrom("proposals").select(this.db.fn.countAll<number>().as("count"));

		if (projectId) {
			query = query.where("project_id", "=", projectId);
		}
		if (status) {
			query = query.where("status", "=", status);
		}

		const result = await query.executeTakeFirst();
		return Number(result?.count ?? 0);
	}

	/**
	 * Delete a proposal.
	 *
	 * @param id - Proposal UUID
	 * @returns True if deleted
	 */
	async delete(id: string): Promise<boolean> {
		const result = await this.db.deleteFrom("proposals").where("id", "=", id).executeTakeFirst();
		return result.numDeletedRows > 0n;
	}
}

	 */
	computeConfidence(
		sourceCount: number,
		retryCount: number,
		outcomeCount: number,
	): number {
		// Base confidence from minimum evidence requirement
		let confidence = BASE_CONFIDENCE;

		// Boost from multiple sources (diminishing returns)
		if (sourceCount >= MIN_SOURCE_REFS) {
			confidence += Math.min(
				(sourceCount - MIN_SOURCE_REFS) * 0.1,
				0.3,
			);
		}

		// Boost from multiple outcomes corroborating the pattern
		if (outcomeCount > 1) {
			confidence += Math.min(
				(outcomeCount - 1) * 0.05,
				0.15,
			);
		}

		// Penalty for retries (reduces confidence in reliability)
		if (retryCount > 0) {
			confidence -= retryCount * RETRY_PENALTY;
		}

		return Math.max(MIN_CONFIDENCE, Math.min(MAX_CONFIDENCE, confidence));
	}

	// -----------------------------------------------------------------------
	// Source mapping
	// -----------------------------------------------------------------------

	/**
	 * Filter source references by ID prefix.
	 * Used to find relevant evidence sources for a category.
	 *
	 * @param sources - All sources from the report
	 * @param prefix - The prefix to filter by (e.g. "workspace-")
	 * @returns Filtered source references
	 */
	private filterSourcesByIdPrefix(
		sources: SourceRef[],
		prefix: string,
	): SourceRef[] {
		return sources.filter((s) => s.id.startsWith(prefix));
	}

	/**
	 * Map failed entries to source references from workspace outcomes.
	 *
	 * @param entries - Failed workspace descriptions or IDs
	 * @param outcomes - All workspace outcomes
	 * @returns Array of source references for the failures
	 */
	mapFailuresToSources(
		entries: string[],
		outcomes: WorkspaceOutcome[],
	): SourceRef[] {
		const sources: SourceRef[] = [];

		for (const entry of entries) {
			// Try to match the entry to a workspace outcome by ID
			const matchingOutcome = outcomes.find(
				(o) =>
					o.workspaceId === entry ||
					o.summary?.includes(entry),
			);

			if (matchingOutcome) {
				sources.push({
					type: "workspace",
					id: `workspace-${matchingOutcome.workspaceId}`,
					description:
						matchingOutcome.summary ??
						`Workspace outcome for ${matchingOutcome.workspaceId}`,
				});
			} else {
				sources.push({
					type: "workspace",
					id: `failure-${entry.replace(/[^a-zA-Z0-9_-]/g, "_")}`,
					description: entry,
				});
			}
		}

		return sources;
	}

	/**
	 * Map workspace IDs to source references from workspace outcomes.
	 *
	 * @param workspaceIds - List of workspace IDs or descriptions
	 * @param outcomes - All workspace outcomes
	 * @returns Array of source references
	 */
	private mapOutcomesToSourcesFromList(
		workspaceIds: string[],
		outcomes: WorkspaceOutcome[],
	): SourceRef[] {
		const sources: SourceRef[] = [];

		for (const id of workspaceIds) {
			const matchingOutcome = outcomes.find(
				(o) => o.workspaceId === id || o.summary?.includes(id),
			);

			if (matchingOutcome) {
				sources.push({
					type: "workspace",
					id: `workspace-${matchingOutcome.workspaceId}`,
					description:
						matchingOutcome.summary ??
						`Workspace outcome for ${matchingOutcome.workspaceId}`,
				});
			} else {
				sources.push({
					type: "workspace",
					id: `workspace-${id.replace(/[^a-zA-Z0-9_-]/g, "_")}`,
					description: id,
				});
			}
		}

		return sources;
	}

	// -----------------------------------------------------------------------
	// Formatting
	// -----------------------------------------------------------------------

	/**
	 * Format a memory proposal output as a partial Proposal record.
	 *
	 * This allows memory proposals to be surfaced through the proposal
	 * inbox and approval workflow if desired.
	 *
	 * @param output - The memory proposal output
	 * @returns A partial Proposal record
	 */
	formatAsProposal(output: MemoryProposalOutput): Partial<Proposal> {
		return {
			type: "memory_proposal",
			title: output.memory.title ?? "Untitled Memory Proposal",
			description: output.memory.content ?? "",
			evidence: {
				memoryIds: [],
				observationIds: [],
				sourceRefs: this.toMemorySourceRefs(output.evidence),
				confidence: output.confidence,
				evidenceSummary: this.buildEvidenceSummary(output.evidence),
			},
			risk: {
				level: "low",
				factors: [],
				mitigation: [],
				affectedSystems: [],
				impactDescription: `Memory proposal for type: ${output.memory.type ?? "unknown"}`,
			},
			status: "draft",
			submittedBy: "pi",
			tags: ["memory-proposal", "auto-generated", "reflection"],
			metadata: {
				memoryType: output.memory.type,
				confidence: output.confidence,
				evidenceCount: output.evidence.length,
			},
		};
	}

	// -----------------------------------------------------------------------
	// Private helpers
	// -----------------------------------------------------------------------

	/**
	 * Convert reflection SourceRefs to MemorySourceRefs for persistence.
	 */
	private toMemorySourceRefs(sources: SourceRef[]): MemorySourceRef[] {
		return sources.map((s) => ({
			type: "reflection",
			path: `reflection:${s.id}`,
			id: s.id,
			timestamp: new Date().toISOString(),
		}));
	}

	/**
	 * Build an evidence summary from source references.
	 */
	private buildEvidenceSummary(sources: SourceRef[]): string {
		if (sources.length === 0) return "No evidence available";
		if (sources.length === 1) return `Based on ${sources[0].description}`;
		return `Based on ${sources.length} evidence sources: ${sources.map((s) => s.description).join(", ")}`;
	}

	/**
	 * Group failed entries into patterns based on error types and outcomes.
	 */
	private groupFailurePatterns(
		failed: string[],
		outcomes: WorkspaceOutcome[],
	): Map<string, string[]> {
		const grouped = new Map<string, string[]>();

		for (const entry of failed) {
			const outcome = outcomes.find(
				(o) => o.workspaceId === entry || o.summary?.includes(entry),
			);

			if (outcome?.errorTypes && outcome.errorTypes.length > 0) {
				// Group by the first error type as the pattern
				const pattern = outcome.errorTypes[0];
				if (!grouped.has(pattern)) {
					grouped.set(pattern, []);
				}
				grouped.get(pattern)!.push(entry);
			} else {
				// No error types — group as generic
				const pattern = "generic-failure";
				if (!grouped.has(pattern)) {
					grouped.set(pattern, []);
				}
				grouped.get(pattern)!.push(entry);
			}
		}

		return grouped;
	}

	/**
	 * Compute total retries for specific entries across all outcomes.
	 */
	private computeTotalRetriesForEntries(
		entries: string[],
		outcomes: WorkspaceOutcome[],
	): number {
		let total = 0;
		for (const entry of entries) {
			const outcome = outcomes.find(
				(o) => o.workspaceId === entry || o.summary?.includes(entry),
			);
			total += outcome?.retryCount ?? 0;
		}
		return total;
	}

	/**
	 * Compute total retries from a list of workspace IDs.
	 */
	private computeTotalRetriesFromList(
		workspaceIds: string[],
		outcomes: WorkspaceOutcome[],
	): number {
		let total = 0;
		for (const id of workspaceIds) {
			const outcome = outcomes.find((o) => o.workspaceId === id);
			total += outcome?.retryCount ?? 0;
		}
		return total;
	}

	/**
	 * Extract a brief description from a workspace entry.
	 */
	private describeEntry(entry: string): string {
		// If it looks like a workspace ID, return it as-is
		if (entry.length <= 20) return entry;
		// Otherwise truncate
		return entry.length > 80 ? `${entry.slice(0, 80)}...` : entry;
	}

	/**
	 * Build content for a failure memory proposal.
	 */
	private buildFailureContent(
		pattern: string,
		entries: string[],
		outcomes: WorkspaceOutcome[],
	): string {
		const lines: string[] = [
			`Failure Pattern: ${pattern}`,
			"",
			`${entries.length} workspace(s) exhibited this failure pattern.`,
			"",
			"Affected Workspaces:",
		];

		for (const entry of entries) {
			const outcome = outcomes.find(
				(o) => o.workspaceId === entry || o.summary?.includes(entry),
			);
			lines.push(
				`- ${entry}${outcome ? ` (retries: ${outcome.retryCount})` : ""}`,
			);
		}

		lines.push(
			"",
			"Generated by MemoryProposalGenerator from reflection analysis.",
		);

		return lines.join("\n");
	}

	/**
	 * Build a summary for a failure memory proposal.
	 */
	private buildFailureSummary(pattern: string, entries: string[]): string {
		return `${entries.length} workspace(s) failed with pattern: ${pattern}`;
	}

	/**
	 * Build content for an individual failure memory proposal.
	 */
	private buildIndividualFailureContent(
		entry: string,
		outcomes: WorkspaceOutcome[],
	): string {
		const outcome = outcomes.find(
			(o) => o.workspaceId === entry || o.summary?.includes(entry),
		);

		const lines: string[] = [
			`Failure: ${entry}`,
			"",
		];

		if (outcome) {
			lines.push(`Status: ${outcome.status}`);
			lines.push(`Retries: ${outcome.retryCount}`);
			if (outcome.errorTypes && outcome.errorTypes.length > 0) {
				lines.push(`Error Types: ${outcome.errorTypes.join(", ")}`);
			}
			if (outcome.summary) {
				lines.push(`Summary: ${outcome.summary}`);
			}
		}

		lines.push(
			"",
			"Generated by MemoryProposalGenerator from reflection analysis.",
		);

		return lines.join("\n");
	}

	/**
	 * Build content for a success execution memory proposal.
	 */
	private buildSuccessContent(
		worked: string[],
		outcomes: WorkspaceOutcome[],
	): string {
		const lines: string[] = [
			`${worked.length} workspace(s) completed successfully.`,
			"",
			"Successful Workspaces:",
		];

		for (const entry of worked) {
			const outcome = outcomes.find(
				(o) => o.workspaceId === entry || o.summary?.includes(entry),
			);
			lines.push(
				`- ${entry}${outcome ? ` (duration: ${outcome.duration}ms, retries: ${outcome.retryCount})` : ""}`,
			);
		}

		lines.push(
			"",
			"Generated by MemoryProposalGenerator from reflection analysis.",
		);

		return lines.join("\n");
	}

	/**
	 * Build content for an architecture memory proposal.
	 */
	private buildArchitectureContent(
		whatRan: string[],
		outcomes: WorkspaceOutcome[],
	): string {
		const lines: string[] = [
			`Execution topology with ${whatRan.length} workspace(s).`,
			"",
			"Workspaces:",
		];

		for (const id of whatRan) {
			const outcome = outcomes.find((o) => o.workspaceId === id);
			lines.push(
				`- ${id}: ${outcome?.status ?? "unknown"}${outcome ? ` (${outcome.duration}ms)` : ""}`,
			);
		}

		lines.push(
			"",
			"Generated by MemoryProposalGenerator from reflection analysis.",
		);

		return lines.join("\n");
	}

	/**
	 * Build failure content from a reflection report (no WorkspaceOutcome data).
	 */
	private buildReflectionFailureContent(report: ReflectionReport): string {
		const lines: string[] = [
			`${report.whatFailed.length} workspace(s) failed.`,
			"",
			"Failed Workspaces:",
		];

		for (const entry of report.whatFailed) {
			lines.push(`- ${entry}`);
		}

		lines.push("");
		lines.push(`Success rate: ${(report.successRate * 100).toFixed(1)}%`);
		lines.push(`Total retries across plan: ${report.retryCount}`);
		lines.push("");
		lines.push("Generated by MemoryProposalGenerator from reflection analysis.");

		return lines.join("\n");
	}

	/**
	 * Build success content from a reflection report (no WorkspaceOutcome data).
	 */
	private buildReflectionSuccessContent(report: ReflectionReport): string {
		const lines: string[] = [
			`${report.whatWorked.length} workspace(s) completed successfully.`,
			"",
			"Successful Workspaces:",
		];

		for (const entry of report.whatWorked) {
			lines.push(`- ${entry}`);
		}

		lines.push("");
		lines.push(`Success rate: ${(report.successRate * 100).toFixed(1)}%`);
		lines.push(`Total validation failures: ${report.validationFailures}`);
		lines.push("");
		lines.push("Generated by MemoryProposalGenerator from reflection analysis.");

		return lines.join("\n");
	}

	/**
	 * Build architecture content from a reflection report (no WorkspaceOutcome data).
	 */
	private buildReflectionArchitectureContent(report: ReflectionReport): string {
		const lines: string[] = [
			`Execution topology with ${report.whatRan.length} workspace(s).`,
			"",
			"Workspaces:",
		];

		for (const id of report.whatRan) {
			lines.push(`- ${id}`);
		}

		lines.push("");
		lines.push(`Total workspaces: ${report.workspaceCount}`);
		lines.push(`Duration: ${report.totalDuration}ms`);
		lines.push("");
		lines.push("Generated by MemoryProposalGenerator from reflection analysis.");

		return lines.join("\n");
	}
}

/**
 * Proposal Scorer.
 *
 * Core scoring engine that evaluates a proposal against a rubric's
 * criteria, computes weighted scores, and generates a structured
 * scoring output.
 */

import type { CriterionScore, Proposal, ProposalRubric, RubricCriterion } from "../types.js";

/**
 * Input for scoring a single proposal.
 */
export interface ScoringInput {
	/** The proposal to score */
	proposal: Pick<Proposal, "id" | "title" | "evidence" | "source_artifacts">;
	/** The rubric to score against */
	rubric: ProposalRubric;
	/**
	 * Pre-computed criterion scores. If provided, the scorer uses these
	 * directly instead of computing default scores.
	 */
	criterionScores?: CriterionScore[];
	/**
	 * Optional scoring context for generating rationale.
	 * Can include additional project context, phase info, etc.
	 */
	context?: Record<string, unknown>;
}

/**
 * Output from scoring a single proposal.
 */
export interface ScoringOutput {
	/** The proposal ID */
	proposal_id: string;
	/** The rubric ID */
	rubric_id: string;
	/** Individual criterion scores */
	scores: CriterionScore[];
	/** Weighted total score */
	total_score: number;
	/** Maximum possible weighted score */
	max_score: number;
	/** Percentage score (0-100) */
	percentage: number;
	/** Human-readable scoring summary */
	summary: string;
	/** Source of the scores ("engine" | "manual") */
	scored_by: string;
}

/**
 * Default scoring function when no manual scores are provided.
 *
 * Assigns a baseline score to each criterion based on evidence presence:
 * - If the proposal has evidence, each criterion gets max_score * 0.7
 * - If evidence includes source_artifacts, each criterion gets max_score * 0.85
 * - Otherwise, each criterion gets max_score * 0.5
 *
 * @param criteria - Rubric criteria
 * @param proposal - The proposal being scored
 * @returns Default criterion scores
 */
function computeDefaultScores(
	criteria: RubricCriterion[],
	proposal: Pick<Proposal, "evidence" | "source_artifacts">,
): CriterionScore[] {
	const hasEvidence = proposal.evidence && Object.keys(proposal.evidence).length > 0;
	const hasArtifacts = Array.isArray(proposal.source_artifacts) && proposal.source_artifacts.length > 0;

	const multiplier = hasArtifacts ? 0.85 : hasEvidence ? 0.7 : 0.5;

	return criteria.map((criterion) => ({
		criterion_name: criterion.name,
		score: Math.round(criterion.max_score * multiplier * 100) / 100,
		rationale: hasArtifacts
			? `Scored based on source artifacts and evidence presence`
			: hasEvidence
				? `Scored based on available evidence`
				: `Scored at baseline (no evidence or artifacts found)`,
	}));
}

/**
 * Compute the weighted total score from criterion scores and rubric criteria.
 *
 * @param scores - Individual criterion scores
 * @param criteria - Rubric criteria (for weights and max scores)
 * @returns Object with total_score, max_score, and percentage
 */
function computeWeightedScore(
	scores: CriterionScore[],
	criteria: RubricCriterion[],
): { total_score: number; max_score: number; percentage: number } {
	const criteriaMap = new Map(criteria.map((c) => [c.name, c]));

	let totalScore = 0;
	let maxScore = 0;

	for (const score of scores) {
		const criterion = criteriaMap.get(score.criterion_name);
		if (!criterion) continue;

		const weight = criterion.weight;
		const normalizedScore = criterion.max_score > 0 ? score.score / criterion.max_score : 0;
		totalScore += normalizedScore * weight;
		maxScore += weight;
	}

	// Normalize to a 0-100 scale
	const normalizedTotal = maxScore > 0 ? (totalScore / maxScore) * 100 : 0;
	const roundedTotal = Math.round(normalizedTotal * 100) / 100;

	return {
		total_score: roundedTotal,
		max_score: 100,
		percentage: roundedTotal,
	};
}

/**
 * Generate a human-readable summary of the scoring result.
 *
 * @param scores - Individual criterion scores
 * @param totalScore - Weighted total score
 * @returns Summary string
 */
function generateSummary(scores: CriterionScore[], totalScore: number): string {
	const rating =
		totalScore >= 90 ? "Excellent" : totalScore >= 75 ? "Good" : totalScore >= 50 ? "Fair" : "Needs Improvement";

	const highest = scores.reduce((best, s) => (s.score > best.score ? s : best), scores[0]);
	const lowest = scores.reduce((worst, s) => (s.score < worst.score ? s : worst), scores[0]);

	return (
		`${rating} (${totalScore.toFixed(1)}/100). ` +
		`Strongest criterion: "${highest?.criterion_name}" (${highest?.score.toFixed(1)}). ` +
		`Weakest criterion: "${lowest?.criterion_name}" (${lowest?.score.toFixed(1)}).`
	);
}

/**
 * Proposal Scorer.
 *
 * Evaluates proposals against rubrics and produces structured scoring
 * output with weighted totals, individual criterion scores, and summaries.
 */
export class ProposalScorer {
	/**
	 * Score a single proposal against a rubric.
	 *
	 * @param input - Scoring input with proposal, rubric, and optional manual scores
	 * @returns Scoring output with computed scores and summary
	 */
	score(input: ScoringInput): ScoringOutput {
		const { proposal, rubric, criterionScores, context: _context } = input;

		// Validate input
		if (!rubric.criteria || rubric.criteria.length === 0) {
			throw new Error(`Rubric "${rubric.name}" has no criteria defined`);
		}

		// Use provided scores or compute defaults
		const scores = criterionScores ?? computeDefaultScores(rubric.criteria, proposal);

		// Validate that all criteria have scores
		const criterionNames = new Set(rubric.criteria.map((c) => c.name));
		for (const score of scores) {
			if (!criterionNames.has(score.criterion_name)) {
				throw new Error(`Criterion "${score.criterion_name}" not found in rubric "${rubric.name}"`);
			}
		}

		// Compute weighted score
		const { total_score, max_score, percentage } = computeWeightedScore(scores, rubric.criteria);

		// Generate summary
		const summary = generateSummary(scores, total_score);

		return {
			proposal_id: proposal.id,
			rubric_id: rubric.id,
			scores,
			total_score,
			max_score,
			percentage,
			summary,
			scored_by: criterionScores ? "manual" : "engine",
		};
	}

	/**
	 * Score multiple proposals against the same rubric.
	 *
	 * @param proposals - Array of proposals to score
	 * @param rubric - The rubric to score against
	 * @param manualScores - Optional map of proposal_id -> manual criterion scores
	 * @returns Array of scoring outputs
	 */
	scoreBatch(
		proposals: ScoringInput["proposal"][],
		rubric: ProposalRubric,
		manualScores?: Map<string, CriterionScore[]>,
	): ScoringOutput[] {
		return proposals.map((proposal) => {
			const criterionScores = manualScores?.get(proposal.id);
			return this.score({
				proposal,
				rubric,
				criterionScores,
			});
		});
	}

	/**
	 * Validate that a rubric's criteria are well-formed.
	 *
	 * @param criteria - Array of rubric criteria
	 * @returns Array of validation error messages (empty if valid)
	 */
	validateCriteria(criteria: RubricCriterion[]): string[] {
		const errors: string[] = [];

		for (let i = 0; i < criteria.length; i++) {
			const c = criteria[i];

			if (!c.name || c.name.trim().length === 0) {
				errors.push(`Criterion at index ${i} has no name`);
			}
			if (c.weight <= 0) {
				errors.push(`Criterion "${c.name || i}" has weight <= 0`);
			}
			if (c.max_score <= 0) {
				errors.push(`Criterion "${c.name || i}" has max_score <= 0`);
			}
			if (!c.description || c.description.trim().length === 0) {
				errors.push(`Criterion "${c.name || i}" has no description`);
			}
		}

		// Check that weights sum to approximately 1.0
		if (criteria.length > 0) {
			const totalWeight = criteria.reduce((sum, c) => sum + c.weight, 0);
			if (Math.abs(totalWeight - 1.0) > 0.01) {
				errors.push(`Criteria weights sum to ${totalWeight.toFixed(3)}, expected approximately 1.0`);
			}
		}

		return errors;
	}
}

/**
 * Proposal Ranking Engine.
 *
 * Ranks proposals by their scores across rubrics, providing
 * comparison and prioritization for the execution pipeline.
 */

import type { ProposalScore } from "../types.js";
import type { ScoringOutput } from "./scorer.js";

/**
 * Input for ranking proposals.
 */
export interface RankingInput {
	/** Scoring outputs to rank */
	results: ScoringOutput[];
	/** Optional weights per rubric ID for multi-rubric ranking */
	rubricWeights?: Record<string, number>;
}

/**
 * A scored proposal with ranking metadata.
 */
export interface ScoredProposalRanking {
	/** The proposal ID */
	proposal_id: string;
	/** The rubric ID used */
	rubric_id: string;
	/** Weighted total score */
	total_score: number;
	/** Maximum score */
	max_score: number;
	/** Percentage score */
	percentage: number;
	/** Scoring summary */
	summary: string;
	/** Rank position (1 = highest) */
	rank: number;
	/** Number of proposals ranked */
	total_ranked: number;
}

/**
 * Ranking results.
 */
export interface RankingOutput {
	/** Ranked proposals (highest score first) */
	rankings: ScoredProposalRanking[];
	/** Number of proposals ranked */
	total: number;
}

/**
 * Proposal Ranking Engine.
 *
 * Ranks scoring outputs to determine proposal priority.
 */
export class ProposalRankingEngine {
	/**
	 * Rank scoring outputs by total score (highest first).
	 *
	 * @param input - Ranking input with scoring results
	 * @returns Ranked proposals with position metadata
	 */
	rank(input: RankingInput): RankingOutput {
		const { results, rubricWeights } = input;

		// Apply rubric weights if provided
		let adjusted = results;
		if (rubricWeights && Object.keys(rubricWeights).length > 0) {
			adjusted = results.map((r) => ({
				...r,
				total_score: r.total_score * (rubricWeights[r.rubric_id] ?? 1.0),
			}));
		}

		// Sort by total_score descending
		const sorted = [...adjusted].sort((a, b) => b.total_score - a.total_score);

		// Assign ranks
		const rankings: ScoredProposalRanking[] = sorted.map((result, index) => ({
			proposal_id: result.proposal_id,
			rubric_id: result.rubric_id,
			total_score: result.total_score,
			max_score: result.max_score,
			percentage: result.percentage,
			summary: result.summary,
			rank: index + 1,
			total_ranked: sorted.length,
		}));

		return {
			rankings,
			total: rankings.length,
		};
	}

	/**
	 * Rank proposals by their latest scores from the database.
	 *
	 * For each proposal, uses the most recent score entry per rubric.
	 *
	 * @param scores - Array of proposal scores from the database
	 * @returns Ranked proposals
	 */
	rankFromDbScores(scores: ProposalScore[]): RankingOutput {
		// Group by proposal_id and get latest per proposal
		const latestPerProposal = new Map<string, ProposalScore>();

		for (const score of scores) {
			const existing = latestPerProposal.get(score.proposal_id);
			if (!existing || score.scored_at > existing.scored_at) {
				latestPerProposal.set(score.proposal_id, score);
			}
		}

		const results: ScoringOutput[] = Array.from(latestPerProposal.values()).map((s) => ({
			proposal_id: s.proposal_id,
			rubric_id: s.rubric_id,
			scores: s.scores,
			total_score: s.total_score,
			max_score: s.max_score,
			percentage: s.max_score > 0 ? (s.total_score / s.max_score) * 100 : 0,
			summary: s.summary ?? "",
			scored_by: s.scored_by,
		}));

		return this.rank({ results });
	}
}

