  timestamp: string;
  eventType: string;
  workspaceId: string;
  severity?: string;
  data: Record<string, unknown>;
}

export interface WorkspaceOutcome {
  workspaceId: string;
  status: "success" | "failure" | "retry" | "skipped" | "conflict";
  retryCount: number;
  duration: number;
  errorTypes?: string[];
  validationPassed?: boolean;
  summary?: string;
}

