/**
 * Plan Factory Engine — P17.A
 *
 * Converts approved proposals into executable phase plans.
 * Analyzes proposal scope, generates workstream definitions,
 * creates dependency graphs, computes batch layouts, validates
 * output, and writes phase markdown + JSON contract files.
 */

import { existsSync } from "node:fs";
import { mkdir, readdir, writeFile } from "node:fs/promises";
import { dirname, resolve } from "node:path";
import type { Proposal, ProposalStore } from "../proposals/types.js";
import type { TemplateData } from "./template.js";
import { MasterTemplateIntegration } from "./template.js";
import type {
	PlanExecutionContract,
	PlanFactoryConfig,
	PlanFactoryInput,
	PlanFactoryOutput,
	ProposalAnalysis,
	ValidationResult2,
	WorkstreamDef,
} from "./types.js";

// ---------------------------------------------------------------------------
// Default config
// ---------------------------------------------------------------------------

const DEFAULT_CONFIG: PlanFactoryConfig = {
	outputDir: "docs/pi/phases",
	contractDir: ".pi/plans/generated",
	maxWorkstreams: 8,
	templateVersion: "2.5.1",
	validateBeforeReturn: true,
	enableLLMContent: true,
};

// ---------------------------------------------------------------------------
// PlanFactory
// ---------------------------------------------------------------------------

export class PlanFactory {
	private config: PlanFactoryConfig;
	private templateIntegration: MasterTemplateIntegration;
	private proposalStore?: ProposalStore;

	constructor(
		templateIntegration?: MasterTemplateIntegration,
		config?: Partial<PlanFactoryConfig>,
		proposalStore?: ProposalStore,
	) {
		this.config = { ...DEFAULT_CONFIG, ...config };
		this.templateIntegration = templateIntegration ?? new MasterTemplateIntegration();
		this.proposalStore = proposalStore;
	}

	// -----------------------------------------------------------------------
	// Core
	// -----------------------------------------------------------------------

	/**
	 * Create a plan from proposal input.
	 *
	 * If a proposal is provided directly, it takes precedence. Otherwise,
	 * the factory will try to fetch the proposal from its store using
	 * `input.proposalId`.
	 */
	async createPlan(input: PlanFactoryInput, proposal?: Proposal): Promise<PlanFactoryOutput> {
		// Resolve the proposal
		let resolvedProposal: Proposal | null = proposal ?? null;
		if (!resolvedProposal && this.proposalStore && input.proposalId) {
			resolvedProposal = await this.proposalStore.getById(input.proposalId);
		}
		if (!resolvedProposal) {
			throw new Error(
				`Cannot create plan: no proposal provided and no ProposalStore configured. ` +
					`Either pass a proposal directly or configure a ProposalStore with proposalId "${input.proposalId}".`,
			);
		}

		const phaseId = await this.computePhaseId();
		const phaseTitle = this.computePhaseTitle(resolvedProposal);

		// Analyze the proposal
		const analysis = this.analyzeProposal(resolvedProposal);

		// Generate workstreams
		const workstreams = this.generateWorkstreams(analysis, resolvedProposal, phaseId);

		// Generate dependencies
		const dependencies = this.generateDependencies(workstreams);

		// Generate batches
		const batches = this.generateBatches(workstreams, dependencies);

		// Build contract
		const jsonContract = this.buildJsonContract({
			id: phaseId,
			title: phaseTitle,
			workstreams,
			dependencies,
			batches,
		});

		// Resolve output paths
		const { markdownPath, contractPath } = await this.resolveOutputPaths(phaseId, phaseTitle);

		// Populate template
		const template = await this.templateIntegration.loadTemplate();
		const templateData: TemplateData = {
			phase: { id: phaseId, title: phaseTitle, purpose: resolvedProposal.description },
			workstreams,
			dependencies,
			batches,
			riskRegister: [],
			rollback: { triggerConditions: [], procedure: [] },
			nextPhase: { id: "", title: "" },
			hardRequirements: ["npm only", "no git push"],
			executionPolicies: {},
		};
		const markdown = this.templateIntegration.populateFullTemplate(template, templateData, phaseId, phaseTitle);

		// Write files
		await this.writeMarkdown(markdownPath, markdown);
		await this.writeContract(contractPath, jsonContract);

		// Build output
		const output: PlanFactoryOutput = {
			phaseId,
			phaseTitle,
			markdownPath,
			jsonContract,
			workstreams,
			batches,
			generatedAt: new Date().toISOString(),
			confidence: analysis.evidenceQuality,
			validationResults: [],
		};

		// Validate
		if (this.config.validateBeforeReturn) {
			output.validationResults = await this.validatePlan(output);
		}

		return output;
	}

	// -----------------------------------------------------------------------
	// Proposal Analysis
	// -----------------------------------------------------------------------

	/**
	 * Analyze a proposal to determine scope, complexity, and risk.
	 */
	private analyzeProposal(proposal: Proposal): ProposalAnalysis {
		const evidenceCount = proposal.evidence?.memoryIds?.length ?? 0;
		const description = proposal.description;
		const wordCount = description.split(/\s+/).length;

		// Estimate workstreams based on description length and evidence
		const estimatedWorkstreams = Math.max(
			1,
			Math.min(this.config.maxWorkstreams, Math.ceil(wordCount / 200) + Math.floor(evidenceCount / 3)),
		);

		// Compute evidence quality
		const evidenceQuality = Math.min(1, evidenceCount / 10);

		return {
			scope: description.substring(0, 200),
			estimatedWorkstreams,
			affectedSystems: this.extractAffectedSystems(description),
			risk: proposal.risk.level,
			evidenceQuality,
		};
	}

	/**
	 * Extract affected system names from proposal text.
	 */
	private extractAffectedSystems(text: string): string[] {
		const known = [
			"api",
			"dashboard",
			"memory",
			"goals",
			"proposal",
			"policy",
			"audit",
			"orchestrator",
			"executor",
			"scheduler",
			"worktree",
			"queue",
		];
		return known.filter((s) => text.toLowerCase().includes(s));
	}

	// -----------------------------------------------------------------------
	// Workstream Generation
	// -----------------------------------------------------------------------

	/**
	 * Generate workstream definitions from proposal analysis.
	 */
	private generateWorkstreams(analysis: ProposalAnalysis, _proposal: Proposal, phaseId: string): WorkstreamDef[] {
		const count = Math.min(analysis.estimatedWorkstreams, this.config.maxWorkstreams);
		const workstreams: WorkstreamDef[] = [];

		for (let i = 0; i < count; i++) {
			const id = this.generateWorkstreamId(phaseId, i);
			workstreams.push({
				id,
				title: `Workstream ${id}`,
				goal: `Implement ${analysis.scope.substring(0, 80)} — part ${i + 1}`,
				acceptanceCriteria: [`${id} implementation complete`, `${id} tests pass`],
				dependencies: [],
				fileScope: [],
				isolationNotes: "",
				queuePriority: i === 0 ? "critical" : i < 3 ? "high" : "normal",
				riskLevel: analysis.risk,
			});
		}

		return workstreams;
	}

	/**
	 * Generate a workstream ID like "P21.A", "P21.B".
	 */
	private generateWorkstreamId(phaseId: string, index: number): string {
		const letter = String.fromCharCode(65 + index); // A, B, C, ...
		return `${phaseId}.${letter}`;
	}

	// -----------------------------------------------------------------------
	// Dependency & Batch Generation
	// -----------------------------------------------------------------------

	/**
	 * Generate dependency edges between workstreams.
	 */
	private generateDependencies(
		workstreams: WorkstreamDef[],
	): Array<{ from: string; to: string; type: "blocking" | "informational" }> {
		const deps: Array<{ from: string; to: string; type: "blocking" | "informational" }> = [];

		// Simple heuristic: each workstream depends on the previous one
		// (more sophisticated analysis would use file scope overlap)
		for (let i = 1; i < workstreams.length; i++) {
			deps.push({
				from: workstreams[i - 1].id,
				to: workstreams[i].id,
				type: "blocking",
			});
		}

		return deps;
	}

	/**
	 * Compute batch layout from workstreams and dependencies.
	 */
	private generateBatches(
		workstreams: WorkstreamDef[],
		dependencies: Array<{ from: string; to: string; type: "blocking" | "informational" }>,
	): string[][] {
		// Build dependency map
		const depMap = new Map<string, Set<string>>();
		for (const ws of workstreams) {
			depMap.set(ws.id, new Set());
		}
		for (const dep of dependencies) {
			if (dep.type === "blocking") {
				depMap.get(dep.to)?.add(dep.from);
			}
		}

		// Kahn's algorithm for topological batches
		const remaining = new Set(workstreams.map((ws) => ws.id));
		const inDegree = new Map<string, number>();
		for (const [id, deps] of depMap) {
			inDegree.set(id, deps.size);
		}

		const batches: string[][] = [];
		while (remaining.size > 0) {
			const batch: string[] = [];
			for (const id of remaining) {
				if ((inDegree.get(id) ?? 0) === 0) {
					batch.push(id);
				}
			}

			if (batch.length === 0) break; // cycle detection

			batches.push(batch);
			for (const id of batch) {
				remaining.delete(id);
				for (const [otherId, deps] of depMap) {
					if (deps.has(id)) {
						deps.delete(id);
						inDegree.set(otherId, (inDegree.get(otherId) ?? 1) - 1);
					}
				}
			}
		}

		return batches;
	}

	// -----------------------------------------------------------------------
	// Phase ID / Title
	// -----------------------------------------------------------------------

	/**
	 * Compute the next available phase ID by scanning existing phase files
	 * in `docs/v2/phases/` or the configured output directory.
	 *
	 * Extracts the highest numeric phase number from existing filenames
	 * matching `phase_p{N}_{slug}.md` and returns the next one.
	 */
	private async computePhaseId(): Promise<string> {
		const phaseDirs = [resolve(this.config.outputDir), resolve("docs/v2/phases")];

		let maxPhaseNum = 13; // P13 is the earliest v2 phase

		for (const dir of phaseDirs) {
			if (!existsSync(dir)) continue;

			try {
				const files = await readdir(dir);
				for (const file of files) {
					const match = file.match(/^phase_p(\d+)_/i);
					if (match) {
						const num = Number.parseInt(match[1], 10);
						if (num > maxPhaseNum) maxPhaseNum = num;
					}
				}
			} catch {
				// Directory doesn't exist or can't be read — skip
			}
		}

		return `P${maxPhaseNum + 1}`;
	}

	/**
	 * Derive a phase title from the proposal type and title.
	 */
	private computePhaseTitle(proposal: Proposal): string {
		// Generate a more descriptive title based on proposal type
		const typePrefix: Record<string, string> = {
			plan_proposal: "Plan",
			memory_proposal: "Memory",
			goal_revision_proposal: "Goal Revision",
			autonomy_adjustment_proposal: "Autonomy",
			reflection_proposal: "Reflection",
			safety_proposal: "Safety",
		};

		const prefix = typePrefix[proposal.type] ?? "Phase";
		const title = proposal.title.replace(/^Plan:\s*/i, "").trim();
		return `${prefix}: ${title}`;
	}

	// -----------------------------------------------------------------------
	// JSON Contract
	// -----------------------------------------------------------------------

	/**
	 * Build the execution contract from phase data.
	 */
	private buildJsonContract(phase: {
		id: string;
		title: string;
		workstreams: WorkstreamDef[];
		dependencies: Array<{ from: string; to: string; type: "blocking" | "informational" }>;
		batches: string[][];
	}): PlanExecutionContract {
		return {
			contractVersion: "2.5.1",
			phase: { id: phase.id, title: phase.title },
			workstreams: phase.workstreams,
			dependencies: phase.dependencies,
			batches: phase.batches,
			scaleMode: "experimental_6",
			integrationQueue: true,
			worktreeIsolation: true,
			metadata: {},
		};
	}

	// -----------------------------------------------------------------------
	// I/O
	// -----------------------------------------------------------------------

	/**
	 * Resolve output file paths for markdown and contract.
	 */
	async resolveOutputPaths(
		phaseId: string,
		phaseTitle: string,
	): Promise<{ markdownPath: string; contractPath: string }> {
		const slug = phaseTitle
			.toLowerCase()
			.replace(/[^a-z0-9]+/g, "_")
			.replace(/^_|_$/g, "")
			.substring(0, 60);
		return {
			markdownPath: resolve(this.config.outputDir, `phase_${phaseId.toLowerCase()}_${slug}.md`),
			contractPath: resolve(this.config.contractDir, `${phaseId.toLowerCase()}-contract.json`),
		};
	}

	/**
	 * Write generated markdown to file.
	 */
	async writeMarkdown(path: string, content: string): Promise<void> {
		await mkdir(dirname(path), { recursive: true });
		await writeFile(path, content, "utf-8");
	}

	/**
	 * Write JSON contract to file.
	 */
	async writeContract(path: string, contract: PlanExecutionContract): Promise<void> {
		await mkdir(dirname(path), { recursive: true });
		await writeFile(path, JSON.stringify(contract, null, 2), "utf-8");
	}

	// -----------------------------------------------------------------------
	// Validation
	// -----------------------------------------------------------------------

	/**
	 * Validate a generated plan output.
	 */
	async validatePlan(output: PlanFactoryOutput): Promise<ValidationResult2[]> {
		const results: ValidationResult2[] = [];

		// Validate markdown
		results.push(...this.validateMarkdown(output.markdownPath));

		// Validate contract
		results.push(...this.validateContract(output.jsonContract));

		// Validate dependencies
		results.push(...this.validateDependencies(output.workstreams, output.jsonContract.dependencies));

		return results;
	}

	/**
	 * Validate the generated markdown file.
	 */
	private validateMarkdown(path: string): ValidationResult2[] {
		const results: ValidationResult2[] = [];
		results.push({ type: "info", component: "markdown", message: `Markdown file: ${path}` });
		return results;
	}

	/**
	 * Validate the execution contract.
	 */
	private validateContract(contract: PlanExecutionContract): ValidationResult2[] {
		return this.templateIntegration.validateContract(contract);
	}

	/**
	 * Validate dependencies are consistent.
	 */
	private validateDependencies(
		workstreams: WorkstreamDef[],
		dependencies: Array<{ from: string; to: string; type: "blocking" | "informational" }>,
	): ValidationResult2[] {
		const results: ValidationResult2[] = [];
		const wsIds = new Set(workstreams.map((w) => w.id));

		for (const dep of dependencies) {
			if (!wsIds.has(dep.from)) {
				results.push({
					type: "error",
					component: "dependency",
					message: `Dependency 'from' ${dep.from} not found in workstreams`,
				});
			}
			if (!wsIds.has(dep.to)) {
				results.push({
					type: "error",
					component: "dependency",
					message: `Dependency 'to' ${dep.to} not found in workstreams`,
				});
			}
		}

		return results;
	}

	// -----------------------------------------------------------------------
	// Configuration
	// -----------------------------------------------------------------------

	setConfig(config: Partial<PlanFactoryConfig>): void {
		this.config = { ...this.config, ...config };
	}

	getConfig(): PlanFactoryConfig {
		return { ...this.config };
	}
}

/**
 * Plan Factory Types — P17.A
 *
 * Defines the core data structures for converting approved proposals
 * into executable phase plans (markdown + JSON contract).
 *
 * Every plan factory output includes workstream definitions, a dependency
 * graph, batch layout, and validation results.
 */

import type { RiskLevel } from "../proposals/types.js";

// ---------------------------------------------------------------------------
// Configuration
// ---------------------------------------------------------------------------

export interface PlanFactoryConfig {
	/** Output directory for generated phase markdown files. */
	outputDir: string;
	/** Output directory for JSON execution contracts. */
	contractDir: string;
	/** Maximum number of workstreams per phase (default: 8). */
	maxWorkstreams: number;
	/** Master template version to use (default: "2.5.1"). */
	templateVersion: string;
	/** Whether to validate output before returning (default: true). */
	validateBeforeReturn: boolean;
	/** Whether to enable LLM content generation in plan sections (default: true). */
	enableLLMContent: boolean;
}

// ---------------------------------------------------------------------------
// Input & Output
// ---------------------------------------------------------------------------

export interface PlanFactoryInput {
	/** ID of the proposal to convert. */
	proposalId: string;
	/** Optional goal ID for alignment. */
	goalId?: string;
	/** Priority override. */
	priority?: "critical" | "high" | "normal" | "low";
	/** Master template version override. */
	masterTemplateVersion?: string;
	/** Optional user notes/overrides for plan generation. */
	userNotes?: string;
}

export interface PlanFactoryOutput {
	/** Generated phase ID (e.g., "P21"). */
	phaseId: string;
	/** Generated phase title (e.g., "Retry Budget"). */
	phaseTitle: string;
	/** Full path to the generated markdown file. */
	markdownPath: string;
	/** JSON execution contract. */
	jsonContract: PlanExecutionContract;
	/** Workstream definitions. */
	workstreams: WorkstreamDef[];
	/** Batch layout: arrays of workstream IDs per batch. */
	batches: string[][];
	/** ISO 8601 generation timestamp. */
	generatedAt: string;
	/** Confidence score 0-1 based on evidence completeness. */
	confidence: number;
	/** Validation results. */
	validationResults: ValidationResult2[];
}

export interface PlanExecutionContract {
	/** Schema version (e.g., "2.5.1"). */
	contractVersion: string;
	/** Phase identification. */
	phase: { id: string; title: string };
	/** Workstream definitions. */
	workstreams: WorkstreamDef[];
	/** Dependency edges. */
	dependencies: Array<{ from: string; to: string; type: "blocking" | "informational" }>;
	/** Batch layout. */
	batches: string[][];
	/** Selected scale mode. */
	scaleMode: string;
	/** Whether integration queue is required. */
	integrationQueue: boolean;
	/** Whether worktree isolation is required. */
	worktreeIsolation: boolean;
	/** Arbitrary metadata. */
	metadata: Record<string, unknown>;
}

export interface WorkstreamDef {
	/** Unique workstream ID (e.g., "P21.A"). */
	id: string;
	/** Human-readable title. */
	title: string;
	/** One-line goal statement. */
	goal: string;
	/** Acceptance criteria checklist. */
	acceptanceCriteria: string[];
	/** IDs of workstreams this depends on. */
	dependencies: string[];
	/** File glob patterns this workstream touches. */
	fileScope: string[];
	/** Isolation notes for the executor. */
	isolationNotes: string;
	/** Queue priority. */
	queuePriority: "critical" | "high" | "normal" | "low";
	/** Risk level. */
	riskLevel: RiskLevel;
}

export interface ValidationResult2 {
	type: "error" | "warning" | "info";
	component: "markdown" | "contract" | "workstream" | "dependency";
	message: string;
	details?: Record<string, unknown>;
}

// ---------------------------------------------------------------------------
// Proposal Analysis
// ---------------------------------------------------------------------------

export interface ProposalAnalysis {
	/** Descriptive scope string. */
	scope: string;
	/** Estimated number of workstreams needed. */
	estimatedWorkstreams: number;
	/** Systems that will be affected. */
	affectedSystems: string[];
	/** Overall risk level. */
	risk: RiskLevel;
	/** How strong the evidence backing is (0-1). */
	evidenceQuality: number;
}

/**
 * Master Template Integration — P17.B
 *
 * Loads, parses, populates, and validates the LLM Implementation Agent
 * master template v2.5.1 for plan generation.
 *
 * Works by reading the template file, identifying required segments with
 * {{ placeholders }}, and populating them with phase-specific data.
 */

import { readFile } from "node:fs/promises";
import type { PlanExecutionContract, ValidationResult2, WorkstreamDef } from "../plan-factory/types.js";

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export interface RequiredSegment {
	id: string;
	name: string;
	required: boolean;
	order: number;
	template: string;
	placeholders: string[];
}

export interface ParsedTemplate {
	version: string;
	segments: RequiredSegment[];
	contractSchema: Record<string, unknown>;
	raw: string;
}

export interface TemplateData {
	phase: { id: string; title: string; purpose: string };
	workstreams: WorkstreamDef[];
	dependencies: Array<{ from: string; to: string; type: "blocking" | "informational" }>;
	batches: string[][];
	riskRegister: Array<{ risk: string; likelihood: string; impact: string; mitigation: string }>;
	rollback: { triggerConditions: string[]; procedure: string[] };
	nextPhase: { id: string; title: string };
	hardRequirements: string[];
	executionPolicies: Record<string, unknown>;
}

// ---------------------------------------------------------------------------
// Default template path resolution
// ---------------------------------------------------------------------------

function findDefaultTemplatePath(): string {
	// Search common locations
	const candidates = [
		"docs/llm-implementation-agent-master-template.md",
		"docs/templates/llm-implementation-agent-master-template.md",
		".pi/templates/master-template.md",
	];
	// Return the first that looks plausible; caller handles missing file
	return candidates[0];
}

// ---------------------------------------------------------------------------
// Required segments for v2.5.1
// ---------------------------------------------------------------------------

const REQUIRED_SEGMENTS_V2_5_1: Omit<RequiredSegment, "template">[] = [
	{
		id: "tldr",
		name: "TL;DR / Compact Mental Model",
		required: true,
		order: 0,
		placeholders: ["phase", "title", "goal"],
	},
	{ id: "header", name: "Header", required: true, order: 1, placeholders: ["phase", "title", "status", "mode"] },
	{ id: "raci", name: "RACI", required: true, order: 2, placeholders: [] },
	{ id: "purpose", name: "Purpose", required: true, order: 3, placeholders: ["phase", "description"] },
	{ id: "carried-over", name: "What Carried Over", required: true, order: 4, placeholders: [] },
	{ id: "background", name: "Background / What Was Wrong", required: true, order: 5, placeholders: [] },
	{ id: "failures", name: "Current Failure State / Known Blockers", required: true, order: 6, placeholders: [] },
	{ id: "risk", name: "Risk Register", required: true, order: 7, placeholders: [] },
	{ id: "workstreams", name: "Workstreams", required: true, order: 8, placeholders: ["workstreams"] },
	{ id: "order", name: "Combined Implementation Order", required: true, order: 9, placeholders: ["batches"] },
	{ id: "done", name: "Definition of Done", required: true, order: 10, placeholders: ["criteria"] },
	{ id: "rollback", name: "Rollback Playbook", required: true, order: 11, placeholders: ["conditions", "procedure"] },
	{ id: "next", name: "What Next Phase Inherits", required: true, order: 12, placeholders: ["nextPhase"] },
];

// ---------------------------------------------------------------------------
// MasterTemplateIntegration
// ---------------------------------------------------------------------------

export class MasterTemplateIntegration {
	private templatePath: string;
	private parsedCache: Map<string, ParsedTemplate> = new Map();

	constructor(templatePath?: string) {
		this.templatePath = templatePath ?? findDefaultTemplatePath();
	}

	/**
	 * Load and parse a template by version.
	 */
	async loadTemplate(version = "2.5.1"): Promise<ParsedTemplate> {
		const cached = this.parsedCache.get(version);
		if (cached) return cached;

		let raw: string;
		try {
			raw = await readFile(this.templatePath, "utf-8");
		} catch {
			// Template file not found — return a minimal template with just the required segments
			raw = this.generateFallbackTemplate(version);
		}

		const parsed = this.parseTemplate(raw);
		this.parsedCache.set(version, parsed);
		return parsed;
	}

	/**
	 * Parse raw template content into structured segments.
	 */
	private parseTemplate(raw: string): ParsedTemplate {
		const version = raw.match(/Template:.*?v?(\d+\.\d+\.\d+)/)?.[1] ?? "2.5.1";
		const segments: RequiredSegment[] = [];

		for (const seg of REQUIRED_SEGMENTS_V2_5_1) {
			// Try to extract the section content from the raw template
			const sectionRegex = new RegExp(
				`##\\s+${escapeRegex(seg.order.toString())}[. ]*${escapeRegex(seg.name)}([\\s\\S]*?)(?=\\n##\\s+\\d+[. ]|$)`,
				"i",
			);
			const match = raw.match(sectionRegex);
			const template = match?.[1]?.trim() ?? `{{${seg.id}:${seg.name}}}`;

			// Find all {{ ... }} placeholders in this section
			const placeholders = [...template.matchAll(/\{\{(\w+)\}\}/g)].map((m) => m[1]);

			segments.push({
				...seg,
				template,
				placeholders: placeholders.length > 0 ? placeholders : seg.placeholders,
			});
		}

		return {
			version,
			segments,
			contractSchema: {},
			raw,
		};
	}

	/**
	 * Populate a single segment with provided data.
	 */
	populateSegment(segment: RequiredSegment, data: TemplateData, phaseId: string, phaseTitle: string): string {
		let content = segment.template;

		const replacements: Record<string, string> = {
			phase: phaseId,
			title: phaseTitle,
			phaseId,
			phaseTitle,
			goal: data.phase.purpose,
			description: data.phase.purpose,
			status: "Authoritative Implementation",
			mode: "experimental_6",
			workstreams: data.workstreams
				.map(
					(ws) =>
						`### ${ws.id} — ${ws.title}\n\n**Goal:** ${ws.goal}\n\n${ws.acceptanceCriteria.map((ac) => `* [ ] ${ac}`).join("\n")}`,
				)
				.join("\n\n"),
			batches: data.batches.map((batch, i) => `**Batch ${i + 1}:** ${batch.join(", ")}`).join("\n"),
			criteria: data.workstreams
				.flatMap((ws) => ws.acceptanceCriteria)
				.map((c) => `* [ ] ${c}`)
				.join("\n"),
			conditions: data.rollback.triggerConditions.join(", "),
			procedure: data.rollback.procedure.map((p) => `* ${p}`).join("\n"),
			nextPhase: `${data.nextPhase.id} — ${data.nextPhase.title}`,
		};

		for (const [key, value] of Object.entries(replacements)) {
			content = content.replace(new RegExp(`\\{\\{${key}\\}\\}`, "g"), value);
		}

		// Remove any remaining unfilled placeholders
		content = content.replace(/\{\{\w+\}\}/g, "");

		return content;
	}

	/**
	 * Populate the full template with data for a phase.
	 */
	populateFullTemplate(parsed: ParsedTemplate, data: TemplateData, phaseId: string, phaseTitle: string): string {
		const parts: string[] = [];

		for (const segment of parsed.segments) {
			if (segment.required) {
				parts.push(`## ${segment.order}. ${segment.name}`);
				parts.push("");
				parts.push(this.populateSegment(segment, data, phaseId, phaseTitle));
				parts.push("");
			}
		}

		return parts.join("\n");
	}

	/**
	 * Generate a JSON execution contract from populated template data.
	 */
	generateContract(
		_populated: string,
		phase: { id: string; title: string; workstreams: WorkstreamDef[]; dependencies: unknown[]; batches: string[][] },
	): PlanExecutionContract {
		return {
			contractVersion: "2.5.1",
			phase: { id: phase.id, title: phase.title },
			workstreams: phase.workstreams,
			dependencies: phase.dependencies as Array<{ from: string; to: string; type: "blocking" | "informational" }>,
			batches: phase.batches,
			scaleMode: "experimental_6",
			integrationQueue: true,
			worktreeIsolation: true,
			metadata: {},
		};
	}

	/**
	 * Validate populated output has all required segments.
	 */
	validatePopulated(content: string): ValidationResult2[] {
		const results: ValidationResult2[] = [];

		for (const seg of REQUIRED_SEGMENTS_V2_5_1) {
			const sectionRegex = new RegExp(`##\\s+${seg.order}[. ]+${escapeRegex(seg.name)}`, "i");
			if (!sectionRegex.test(content)) {
				results.push({
					type: "error",
					component: "markdown",
					message: `Missing required segment: ${seg.name}`,
				});
			} else {
				results.push({
					type: "info",
					component: "markdown",
					message: `Segment present: ${seg.name}`,
				});
			}
		}

		return results;
	}

	/**
	 * Validate a generated contract.
	 */
	validateContract(contract: PlanExecutionContract): ValidationResult2[] {
		const results: ValidationResult2[] = [];

		if (!contract.contractVersion) {
			results.push({ type: "error", component: "contract", message: "Missing contractVersion" });
		}
		if (!contract.phase?.id) {
			results.push({ type: "error", component: "contract", message: "Missing phase.id" });
		}
		if (!contract.workstreams?.length) {
			results.push({ type: "error", component: "contract", message: "No workstreams defined" });
		}
		if (!contract.batches?.length) {
			results.push({ type: "error", component: "contract", message: "No batches defined" });
		}

		// Validate no duplicate workstream IDs
		const ids = new Set<string>();
		for (const ws of contract.workstreams) {
			if (ids.has(ws.id)) {
				results.push({ type: "error", component: "workstream", message: `Duplicate workstream ID: ${ws.id}` });
			}
			ids.add(ws.id);
		}

		return results;
	}

	/**
	 * Check all required segments are present.
	 */
	checkAllRequiredSegmentsPresent(populated: string, _version = "2.5.1"): boolean {
		for (const seg of REQUIRED_SEGMENTS_V2_5_1) {
			const sectionRegex = new RegExp(`##\\s+${seg.order}[. ]+${escapeRegex(seg.name)}`, "i");
			if (!sectionRegex.test(populated)) return false;
		}
		return true;
	}

	getSupportedVersions(): string[] {
		return ["2.5.1"];
	}

	isVersionSupported(version: string): boolean {
		return version === "2.5.1";
	}

	clearCache(): void {
		this.parsedCache.clear();
	}

	/**
	 * Generate a fallback template when the template file doesn't exist.
	 */
	private generateFallbackTemplate(version: string): string {
		const lines: string[] = [];
		lines.push(`# Template v${version} — Fallback`);
		lines.push("");
		for (const seg of REQUIRED_SEGMENTS_V2_5_1) {
			lines.push(`## ${seg.order}. ${seg.name}`);
			lines.push("");
			lines.push(`{{${seg.id}}}`);
			lines.push("");
		}
		return lines.join("\n");
	}
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function escapeRegex(str: string): string {
	return str.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

