/**
 * Reflection Types — P17.C/D/E/F shared types
 *
 * Defines the core data structures for reflection reports,
 * memory proposals, and future phase suggestions after a
 * plan execution completes.
 */

import type { MemoryType } from "../memory/types.js";
import type { ProposalType, RiskLevel } from "../proposals/types.js";

// ---------------------------------------------------------------------------
// Execution Journal & Workspace Outcome
// ---------------------------------------------------------------------------

export interface ExecutionJournalEntry {
  timestamp: string;
  eventType: string;
  workspaceId: string;
  severity?: string;
  data: Record<string, unknown>;
}

export interface WorkspaceOutcome {
  workspaceId: string;
  status: "success" | "failure" | "retry" | "skipped" | "conflict";
  retryCount: number;
  duration: number;
  errorTypes?: string[];
  validationPassed?: boolean;
  summary?: string;
}

// ---------------------------------------------------------------------------
// Reflection Input
// ---------------------------------------------------------------------------

export interface ReflectionInput {
  planExecId: string;
  planId: string;
  planTitle?: string;
  executionJournal: ExecutionJournalEntry[];
  workspaceOutcomes: WorkspaceOutcome[];
  validationResults: ValidationResult[];
  integrationState: {
    wasDirty: boolean;
    conflicts: number;
    resolvedConflicts: number;
  };
  duration: number;
  startTime: string;
  endTime: string;
  autonomyLevel: number;
  policyStops: number;
  approvalRequests: number;
}

export interface ValidationResult {
  type: "error" | "warning" | "info";
  component: string;
  message: string;
  passed?: boolean;
  details?: Record<string, unknown>;
}

// ---------------------------------------------------------------------------
// Reflection Report
// ---------------------------------------------------------------------------

export interface ReflectionReport {
  id: string;
  planExecId: string;
  planTitle?: string;

  // Summary
  summary: string;
  whatPeopleNeedToKnow: string;

  // What happened
  whatRan: string[];
  whatWorked: string[];
  whatFailed: string[];
  whatSlowedDown: string[];

  // Metrics
  workspaceCount: number;
  successCount: number;
  failureCount: number;
  retryCount: number;
  successRate: number;
  avgRetryCount: number;
  totalDuration: number;
  validationFailures: number;

  // Memory & proposals
  memoriesToCreate: MemoryProposalSuggestion[];
  proposalsToGenerate: ProposalSuggestion[];
  futurePhaseSuggestions: FuturePhaseSuggestion[];

  // Trust
  policyStops: number;
  approvalRequests: number;
  safetyInterventions: number;

  // Metadata
  createdAt: string;
  confidence: number;
  sources: SourceRef[];
}

export interface SourceRef {
  type: "workspace" | "journal" | "validation" | "memory";
  id: string;
  description: string;
}

// ---------------------------------------------------------------------------
// Memory & Proposal Suggestions
// ---------------------------------------------------------------------------

export interface MemoryProposalSuggestion {
  type: MemoryType;
  title: string;
  content: string;
  confidence: number;
  sourceRefs: SourceRef[];
  category: "failure" | "success" | "architecture" | "process";
}

export interface ProposalSuggestion {
  type: ProposalType;
  title: string;
  description: string;
  rationale: string;
  priority: "critical" | "high" | "normal" | "low";
  evidenceIds: string[];
}

export interface FuturePhaseSuggestion {
  title: string;
  rationale: string;
  priority: "critical" | "high" | "normal" | "low";
  estimatedWorkstreams: number;
  relatedMemoryIds: string[];
  relatedObservationIds: string[];
}

// ---------------------------------------------------------------------------
// Reflection Engine Config
// ---------------------------------------------------------------------------

export interface ReflectionConfig {
  outputBaseDir: string;
  minWorkspaceCount: number;
  enableMemoryGeneration: boolean;
  enableFutureSuggestions: boolean;
  maxFutureSuggestions: number;
  sourceBackedRequired: boolean;
}

/**
 * Brain Reflection API — P17.G
 *
 * High-level API service for reflection operations.
 *
 * Wraps ReflectionEngine into a unified service interface used by
 * the web-server routes. Handles listing, reading, stats, and
 * extraction of memory proposals and future suggestions from
 * stored reflection reports.
 *
 * This service is stateless: it delegates all storage and generation
 * to the injected ReflectionEngine instance.
 *
 * @packageDocumentation
 */

import { ReflectionEngine } from "./engine.js";
import type {
	FuturePhaseSuggestion,
	MemoryProposalSuggestion,
	ReflectionInput,
	ReflectionReport,
} from "./types.js";

// ---------------------------------------------------------------------------
// Reflection API Query Types
// ---------------------------------------------------------------------------

/**
 * Query parameters for listing reflections.
 */
export interface ReflectionListQuery {
	/** Filter by plan execution ID (exact match) */
	planExecId?: string;
	/** Filter by plan title (substring match, case-insensitive) */
	planTitle?: string;
	/** Maximum number of results to return (1-1000, default 100) */
	limit?: number;
	/** Number of results to skip (default 0) */
	offset?: number;
	/** Only include reflections created at or after this ISO 8601 timestamp */
	since?: string;
	/** Only include reflections created at or before this ISO 8601 timestamp */
	until?: string;
}

/**
 * Aggregate statistics for stored reflections.
 */
export interface ReflectionStats {
	/** Total number of reflections stored */
	total: number;
	/** Number of reflections per plan execution ID */
	byPlan: Record<string, number>;
	/** Average confidence across all reflections */
	avgConfidence: number;
}

/**
 * Result of a reflection generate operation.
 */
export interface ReflectionGenerateResult {
	success: boolean;
	report?: ReflectionReport;
	error?: string;
	regenerated?: boolean;
}

// ---------------------------------------------------------------------------
// Brain Reflection API
// ---------------------------------------------------------------------------

/**
 * High-level service for reflection API operations.
 *
 * Provides methods for listing, reading, generating, and extracting
 * data from reflection reports. All methods return serializable
 * results suitable for REST API responses.
 *
 * Usage:
 * ```typescript
 * const engine = new ReflectionEngine();
 * const api = new BrainReflectionApi(engine);
 *
 * // List all reflections
 * const { reflections, total } = await api.listReflections({ limit: 10 });
 *
 * // Get a specific reflection
 * const report = await api.getReflection("plan-exec-123");
 *
 * // Generate a new reflection
 * const result = await api.generateReflection(input, { force: true });
 * ```
 */
export class BrainReflectionApi {
	private engine: ReflectionEngine;

	/**
	 * @param engine - An optional ReflectionEngine instance (default: created fresh)
	 */
	constructor(engine?: ReflectionEngine) {
		this.engine = engine ?? new ReflectionEngine();
	}

	// -----------------------------------------------------------------------
	// Configuration
	// -----------------------------------------------------------------------

	/**
	 * Get the underlying ReflectionEngine instance.
	 */
	getEngine(): ReflectionEngine {
		return this.engine;
	}

	// -----------------------------------------------------------------------
	// List / Read
	// -----------------------------------------------------------------------

	/**
	 * List reflections with optional filtering and pagination.
	 *
	 * Filters:
	 * - `planExecId`: exact match on plan execution ID
	 * - `planTitle`: case-insensitive substring match on plan title
	 * - `since`: ISO 8601 timestamp, only reflections created at or after this time
	 * - `until`: ISO 8601 timestamp, only reflections created at or before this time
	 *
	 * Pagination:
	 * - `limit`: max results (1-1000, default 100)
	 * - `offset`: skip N results (default 0)
	 *
	 * @param query - Query parameters (all optional)
	 * @returns Filtered and paginated list with total count
	 */
	async listReflections(query?: ReflectionListQuery): Promise<{
		reflections: ReflectionReport[];
		total: number;
	}> {
		const q = query ?? {};
		let all = this.engine.listReflections();

		// Filter by planExecId (exact match)
		if (q.planExecId) {
			all = all.filter((r) => r.planExecId === q.planExecId);
		}

		// Filter by planTitle (case-insensitive substring)
		if (q.planTitle) {
			const lower = q.planTitle.toLowerCase();
			all = all.filter((r) => (r.planTitle ?? "").toLowerCase().includes(lower));
		}

		// Filter by createdAt timestamp (since)
		if (q.since) {
			const sinceMs = new Date(q.since).getTime();
			all = all.filter((r) => new Date(r.createdAt).getTime() >= sinceMs);
		}

		// Filter by createdAt timestamp (until)
		if (q.until) {
			const untilMs = new Date(q.until).getTime();
			all = all.filter((r) => new Date(r.createdAt).getTime() <= untilMs);
		}

		const total = all.length;

		// Apply pagination
		const limit = q.limit ? Math.max(1, Math.min(q.limit, 1000)) : 100;
		const offset = q.offset ? Math.max(0, q.offset) : 0;

		const paginated = all.slice(offset, offset + limit);

		return {
			reflections: paginated,
			total,
		};
	}

	/**
	 * Get a single reflection report by plan execution ID.
	 *
	 * @param planExecId - The plan execution ID
	 * @returns The reflection report, or null if not found
	 */
	async getReflection(planExecId: string): Promise<ReflectionReport | null> {
		return this.engine.getReflection(planExecId) ?? null;
	}

	/**
	 * Generate a reflection report from execution data.
	 *
	 * Takes a complete ReflectionInput and delegates to the engine's
	 * generateReflection method. If a reflection already exists for
	 * the given planExecId and force is false (default), it returns
	 * the existing report instead of regenerating.
	 *
	 * @param input - The complete reflection input data
	 * @param options - Generation options
	 * @param options.force - If true, overwrite any existing reflection (default: false)
	 * @returns Result with the generated report or error
	 */
	async generateReflection(
		input: ReflectionInput,
		options?: { force?: boolean },
	): Promise<ReflectionGenerateResult> {
		const force = options?.force ?? false;

		try {
			// Check if a reflection already exists
			const existing = this.engine.getReflection(input.planExecId);
			if (existing && !force) {
				return {
					success: true,
					report: existing,
					regenerated: false,
				};
			}

			// Generate the reflection
			const report = await this.engine.generateReflection(input);
			return {
				success: true,
				report,
				regenerated: !!existing,
			};
		} catch (error) {
			return {
				success: false,
				error: error instanceof Error ? error.message : "Failed to generate reflection",
			};
		}
	}

	// -----------------------------------------------------------------------
	// Stats
	// -----------------------------------------------------------------------

	/**
	 * Compute aggregate statistics from all stored reflections.
	 *
	 * Returns:
	 * - total: number of reflections
	 * - byPlan: count of reflections per plan execution ID
	 * - avgConfidence: average confidence score across all reflections
	 *
	 * @returns Aggregate statistics
	 */
	async getStats(): Promise<ReflectionStats> {
		const all = this.engine.listReflections();
		const total = all.length;

		// Count per plan
		const byPlan: Record<string, number> = {};
		for (const r of all) {
			byPlan[r.planExecId] = (byPlan[r.planExecId] ?? 0) + 1;
		}

		// Average confidence
		const avgConfidence =
			total > 0
				? all.reduce((sum, r) => sum + r.confidence, 0) / total
				: 0;

		return { total, byPlan, avgConfidence };
	}

	// -----------------------------------------------------------------------
	// Memories & Future (extracted from a stored report)
	// -----------------------------------------------------------------------

	/**
	 * Get memory proposals from a stored reflection report.
	 *
	 * Extracts the `memoriesToCreate` array from the reflection
	 * with the given planExecId.
	 *
	 * @param planExecId - The plan execution ID
	 * @returns Memory proposals, or null if the reflection is not found
	 */
	async getMemories(
		planExecId: string,
	): Promise<{ memories: MemoryProposalSuggestion[] } | null> {
		const report = this.engine.getReflection(planExecId);
		if (!report) return null;
		return { memories: report.memoriesToCreate };
	}

	/**
	 * Get future phase suggestions from a stored reflection report.
	 *
	 * Extracts the `futurePhaseSuggestions` array from the reflection
	 * with the given planExecId.
	 *
	 * @param planExecId - The plan execution ID
	 * @returns Future suggestions, or null if the reflection is not found
	 */
	async getFuture(
		planExecId: string,
	): Promise<{ suggestions: FuturePhaseSuggestion[] } | null> {
		const report = this.engine.getReflection(planExecId);
		if (!report) return null;
		return { suggestions: report.futurePhaseSuggestions };
	}
}

/**
 * Brain Reflection API Routes — P17.G
 *
 * REST API for listing, reading, and extracting data from reflection reports.
 *
 * Endpoints:
 *   GET    /api/brain/reflections              List reflections (query: planExecId, planTitle, limit, offset, since, until)
 *   GET    /api/brain/reflections/stats        Reflection aggregate statistics
 *   GET    /api/brain/reflections/:planExecId  Get single reflection detail
 *   POST   /api/brain/reflections/:planExecId/generate  Generate/regenerate a reflection
 *   GET    /api/brain/reflections/:planExecId/memories  Get memory proposals from a reflection
 *   GET    /api/brain/reflections/:planExecId/future    Get future suggestions from a reflection
 *
 * All list endpoints return { success: true, ... } format.
 * Errors return { success: false, error: "..." }.
 *
 * @packageDocumentation
 */

import type { FastifyInstance } from "fastify";

// ---------------------------------------------------------------------------
// API Interface (duck-typed to avoid direct dependency on coding-agent)
// ---------------------------------------------------------------------------

/**
 * Minimal interface for the Brain Reflection API.
 *
 * The routes only depend on this interface, not on the concrete
 * BrainReflectionApi class from the coding-agent package.
 * This keeps the web-server free of a direct dependency on
 * the coding-agent package.
 */
export interface BrainReflectionApiLike {
	listReflections(query?: {
		planExecId?: string;
		planTitle?: string;
		limit?: number;
		offset?: number;
		since?: string;
		until?: string;
	}): Promise<{
		reflections: unknown[];
		total: number;
	}>;

	getReflection(planExecId: string): Promise<unknown | null>;

	generateReflection(
		input: any,
		options?: { force?: boolean },
	): Promise<{
		success: boolean;
		report?: unknown;
		error?: string;
		regenerated?: boolean;
	}>;

	getStats(): Promise<{
		total: number;
		byPlan: Record<string, number>;
		avgConfidence: number;
	}>;

	getMemories(planExecId: string): Promise<{ memories: unknown[] } | null>;

	getFuture(planExecId: string): Promise<{ suggestions: unknown[] } | null>;
}

// ---------------------------------------------------------------------------
// Route Registration
// ---------------------------------------------------------------------------

/**
 * Register brain reflection API routes on the Fastify instance.
 *
 * NOTE: The `/stats` route MUST be registered BEFORE the `/:planExecId` route
 * to avoid Fastify interpreting "stats" as a planExecId parameter.
 *
 * @param fastify - The Fastify server instance
 * @param api - A BrainReflectionApiLike-compatible object
 */
export async function registerBrainReflectionRoutes(
	fastify: FastifyInstance,
	api: BrainReflectionApiLike,
): Promise<void> {
	// -----------------------------------------------------------------------
	// GET /api/brain/reflections — List reflections
	// -----------------------------------------------------------------------

	fastify.get<{
		Querystring: {
			planExecId?: string;
			planTitle?: string;
			limit?: number;
			offset?: number;
			since?: string;
			until?: string;
		};
	}>("/api/brain/reflections", async (request, reply) => {
		try {
			const { query } = request;
			const result = await api.listReflections({
				planExecId: query.planExecId,
				planTitle: query.planTitle,
				limit: query.limit ? Math.min(Math.max(query.limit, 1), 1000) : undefined,
				offset: query.offset ? Math.max(query.offset, 0) : undefined,
				since: query.since,
				until: query.until,
			});

			return reply.send({
				success: true,
				reflections: result.reflections,
				total: result.total,
			});
		} catch (error) {
			fastify.log.error({ error }, "Failed to list reflections");
			return reply.code(500).send({
				success: false,
				error: error instanceof Error ? error.message : "Failed to list reflections",
			});
		}
	});

	// -----------------------------------------------------------------------
	// GET /api/brain/reflections/stats — Reflection aggregate statistics
	//
	// NOTE: This MUST be registered BEFORE the /:planExecId route to avoid
	// Fastify interpreting "stats" as a planExecId parameter.
	// -----------------------------------------------------------------------

	fastify.get("/api/brain/reflections/stats", async (_request, reply) => {
		try {
			const stats = await api.getStats();
			return reply.send({
				success: true,
				stats,
			});
		} catch (error) {
			fastify.log.error({ error }, "Failed to get reflection stats");
			return reply.code(500).send({
				success: false,
				error: error instanceof Error ? error.message : "Failed to get reflection stats",
			});
		}
	});

	// -----------------------------------------------------------------------
	// GET /api/brain/reflections/:planExecId — Get single reflection detail
	// -----------------------------------------------------------------------

	fastify.get<{
		Params: { planExecId: string };
	}>("/api/brain/reflections/:planExecId", async (request, reply) => {
		try {
			const { planExecId } = request.params;
			const report = await api.getReflection(planExecId);

			if (!report) {
				return reply.code(404).send({
					success: false,
					error: `Reflection not found for plan execution "${planExecId}"`,
				});
			}

			return reply.send({
				success: true,
				reflection: report,
			});
		} catch (error) {
			fastify.log.error({ error }, "Failed to get reflection");
			return reply.code(500).send({
				success: false,
				error: error instanceof Error ? error.message : "Failed to get reflection",
			});
		}
	});

	// -----------------------------------------------------------------------
	// POST /api/brain/reflections/:planExecId/generate — Generate/regenerate
	// -----------------------------------------------------------------------

	fastify.post<{
		Params: { planExecId: string };
		Body: {
			force?: boolean;
			input?: Record<string, unknown>;
		};
	}>("/api/brain/reflections/:planExecId/generate", async (request, reply) => {
		try {
			const { planExecId } = request.params;
			const { force, input: rawInput } = request.body ?? {};

			// Build the reflection input. The caller must provide execution data,
			// either as a complete ReflectionInput object or it will be looked up
			// from stored plan execution state.
			if (!rawInput || Object.keys(rawInput).length === 0) {
				return reply.code(400).send({
					success: false,
					error:
						"Reflection input is required. Provide execution data in the 'input' field " +
						"with planExecId, executionJournal, workspaceOutcomes, and validationResults.",
				});
			}

			const reflectionInput = {
				...rawInput,
				planExecId: rawInput.planExecId ?? planExecId,
			};

			const result = await api.generateReflection(reflectionInput, { force });

			if (!result.success) {
				return reply.code(500).send({
					success: false,
					error: result.error ?? "Failed to generate reflection",
				});
			}

			const statusCode = result.regenerated ? 200 : 201;
			return reply.code(statusCode).send({
				success: true,
				reflection: result.report,
				regenerated: result.regenerated,
			});
		} catch (error) {
			fastify.log.error({ error }, "Failed to generate reflection");
			return reply.code(500).send({
				success: false,
				error: error instanceof Error ? error.message : "Failed to generate reflection",
			});
		}
	});

	// -----------------------------------------------------------------------
	// GET /api/brain/reflections/:planExecId/memories — Get memory proposals
	// -----------------------------------------------------------------------

	fastify.get<{
		Params: { planExecId: string };
	}>("/api/brain/reflections/:planExecId/memories", async (request, reply) => {
		try {
			const { planExecId } = request.params;
			const result = await api.getMemories(planExecId);

			if (!result) {
				return reply.code(404).send({
					success: false,
					error: `Reflection not found for plan execution "${planExecId}"`,
				});
			}

			return reply.send({
				success: true,
				memories: result.memories,
			});
		} catch (error) {
			fastify.log.error({ error }, "Failed to get memory proposals");
			return reply.code(500).send({
				success: false,
				error: error instanceof Error ? error.message : "Failed to get memory proposals",
			});
		}
	});

	// -----------------------------------------------------------------------
	// GET /api/brain/reflections/:planExecId/future — Get future suggestions
	// -----------------------------------------------------------------------

	fastify.get<{
		Params: { planExecId: string };
	}>("/api/brain/reflections/:planExecId/future", async (request, reply) => {
		try {
			const { planExecId } = request.params;
			const result = await api.getFuture(planExecId);

			if (!result) {
				return reply.code(404).send({
					success: false,
					error: `Reflection not found for plan execution "${planExecId}"`,
				});
			}

			return reply.send({
				success: true,
				suggestions: result.suggestions,
			});
		} catch (error) {
			fastify.log.error({ error }, "Failed to get future suggestions");
			return reply.code(500).send({
				success: false,
				error: error instanceof Error ? error.message : "Failed to get future suggestions",
			});
		}
	});
}

/**
 * Brain Protocol API Routes — P15.F
 *
 * REST API for the User Protocol Actions: morning report, daytime
 * approval/rejection, night run configuration, and decision explanations.
 *
 * Endpoints:
 *   GET    /api/brain/protocol/morning        Get morning report data (JSON)
 *   GET    /api/brain/protocol/morning/markdown  Get morning report (Markdown)
 *   POST   /api/brain/protocol/approval       Process an approval/rejection
 *   POST   /api/brain/protocol/rejection      Record a rejection
 *   POST   /api/brain/protocol/memory-correction  Record a memory correction
 *   POST   /api/brain/protocol/night/configure  Configure a night run
 *   POST   /api/brain/protocol/night/:sessionId/start  Start a night run
 *   GET    /api/brain/protocol/night/:sessionId/status  Check night run status
 *   POST   /api/brain/protocol/explain         Explain a decision
 *   GET    /api/brain/protocol/rejections      Get all rejection records
 *
 * Dependencies: P15.F (UserProtocol)
 *
 * Usage:
 * ```typescript
 * import { UserProtocol } from "@earendil-works/pi-coding-agent";
 * const protocol = new UserProtocol(goalStore, autonomyEngine, decisionClassifier);
 * registerBrainProtocolRoutes(fastify, protocol);
 * ```
 */

import type { FastifyInstance } from "fastify";

// ---------------------------------------------------------------------------
// API Interface (duck-typed to avoid direct dependency on coding-agent)
// ---------------------------------------------------------------------------

/**
 * Minimal interface for the User Protocol API.
 *
 * The routes only depend on this interface, not on the concrete
 * UserProtocol class from the coding-agent package.
 * This keeps the web-server free of a direct dependency on
 * the coding-agent package.
 */
export interface BrainProtocolApi {
	getMorningData(): Promise<{
		date: string;
		whatRan: Array<{ planId: string; planTitle: string; status: string }>;
		whatCompleted: Array<{ planId: string; planTitle: string }>;
		whatStopped: Array<{ planId: string; planTitle: string; reason: string }>;
		whatChanged: string[];
		whatLearned: string[];
		needsApproval: Array<{ type: string; id: string; description: string }>;
		top3NextActions: string[];
		artifactLinks: Array<{ label: string; path: string }>;
	}>;

	generateMorningMarkdown(): Promise<string>;

	processApproval(requestId: string, approved: boolean, by: string): Promise<void>;

	processRejection(
		proposalId: string,
		by: string,
		reason?: string,
	): Promise<{
		id: string;
		proposalId: string;
		proposedAt: string;
		rejectedAt: string;
		rejectionReason?: string;
		category: string;
		affected: string[];
		suppressSimilar: boolean;
		memoryUpdated: boolean;
		updatedMemoryId?: string;
	}>;

	processMemoryCorrection(
		memoryId: string,
		correction: string,
		by: string,
	): Promise<{
		id: string;
		originalMemoryId: string;
		reason: string;
		action: string;
		createdAt: string;
		createdBy: string;
	}>;

	configureNightRun(config: {
		queue: string[];
		autonomyLevel: number;
		stopConditions: string[];
		maxDurationHours: number;
		notificationEmail?: string;
		generateMorningReport: boolean;
	}): Promise<{ sessionId: string }>;

	startNightRun(sessionId: string): Promise<void>;

	checkNightRunStatus(sessionId: string): Promise<{ status: string; progress: number }>;

	explainDecision(
		action: string,
		context: Record<string, unknown>,
	): Promise<{
		action: string;
		decision: Record<string, unknown>;
		reasoning: string;
		applicableRules: Array<Record<string, unknown>>;
		autonomyLevel: number;
		appealOptions: string[];
	}>;

	getRejectionRecords(): unknown[];
}

// ---------------------------------------------------------------------------
// Route registration
// ---------------------------------------------------------------------------

/**
 * Register brain protocol API routes on the Fastify instance.
 *
 * @param fastify - The Fastify server instance
 * @param api - A BrainProtocolApi-compatible object
 */
export async function registerBrainProtocolRoutes(fastify: FastifyInstance, api: BrainProtocolApi): Promise<void> {
	// -----------------------------------------------------------------------
	// GET /api/brain/protocol/morning — Get morning report data (JSON)
	// -----------------------------------------------------------------------

	fastify.get("/api/brain/protocol/morning", async (_request, reply) => {
		try {
			const data = await api.getMorningData();
			return { success: true, data };
		} catch (error) {
			fastify.log.error({ error }, "Failed to get morning report data");
			return reply.code(500).send({
				success: false,
				error: error instanceof Error ? error.message : "Failed to get morning report data",
			});
		}
	});

	// -----------------------------------------------------------------------
	// GET /api/brain/protocol/morning/markdown — Get morning report (Markdown)
	// -----------------------------------------------------------------------

	fastify.get("/api/brain/protocol/morning/markdown", async (_request, reply) => {
		try {
			const markdown = await api.generateMorningMarkdown();
			return reply.header("Content-Type", "text/markdown; charset=utf-8").send(markdown);
		} catch (error) {
			fastify.log.error({ error }, "Failed to generate morning markdown");
			return reply.code(500).send({
				success: false,
				error: error instanceof Error ? error.message : "Failed to generate morning markdown",
			});
		}
	});

	// -----------------------------------------------------------------------
	// POST /api/brain/protocol/approval — Process an approval/rejection
	// -----------------------------------------------------------------------

	fastify.post<{
		Body: {
			requestId: string;
			approved: boolean;
			by: string;
		};
	}>("/api/brain/protocol/approval", async (request, reply) => {
		try {
			const { requestId, approved, by } = request.body;
			if (!requestId || by === undefined || by === null) {
				return reply.code(400).send({
					success: false,
					error: "requestId and by are required",
				});
			}
			await api.processApproval(requestId, approved, by);
			return { success: true };
		} catch (error) {
			fastify.log.error({ error }, "Failed to process approval");
			const status = error instanceof Error && error.message.includes("not found") ? 404 : 400;
			return reply.code(status).send({
				success: false,
				error: error instanceof Error ? error.message : "Failed to process approval",
			});
		}
	});

	// -----------------------------------------------------------------------
	// POST /api/brain/protocol/rejection — Record a rejection
	// -----------------------------------------------------------------------

	fastify.post<{
		Body: {
			proposalId: string;
			by: string;
			reason?: string;
		};
	}>("/api/brain/protocol/rejection", async (request, reply) => {
		try {
			const { proposalId, by, reason } = request.body;
			if (!proposalId || !by) {
				return reply.code(400).send({
					success: false,
					error: "proposalId and by are required",
				});
			}
			const record = await api.processRejection(proposalId, by, reason);
			return reply.code(201).send({ success: true, record });
		} catch (error) {
			fastify.log.error({ error }, "Failed to record rejection");
			return reply.code(400).send({
				success: false,
				error: error instanceof Error ? error.message : "Failed to record rejection",
			});
		}
	});

	// -----------------------------------------------------------------------
	// POST /api/brain/protocol/memory-correction — Record a memory correction
	// -----------------------------------------------------------------------

	fastify.post<{
		Body: {
			memoryId: string;
			correction: string;
			by: string;
		};
	}>("/api/brain/protocol/memory-correction", async (request, reply) => {
		try {
			const { memoryId, correction, by } = request.body;
			if (!memoryId || !correction || !by) {
				return reply.code(400).send({
					success: false,
					error: "memoryId, correction, and by are required",
				});
			}
			const record = await api.processMemoryCorrection(memoryId, correction, by);
			return reply.code(201).send({ success: true, record });
		} catch (error) {
			fastify.log.error({ error }, "Failed to record memory correction");
			return reply.code(400).send({
				success: false,
				error: error instanceof Error ? error.message : "Failed to record memory correction",
			});
		}
	});

	// -----------------------------------------------------------------------
	// POST /api/brain/protocol/night/configure — Configure a night run
	// -----------------------------------------------------------------------

	fastify.post<{
		Body: {
			queue: string[];
			autonomyLevel: number;
			stopConditions: string[];
			maxDurationHours: number;
			notificationEmail?: string;
			generateMorningReport: boolean;
		};
	}>("/api/brain/protocol/night/configure", async (request, reply) => {
		try {
			const config = {
				queue: request.body.queue,
				autonomyLevel: request.body.autonomyLevel,
				stopConditions: request.body.stopConditions,
				maxDurationHours: request.body.maxDurationHours,
				notificationEmail: request.body.notificationEmail,
				generateMorningReport: request.body.generateMorningReport,
			};

			if (!config.queue || config.queue.length === 0) {
				return reply.code(400).send({
					success: false,
					error: "queue must contain at least one plan ID",
				});
			}

			const result = await api.configureNightRun(config);
			return reply.code(201).send({ success: true, sessionId: result.sessionId });
		} catch (error) {
			fastify.log.error({ error }, "Failed to configure night run");
			return reply.code(400).send({
				success: false,
				error: error instanceof Error ? error.message : "Failed to configure night run",
			});
		}
	});

	// -----------------------------------------------------------------------
	// POST /api/brain/protocol/night/:sessionId/start — Start a night run
	// -----------------------------------------------------------------------

	fastify.post<{
		Params: { sessionId: string };
	}>("/api/brain/protocol/night/:sessionId/start", async (request, reply) => {
		try {
			await api.startNightRun(request.params.sessionId);
			return { success: true };
		} catch (error) {
			fastify.log.error({ error }, "Failed to start night run");
			const status = error instanceof Error && error.message.includes("not found") ? 404 : 400;
			return reply.code(status).send({
				success: false,
				error: error instanceof Error ? error.message : "Failed to start night run",
			});
		}
	});

	// -----------------------------------------------------------------------
	// GET /api/brain/protocol/night/:sessionId/status — Check night run status
	// -----------------------------------------------------------------------

	fastify.get<{
		Params: { sessionId: string };
	}>("/api/brain/protocol/night/:sessionId/status", async (request, reply) => {
		try {
			const status = await api.checkNightRunStatus(request.params.sessionId);
			return { success: true, ...status };
		} catch (error) {
			fastify.log.error({ error }, "Failed to check night run status");
			const statusCode = error instanceof Error && error.message.includes("not found") ? 404 : 500;
			return reply.code(statusCode).send({
				success: false,
				error: error instanceof Error ? error.message : "Failed to check night run status",
			});
		}
	});

	// -----------------------------------------------------------------------
	// POST /api/brain/protocol/explain — Explain a decision
	// -----------------------------------------------------------------------

	fastify.post<{
		Body: {
			action: string;
			context?: Record<string, unknown>;
		};
	}>("/api/brain/protocol/explain", async (request, reply) => {
		try {
			const { action, context = {} } = request.body;
			if (!action) {
				return reply.code(400).send({
					success: false,
					error: "action is required",
				});
			}
			const explanation = await api.explainDecision(action, context);
			return { success: true, explanation };
		} catch (error) {
			fastify.log.error({ error }, "Failed to explain decision");
			return reply.code(500).send({
				success: false,
				error: error instanceof Error ? error.message : "Failed to explain decision",
			});
		}
	});

	// -----------------------------------------------------------------------
	// GET /api/brain/protocol/rejections — Get all rejection records
	// -----------------------------------------------------------------------

	fastify.get("/api/brain/protocol/rejections", async (_request, reply) => {
		try {
			const records = api.getRejectionRecords();
			return { success: true, records };
		} catch (error) {
			fastify.log.error({ error }, "Failed to get rejection records");
			return reply.code(500).send({
				success: false,
				records: [],
				error: error instanceof Error ? error.message : "Failed to get rejection records",
			});
		}
	});
}

