	seed(...proposals: Proposal[]): void {
		for (const p of proposals) {
			this.proposals.set(p.id, p);
		}
	}

	/**
	 * Clear all proposals from the store.
	 */
	clear(): void {
		this.proposals.clear();
	}

	/**
	 * Get the total number of stored proposals.
	 */
	get size(): number {
		return this.proposals.size;
	}
