		const records: PreferenceRecord[] = [];
		for (const id of ids) {
			try {
				const record = await this.getPreference(id);
				if (record) {
					records.push(record);
				}
			} catch {
				// Skip corrupt or missing records
			}
		}

		return records;
	}

