	private ensureInitialized(): void {
		if (!this.initialized) {
			throw new Error("GoalStore not initialized. Call initialize() before performing CRUD operations.");
		}
	}

	private async withWriteLock<T>(fn: () => Promise<T>): Promise<T> {
		const prev = this.writeLock;
		let resolve: () => void;
		this.writeLock = new Promise<void>((r) => {
			resolve = r;
		});

		await prev;
		try {
			return await fn();
		} finally {
			resolve!();
		}
	}

	private async loadIndex(): Promise<GoalIndex> {
		try {
			const json = await fs.readFile(this.config.indexPath, "utf-8");
			const parsed = JSON.parse(json) as GoalIndex;
			if (parsed.byId && parsed.byStatus && parsed.byPriority && parsed.byCategory) {
				return parsed;
			}
			return this.createEmptyIndex();
		} catch {
			return this.createEmptyIndex();
		}
	}

	private async saveIndex(): Promise<void> {
		this.index.lastUpdated = new Date().toISOString();
		await this.atomicWrite(this.config.indexPath, JSON.stringify(this.index, null, 2));
	}

	private async atomicWrite(filePath: string, data: string): Promise<void> {
		const byteLength = Buffer.byteLength(data, "utf-8");
		if (byteLength > this.config.maxFileSizeBytes) {
			throw new Error(`File size ${byteLength} bytes exceeds maximum ${this.config.maxFileSizeBytes} bytes`);
		}

		const dir = path.dirname(filePath);
		await fs.mkdir(dir, { recursive: true });

		const tmpPath = `${filePath}.tmp.${Date.now()}.${Math.random().toString(36).slice(2, 8)}`;
		try {
			await fs.writeFile(tmpPath, data, "utf-8");
			await fs.rename(tmpPath, filePath);
		} catch (err) {
			try {
				await fs.unlink(tmpPath);
			} catch {
				// Ignore cleanup errors
			}
			throw err;
		}
	}

	private async readFileSafe(filePath: string): Promise<string | null> {
		try {
			const stat = await fs.stat(filePath);
			if (stat.size > this.config.maxFileSizeBytes) {
				return null;
			}
			return await fs.readFile(filePath, "utf-8");
		} catch {
			return null;
		}
	}

	private createEmptyIndex(): GoalIndex {
		const byStatus = {} as Record<GoalStatus, string[]>;
		const byPriority = {} as Record<GoalPriority, string[]>;
		const byCategory: Record<string, string[]> = {};
		const preferencesByCategory = {} as Record<PreferenceCategory, string[]>;
		const driftByGoalId: Record<string, string[]> = {};

		for (const s of ALL_GOAL_STATUSES) {
			byStatus[s] = [];
		}
		for (const p of ALL_GOAL_PRIORITIES) {
			byPriority[p] = [];
		}
		for (const c of ALL_PREFERENCE_CATEGORIES) {
			preferencesByCategory[c] = [];
		}

		return {
			byId: {},
			byStatus,
			byPriority,
			byCategory,
			preferencesByCategory,
			driftByGoalId,
			lastUpdated: new Date().toISOString(),
		};
	}

	private updateGoalIndexEntry(record: GoalRecord): void {
		this.addGoalToIndex(this.index, record);
	}

	private addGoalToIndex(index: GoalIndex, record: GoalRecord): void {
		const entry: GoalIndexEntry = {
			id: record.id,
			status: record.status,
			priority: record.priority,
			category: record.category,
			createdAt: record.createdAt,
			updatedAt: record.updatedAt,
		};

		// Remove old entry if present (for updates)
		const oldEntry = index.byId[record.id];
		if (oldEntry) {
			this.removeGoalFromIndexLists(index, record.id, oldEntry);
		}

		index.byId[record.id] = entry;

		// byStatus
		if (!index.byStatus[record.status]) {
			index.byStatus[record.status] = [];
		}
		if (!index.byStatus[record.status].includes(record.id)) {
			index.byStatus[record.status].push(record.id);
		}

		// byPriority
		if (!index.byPriority[record.priority]) {
			index.byPriority[record.priority] = [];
		}
		if (!index.byPriority[record.priority].includes(record.id)) {
			index.byPriority[record.priority].push(record.id);
		}

		// byCategory (case-insensitive key)
		const catKey = record.category.toLowerCase();
		if (!index.byCategory[catKey]) {
			index.byCategory[catKey] = [];
		}
		if (!index.byCategory[catKey].includes(record.id)) {
			index.byCategory[catKey].push(record.id);
		}
	}

	private removeGoalIndexEntry(id: string): void {
		const entry = this.index.byId[id];
		if (!entry) return;
		this.removeGoalFromIndexLists(this.index, id, entry);
		delete this.index.byId[id];
	}

	private removeGoalFromIndexLists(index: GoalIndex, id: string, entry: GoalIndexEntry): void {
		// byStatus
		const statusList = index.byStatus[entry.status];
		if (statusList) {
			const idx = statusList.indexOf(id);
			if (idx !== -1) statusList.splice(idx, 1);
		}

		// byPriority
		const priorityList = index.byPriority[entry.priority];
		if (priorityList) {
			const idx = priorityList.indexOf(id);
			if (idx !== -1) priorityList.splice(idx, 1);
		}

		// byCategory
		const catKey = entry.category.toLowerCase();
		const catList = index.byCategory[catKey];
		if (catList) {
			const idx = catList.indexOf(id);
			if (idx !== -1) catList.splice(idx, 1);
			if (catList.length === 0) {
				delete index.byCategory[catKey];
			}
		}
	}

	private updatePreferenceIndexEntry(record: PreferenceRecord): void {
		this.addPreferenceToIndex(this.index, record);
	}

	private addPreferenceToIndex(index: GoalIndex, record: PreferenceRecord): void {
		if (!index.preferencesByCategory[record.category]) {
			index.preferencesByCategory[record.category] = [];
		}
		if (!index.preferencesByCategory[record.category].includes(record.id)) {
			index.preferencesByCategory[record.category].push(record.id);
		}
	}

	private removePreferenceIndexEntry(id: string, category: PreferenceCategory): void {
		const catList = this.index.preferencesByCategory[category];
		if (catList) {
			const idx = catList.indexOf(id);
			if (idx !== -1) catList.splice(idx, 1);
		}
	}

	private updateDriftIndexEntry(report: GoalDriftReport): void {
		this.addDriftToIndex(this.index, report);
	}

	private addDriftToIndex(index: GoalIndex, report: GoalDriftReport): void {
		if (!index.driftByGoalId[report.goalId]) {
			index.driftByGoalId[report.goalId] = [];
		}
		if (!index.driftByGoalId[report.goalId].includes(report.id)) {
			index.driftByGoalId[report.goalId].push(report.id);
		}
	}

	private intersectSets(a: Set<string> | null, b: Set<string>): Set<string> {
		if (a === null) return new Set(b);
		const result = new Set<string>();
		for (const item of a) {
			if (b.has(item)) result.add(item);
		}
		return result;
	}
}

/**
 * Edit Audit Events - Makes edit strategy decisions, failures, and token-waste prevention visible.
 *
 * P4.5 Workstream 4.5.E: Provides audit event emission for:
 * - edit_strategy_selected
 * - edit_strategy_blocked
 * - full_rewrite_attempted
 * - edit_truncation_detected
 * - edit_exact_match_failed
 * - patch_fallback_forced
 * - edit_failure_handoff
 * - token_waste_prevented
 *
 * Events are emitted on the EventBus and can be archived for reporting.
 */

import type {
	EditAuditEventPayload,
	EditAuditEventType,
	EditFailureType,
	EditStrategyMode,
	EditStrategyReasonCode,
} from "./edit-strategy-types.js";
import type { EventBus } from "./event-bus.js";

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------

/** Event channel for all edit strategy audit events. */
export const EDIT_AUDIT_CHANNEL = "edit_strategy_audit";

// ---------------------------------------------------------------------------
// EditAuditEventEmitter
// ---------------------------------------------------------------------------

/**
 * Emits structured audit events for all edit strategy decisions, failures,
 * fallbacks, and handoffs. Events are emitted on the EventBus and can be
 * consumed by dashboards, logging, and reporting systems.
 *
 * Each event includes planExecId, workspaceId, filePath, mode, strategy,
 * lineCount, byteSize, attemptNumber, failureType, and reasonCode.
 */
export class EditAuditEventEmitter {
	private eventBus: EventBus | undefined;
	private eventLog: EditAuditEventPayload[] = [];

	constructor(options?: { eventBus?: EventBus }) {
		this.eventBus = options?.eventBus;
	}

	/**
	 * Emit an edit_strategy_selected event.
	 *
	 * @param planExecId - Plan execution ID
	 * @param workspaceId - Workspace ID
	 * @param filePath - Relative file path
	 * @param mode - Selected edit strategy mode
	 * @param lineCount - Line count of the file
	 * @param byteSize - Byte size of the file
	 */
	emitStrategySelected(
		planExecId: string,
		workspaceId: string,
		filePath: string,
		mode: EditStrategyMode,
		lineCount?: number,
		byteSize?: number,
	): void {
		this.emit({
			eventType: "edit_strategy_selected",
			planExecId,
			workspaceId,
			filePath,
			mode,
			lineCount,
			byteSize,
			timestamp: Date.now(),
		});
	}

	/**
	 * Emit an edit_strategy_blocked event.
	 *
	 * @param planExecId - Plan execution ID
	 * @param workspaceId - Workspace ID
	 * @param filePath - Relative file path
	 * @param mode - Current edit strategy mode
	 * @param reasonCode - Reason code for blocking
	 * @param lineCount - Line count of the file
	 * @param byteSize - Byte size of the file
	 */
	emitStrategyBlocked(
		planExecId: string,
		workspaceId: string,
		filePath: string,
		mode: EditStrategyMode,
		reasonCode: EditStrategyReasonCode,
		lineCount?: number,
		byteSize?: number,
	): void {
		this.emit({
			eventType: "edit_strategy_blocked",
			planExecId,
			workspaceId,
			filePath,
			mode,
			reasonCode,
			lineCount,
			byteSize,
			timestamp: Date.now(),
		});
	}

	/**
	 * Emit a full_rewrite_attempted event.
	 *
	 * @param planExecId - Plan execution ID
	 * @param workspaceId - Workspace ID
	 * @param filePath - Relative file path
	 * @param mode - Current edit strategy mode
	 * @param lineCount - Line count of the file
	 * @param byteSize - Byte size of the file
	 */
	emitFullRewriteAttempted(
		planExecId: string,
		workspaceId: string,
		filePath: string,
		mode: EditStrategyMode,
		lineCount?: number,
		byteSize?: number,
	): void {
		this.emit({
			eventType: "full_rewrite_attempted",
			planExecId,
			workspaceId,
			filePath,
			mode,
			strategy: "full_write",
			lineCount,
			byteSize,
			timestamp: Date.now(),
		});
	}

	/**
	 * Emit an edit_truncation_detected event.
	 *
	 * @param planExecId - Plan execution ID
	 * @param workspaceId - Workspace ID
	 * @param filePath - Relative file path
	 * @param mode - Current edit strategy mode
	 * @param attemptNumber - Attempt number
	 */
	emitTruncationDetected(
		planExecId: string,
		workspaceId: string,
		filePath: string,
		mode: EditStrategyMode,
		attemptNumber?: number,
	): void {
		this.emit({
			eventType: "edit_truncation_detected",
			planExecId,
			workspaceId,
			filePath,
			mode,
			strategy: "full_write",
			failureType: "truncation",
			attemptNumber,
			timestamp: Date.now(),
		});
	}

	/**
	 * Emit an edit_exact_match_failed event.
	 *
	 * @param planExecId - Plan execution ID
	 * @param workspaceId - Workspace ID
	 * @param filePath - Relative file path
	 * @param mode - Current edit strategy mode
	 * @param attemptNumber - Attempt number
	 */
	emitExactMatchFailed(
		planExecId: string,
		workspaceId: string,
		filePath: string,
		mode: EditStrategyMode,
		attemptNumber?: number,
	): void {
		this.emit({
			eventType: "edit_exact_match_failed",
			planExecId,
			workspaceId,
			filePath,
			mode,
			strategy: "targeted_edit",
			failureType: "exact_match_failed",
			attemptNumber,
			timestamp: Date.now(),
		});
	}

	/**
	 * Emit a patch_fallback_forced event.
	 *
	 * @param planExecId - Plan execution ID
	 * @param workspaceId - Workspace ID
	 * @param filePath - Relative file path
	 * @param mode - Current edit strategy mode
	 * @param reasonCode - Reason code for fallback
	 */
	emitPatchFallbackForced(
		planExecId: string,
		workspaceId: string,
		filePath: string,
		mode: EditStrategyMode,
		reasonCode?: EditStrategyReasonCode,
	): void {
		this.emit({
			eventType: "patch_fallback_forced",
			planExecId,
			workspaceId,
			filePath,
			mode,
			strategy: "targeted_edit",
			reasonCode,
			timestamp: Date.now(),
		});
	}

	/**
	 * Emit an edit_failure_handoff event.
	 *
	 * @param planExecId - Plan execution ID
	 * @param workspaceId - Workspace ID
	 * @param filePath - Relative file path
	 * @param mode - Current edit strategy mode
	 * @param failureType - Primary failure type
	 */
	emitFailureHandoff(
		planExecId: string,
		workspaceId: string,
		filePath: string,
		mode: EditStrategyMode,
		failureType?: EditFailureType,
	): void {
		this.emit({
			eventType: "edit_failure_handoff",
			planExecId,
			workspaceId,
			filePath,
			mode,
			failureType,
			timestamp: Date.now(),
		});
	}

	/**
	 * Emit a token_waste_prevented event.
	 *
	 * @param planExecId - Plan execution ID
	 * @param workspaceId - Workspace ID
	 * @param filePath - Relative file path
	 * @param mode - Current edit strategy mode
	 * @param reasonCode - Reason for prevention
	 */
	emitTokenWastePrevented(
		planExecId: string,
		workspaceId: string,
		filePath: string,
		mode: EditStrategyMode,
		reasonCode: EditStrategyReasonCode,
	): void {
		this.emit({
			eventType: "token_waste_prevented",
			planExecId,
			workspaceId,
			filePath,
			mode,
			reasonCode,
			timestamp: Date.now(),
		});
	}

	/**
	 * Get all events that have been emitted.
	 *
	 * @returns Array of emitted event payloads
	 */
	getEventLog(): EditAuditEventPayload[] {
		return [...this.eventLog];
	}

	/**
	 * Get events filtered by type.
	 *
	 * @param eventType - Event type to filter by
	 * @returns Filtered events
	 */
	getEventsByType(eventType: EditAuditEventType): EditAuditEventPayload[] {
		return this.eventLog.filter((e) => e.eventType === eventType);
	}

	/**
	 * Generate a final summary of edit strategy events.
	 *
	 * @returns Summary object
	 */
	generateSummary(): EditStrategyAuditSummary {
		const summary: EditStrategyAuditSummary = {
			editModeUsed: undefined,
			blockedRewrites: 0,
			truncationEvents: 0,
			exactMatchFailures: 0,
			handoffs: 0,
			estimatedWastePrevented: 0,
		};

		for (const event of this.eventLog) {
			switch (event.eventType) {
				case "edit_strategy_selected":
					summary.editModeUsed = event.mode;
					break;
				case "edit_strategy_blocked":
					summary.blockedRewrites++;
					summary.estimatedWastePrevented++;
					break;
				case "edit_truncation_detected":
					summary.truncationEvents++;
					break;
				case "edit_exact_match_failed":
					summary.exactMatchFailures++;
					break;
				case "edit_failure_handoff":
					summary.handoffs++;
					break;
				case "token_waste_prevented":
					summary.estimatedWastePrevented++;
					break;
			}
		}

		return summary;
	}

	/**
	 * Clear the event log.
	 */
	clear(): void {
		this.eventLog = [];
	}

	// -----------------------------------------------------------------------
	// Private
	// -----------------------------------------------------------------------

	/**
	 * Emit an event to both the event bus and the internal log.
	 */
	private emit(payload: EditAuditEventPayload): void {
		this.eventLog.push(payload);

		if (this.eventBus) {
			this.eventBus.emit(EDIT_AUDIT_CHANNEL, payload);
		}
	}
}

// ---------------------------------------------------------------------------
// Summary Types
// ---------------------------------------------------------------------------

/**
 * Summary of edit strategy audit events for a plan execution.
 */
export interface EditStrategyAuditSummary {
	/** Edit mode used during execution */
	editModeUsed: EditStrategyMode | undefined;
	/** Number of blocked full rewrites */
	blockedRewrites: number;
	/** Number of truncation events */
	truncationEvents: number;
	/** Number of exact-match edit failures */
	exactMatchFailures: number;
	/** Number of edit failure handoffs */
	handoffs: number;
	/** Estimated number of token-waste events prevented */
	estimatedWastePrevented: number;
}

// ---------------------------------------------------------------------------
// Factory
// ---------------------------------------------------------------------------

/**
 * Create an EditAuditEventEmitter instance.
 *
 * @param options - Emitter configuration
 * @returns EditAuditEventEmitter instance
 */
export function createEditAuditEventEmitter(options?: { eventBus?: EventBus }): EditAuditEventEmitter {
	return new EditAuditEventEmitter(options);
}

/**
 * Write Gate - Guards full-writes to existing large files.
 *
 * P4.5: Before the write tool overwrites an existing file, the write gate consults
 * the EditStrategyPolicy to decide whether a full rewrite is allowed or
 * whether only targeted edits (patches) should be used.
 *
 * Also integrates with:
 * - TruncationDetector: Detects truncation in tool output and forces fallback
 * - EditAttemptTracker: Records attempted writes and their outcomes
 * - EditAuditEventEmitter: Emits audit events for visibility
 *
 * For guarded files (existing files whose size exceeds the policy threshold),
 * the gate:
 *   1. Consults EditStrategyPolicy.checkPolicy()
 *   2. Creates a pre-write snapshot (in-memory copy of the file content)
 *   3. Blocks the full write if the policy disallows it
 *   4. Emits an "edit_strategy_blocked" event on the EventBus when blocked
 */

import { readFile as fsReadFile, stat as fsStat } from "fs/promises";
import type { EditAttemptTracker } from "./edit-attempt-tracker.js";
import type { EditAuditEventEmitter } from "./edit-audit-events.js";
import type { EditStrategyPolicy, EditStrategyReasonCode, EditStrategyResult } from "./edit-strategy-policy.js";
import type { EventBus } from "./event-bus.js";
import type { TruncationDetector } from "./truncation-detector.js";

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

/** Result of a write gate check. */
export interface WriteGateResult {
	/** Whether the full write is allowed to proceed. */
	allowed: boolean;
	/** Whether this was a new-file write (always allowed). */
	isNewFile: boolean;
	/** Human-readable reason (empty when allowed). */
	reason: string;
	/** Reason code from the edit strategy policy. */
	reasonCode: EditStrategyReasonCode | undefined;
	/** Pre-write snapshot content (set for guarded existing files, even when blocked). */
	snapshot: string | undefined;
	/** Whether truncation forced fallback (P4.5). */
	truncationFallback: boolean;
	/** Whether same-file failure threshold is reached (P4.5). */
	handoffTriggered: boolean;
}

/** Event data emitted when a full write is blocked by the gate. */
export interface EditStrategyBlockedEvent {
	/** Relative or absolute path of the file. */
	filePath: string;
	/** Number of lines in the existing file. */
	existingLineCount: number;
	/** Byte size of the existing file. */
	existingByteSize: number;
	/** Reason code from the policy. */
	reasonCode: EditStrategyReasonCode;
	/** Human-readable reason. */
	reason: string;
}

/** Options for constructing a WriteGate. */
export interface WriteGateOptions {
	/** The edit strategy policy to consult. */
	policy: EditStrategyPolicy;
	/** Optional event bus for emitting edit_strategy_blocked events. */
	eventBus?: EventBus;
	/** Optional truncation detector (P4.5). */
	truncationDetector?: TruncationDetector;
	/** Optional edit attempt tracker (P4.5). */
	attemptTracker?: EditAttemptTracker;
	/** Optional audit event emitter (P4.5). */
	auditEmitter?: EditAuditEventEmitter;
	/** Plan execution ID for tracking (P4.5). */
	planExecId?: string;
	/** Workspace ID for tracking (P4.5). */
	workspaceId?: string;
	/** Custom stat function (for testing). Default: fs.stat. */
	stat?: (path: string) => Promise<{ size: number; isFile: () => boolean }>;
	/** Custom readFile function (for testing). Default: fs.readFile. */
	readFile?: (path: string) => Promise<Buffer>;
}

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------

/** Event channel name for blocked-write events. */
export const EDIT_STRATEGY_BLOCKED_CHANNEL = "edit_strategy_blocked";

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/**
 * Count the number of lines in a string.
 *
 * Uses the same convention as the read/edit tools: split on newlines,
 * treating both LF and CRLF as line breaks.
 *
 * @param content - File content string
 * @returns Number of lines (0 for empty string, 1 for single line without newline)
 */
export function countLines(content: string): number {
	if (content.length === 0) return 0;
	const normalized = content.replace(/\r\n/g, "\n");
	const lines = normalized.split("\n");
	return lines.length;
}

// ---------------------------------------------------------------------------
// WriteGate
// ---------------------------------------------------------------------------

/**
 * Gate that intercepts write tool invocations and blocks full rewrites of
 * existing large files unless the EditStrategyPolicy permits them.
 *
 * P4.5 enhancements:
 * - Integrates with TruncationDetector to detect truncated writes
 * - Integrates with EditAttemptTracker to record write attempts
 * - Integrates with EditAuditEventEmitter for audit visibility
 * - Blocks writes when same-file failure threshold is reached
 * - Forces fallback after truncation detection
 */
export class WriteGate {
	private readonly policy: EditStrategyPolicy;
	private readonly eventBus: EventBus | undefined;
	private readonly truncationDetector: TruncationDetector | undefined;
	private readonly attemptTracker: EditAttemptTracker | undefined;
	private readonly auditEmitter: EditAuditEventEmitter | undefined;
	private readonly planExecId: string;
	private readonly workspaceId: string;
	private readonly statFn: (path: string) => Promise<{ size: number; isFile: () => boolean }>;
	private readonly readFileFn: (path: string) => Promise<Buffer>;

	constructor(options: WriteGateOptions) {
		this.policy = options.policy;
		this.eventBus = options.eventBus;
		this.truncationDetector = options.truncationDetector;
		this.attemptTracker = options.attemptTracker;
		this.auditEmitter = options.auditEmitter;
		this.planExecId = options.planExecId ?? "unknown";
		this.workspaceId = options.workspaceId ?? "unknown";
		this.statFn =
			options.stat ??
			((path: string) => fsStat(path) as unknown as Promise<{ size: number; isFile: () => boolean }>);
		this.readFileFn = options.readFile ?? ((path: string) => fsReadFile(path));
	}

	/**
	 * Check whether a full write to the given file path is allowed.
	 *
	 * For new files (files that don't exist on disk), the write is always allowed.
	 * For existing files, the EditStrategyPolicy is consulted. If the policy
	 * disallows a full rewrite:
	 *   - The write gate blocks the operation
	 *   - A pre-write snapshot is still created
	 *   - An "edit_strategy_blocked" event is emitted on the EventBus
	 *
	 * P4.5 additions:
	 *   - If same-file failure threshold is reached, the write is blocked
	 *   - Truncation detection can force fallback
	 *
	 * @param filePath - Absolute path to the file being written
	 * @param relativePath - Relative path (for policy and event data)
	 * @param newContentByteSize - Byte size of the content being written
	 * @param outputBudgetRemaining - Remaining output token budget (undefined = not checked)
	 * @param newLineCount - Number of lines in the new content
	 * @returns WriteGateResult indicating whether the write is allowed
	 */
	async check(
		filePath: string,
		relativePath: string,
		newContentByteSize: number = 0,
		outputBudgetRemaining?: number,
		newLineCount: number = 0,
	): Promise<WriteGateResult> {
		// P4.5: Check if same-file failure threshold is reached
		if (this.attemptTracker && this.planExecId && this.workspaceId !== "unknown") {
			if (this.attemptTracker.hasReachedHandoffThreshold(this.planExecId, this.workspaceId, relativePath)) {
				return {
					allowed: false,
					isNewFile: false,
					reason: `Cannot write "${relativePath}": same-file edit failure threshold reached. Manual intervention required.`,
					reasonCode: undefined,
					snapshot: undefined,
					truncationFallback: false,
					handoffTriggered: true,
				};
			}
		}

		// Check if file exists and get its stats
		let existingByteSize: number;
		let existingLineCount: number;
		let isNewFile: boolean;
		let snapshot: string | undefined;

		try {
			const stats = await this.statFn(filePath);
			if (!stats.isFile()) {
				// Not a regular file - treat as new
				return {
					allowed: true,
					isNewFile: true,
					reason: "",
					reasonCode: undefined,
					snapshot: undefined,
					truncationFallback: false,
					handoffTriggered: false,
				};
			}
			isNewFile = false;
			existingByteSize = stats.size;

			// Read the file to count lines and create snapshot
			const buffer = await this.readFileFn(filePath);
			const content = buffer.toString("utf-8");
			existingLineCount = countLines(content);
			snapshot = content;
		} catch {
			// File does not exist - new file write always allowed
			return {
				allowed: true,
				isNewFile: true,
				reason: "",
				reasonCode: undefined,
				snapshot: undefined,
				truncationFallback: false,
				handoffTriggered: false,
			};
		}

		// Consult the EditStrategyPolicy
		const policyResult: EditStrategyResult = this.policy.checkPolicy(
			relativePath,
			isNewFile,
			existingLineCount,
			existingByteSize,
			newContentByteSize,
			outputBudgetRemaining,
			newLineCount,
		);

		// P4.5: Emit audit event for strategy selection
		if (this.auditEmitter && this.planExecId && this.workspaceId !== "unknown") {
			this.auditEmitter.emitStrategySelected(
				this.planExecId,
				this.workspaceId,
				relativePath,
				this.policy.getMode(),
				existingLineCount,
				existingByteSize,
			);
		}

		if (policyResult.writeAllowed) {
			// P4.5: Record that a full rewrite was attempted
			if (this.auditEmitter && this.planExecId && this.workspaceId !== "unknown") {
				this.auditEmitter.emitFullRewriteAttempted(
					this.planExecId,
					this.workspaceId,
					relativePath,
					this.policy.getMode(),
					existingLineCount,
					existingByteSize,
				);
			}

			return {
				allowed: true,
				isNewFile: false,
				reason: "",
				reasonCode: policyResult.reasonCode,
				snapshot,
				truncationFallback: false,
				handoffTriggered: false,
			};
		}

		// Full write is blocked
		this.emitBlockedEvent(
			relativePath,
			existingLineCount,
			existingByteSize,
			policyResult.reasonCode,
			policyResult.reason,
		);

		// P4.5: Emit audit events for blocked rewrite and token waste prevention
		if (this.auditEmitter && this.planExecId && this.workspaceId !== "unknown") {
			this.auditEmitter.emitStrategyBlocked(
				this.planExecId,
				this.workspaceId,
				relativePath,
				this.policy.getMode(),
				policyResult.reasonCode,
				existingLineCount,
				existingByteSize,
			);
			this.auditEmitter.emitTokenWastePrevented(
				this.planExecId,
				this.workspaceId,
				relativePath,
				this.policy.getMode(),
				policyResult.reasonCode,
			);
		}

		return {
			allowed: false,
			isNewFile: false,
			reason: policyResult.reason,
			reasonCode: policyResult.reasonCode,
			snapshot,
			truncationFallback: false,
			handoffTriggered: false,
		};
	}

	/**
	 * Process the result of a write operation for truncation detection.
	 *
	 * Called after a write tool completes (successfully or not) to detect
	 * truncation and record the attempt.
	 *
	 * @param relativePath - Relative file path
	 * @param writeOutput - Output/result from the write tool
	 * @param succeeded - Whether the write succeeded
	 */
	processWriteResult(relativePath: string, writeOutput: string, succeeded: boolean): void {
		if (
			!this.attemptTracker ||
			!this.truncationDetector ||
			this.planExecId === "unknown" ||
			this.workspaceId === "unknown"
		) {
			return;
		}

		if (succeeded) {
			this.attemptTracker.recordSuccess(this.planExecId, this.workspaceId, relativePath, "full_write");
		} else {
			// Detect failure type from output
			const detection = this.truncationDetector.detectAny(writeOutput);
			const failureType = detection.failureType ?? "restore_after_failed_write";

			this.attemptTracker.recordFailure(
				this.planExecId,
				this.workspaceId,
				relativePath,
				"full_write",
				failureType,
				writeOutput.slice(0, 500),
			);

			// Emit appropriate audit event
			if (this.auditEmitter) {
				if (detection.failureType === "truncation") {
					this.auditEmitter.emitTruncationDetected(
						this.planExecId,
						this.workspaceId,
						relativePath,
						this.policy.getMode(),
					);
				} else if (detection.failureType === "exact_match_failed") {
					this.auditEmitter.emitExactMatchFailed(
						this.planExecId,
						this.workspaceId,
						relativePath,
						this.policy.getMode(),
					);
				}

				// If truncation detected, emit patch fallback forced
				if (detection.failureType === "truncation" && this.policy.isTruncationFallbackEnabled()) {
					this.auditEmitter.emitPatchFallbackForced(
						this.planExecId,
						this.workspaceId,
						relativePath,
						this.policy.getMode(),
					);
				}
			}
		}
	}

	/**
	 * Process the result of an edit operation for failure detection.
	 *
	 * @param relativePath - Relative file path
	 * @param editOutput - Output/result from the edit tool
	 * @param succeeded - Whether the edit succeeded
	 */
	processEditResult(relativePath: string, editOutput: string, succeeded: boolean): void {
		if (!this.attemptTracker || this.planExecId === "unknown" || this.workspaceId === "unknown") {
			return;
		}

		if (succeeded) {
			this.attemptTracker.recordSuccess(this.planExecId, this.workspaceId, relativePath, "targeted_edit");
		} else {
			const detection = this.truncationDetector?.detectAny(editOutput);
			const failureType = detection?.failureType ?? "exact_match_failed";

			this.attemptTracker.recordFailure(
				this.planExecId,
				this.workspaceId,
				relativePath,
				"targeted_edit",
				failureType,
				editOutput.slice(0, 500),
			);

			if (this.auditEmitter && detection?.failureType === "exact_match_failed") {
				this.auditEmitter.emitExactMatchFailed(
					this.planExecId,
					this.workspaceId,
					relativePath,
					this.policy.getMode(),
				);
			}
		}
	}

	/**
	 * Emit an edit_strategy_blocked event on the EventBus.
	 */
	private emitBlockedEvent(
		filePath: string,
		existingLineCount: number,
		existingByteSize: number,
		reasonCode: EditStrategyReasonCode,
		reason: string,
	): void {
		if (!this.eventBus) return;

		const eventData: EditStrategyBlockedEvent = {
			filePath,
			existingLineCount,
			existingByteSize,
			reasonCode,
			reason,
		};

		this.eventBus.emit(EDIT_STRATEGY_BLOCKED_CHANNEL, eventData);
	}
}

