// Factory
// ---------------------------------------------------------------------------

export function createAuditLedger(options?: {
	basePath?: string;
	rotationThresholdBytes?: number;
	flushIntervalMs?: number;
	batchSize?: number;
}): AuditLedger {
	return new AuditLedger(options);
}

