/**
 * Policy Engine V0 — P18.A
 *
 * Evaluates any action against policy rules and returns a policy decision
 * (allow / deny / approval_required / forbidden).
 *
 * Features:
 * - Rule-based evaluation with priority ordering (higher priority evaluated first)
 * - Glob pattern matching on action names ("memory_*" matches "memory_creation")
 * - Context-aware evaluation (autonomy level, risk level, affected system)
 * - Time-restricted rules (e.g., block during maintenance window)
 * - Recent-decision cache with configurable TTL
 * - Default-deny when no rule matches (fail-safe)
 * - Integration with AuditLedger for decision logging
 *
 * Dependencies: P18.B RuleStore, P18.E AuditLedger
 */

import { randomUUID } from "node:crypto";
import type { AuditEntry } from "../audit/ledger.js";
import type { RuleStore } from "./store.js";
import type { PolicyCondition, PolicyContext, PolicyDecision, PolicyResult, PolicyRule } from "./types.js";

// ---------------------------------------------------------------------------
// Configuration
// ---------------------------------------------------------------------------

export interface PolicyEngineConfig {
	/**
	 * Time-to-live for cached decisions in milliseconds.
	 * Default: 5000 (5 seconds)
	 */
	cacheTtlMs: number;

	/**
	 * Maximum number of cached entries.
	 * Default: 1000
	 */
	maxCacheSize: number;
}

const DEFAULT_CONFIG: PolicyEngineConfig = {
	cacheTtlMs: 5000,
	maxCacheSize: 1000,
};

// ---------------------------------------------------------------------------
// Cache Entry
// ---------------------------------------------------------------------------

interface CacheEntry {
	result: PolicyResult;
	cachedAt: number;
}

// ---------------------------------------------------------------------------
// PolicyEngine
// ---------------------------------------------------------------------------

export class PolicyEngine {
	private ruleStore: RuleStore;
	private cache: Map<string, CacheEntry>;
	private config: PolicyEngineConfig;

	constructor(ruleStore: RuleStore, config?: Partial<PolicyEngineConfig>) {
		this.ruleStore = ruleStore;
		this.cache = new Map<string, CacheEntry>();
		this.config = { ...DEFAULT_CONFIG, ...config };
	}

	// -----------------------------------------------------------------------
	// Public API
	// -----------------------------------------------------------------------

	/**
	 * Evaluate a single action against all policy rules.
	 *
	 * 1. Check cache for a recent decision on the same context.
	 * 2. Load all enabled rules from the store.
	 * 3. Filter to matching rules (by action glob + context conditions).
	 * 4. Sort by priority (highest first).
	 * 5. Return the highest-priority matching rule's decision.
	 * 6. If no rule matches, return default-deny.
	 *
	 * @param context - The policy context describing the action being taken
	 * @returns PolicyResult with decision, matched rule, and explanation
	 */
	async evaluate(context: PolicyContext): Promise<PolicyResult> {
		const startTime = Date.now();

		// 1. Check cache
		const key = this.cacheKey(context);
		const cached = this.cache.get(key);
		if (cached && Date.now() - cached.cachedAt < this.config.cacheTtlMs) {
			return cached.result;
		}

		// 2. Load enabled rules from store
		const allRules = await this.ruleStore.listRules({ enabled: true });

		// 3. Filter to matching rules (by action glob + context conditions)
		const matchingRules = this.findMatchingRules(allRules, context);

		// 4. Sort by priority (highest first)
		const sorted = this.sortByPriority(matchingRules);

		// 5. Determine result
		let result: PolicyResult;

		if (sorted.length === 0) {
			// No matching rule → default deny
			result = {
				decision: this.getDefaultDecision(),
				matchedRule: null,
				allEvaluatedRules: [],
				explanation: `No policy rule matched action "${context.action}". Defaulting to deny (fail-safe).`,
				evaluatedAt: new Date().toISOString(),
				durationMs: Date.now() - startTime,
			};
		} else {
			// Return the highest-priority matching rule
			const matchedRule = sorted[0];
			const evaluatedRules = sorted.map((r) => ({
				rule: r,
				matched: r.id === matchedRule.id,
				reason:
					r.id === matchedRule.id
						? `Rule "${r.name}" (priority ${r.priority}) matched with decision "${r.decision}"`
						: `Lower priority rule (${r.priority}) superseded by higher priority rule`,
			}));

			result = {
				decision: matchedRule.decision,
				matchedRule,
				allEvaluatedRules: evaluatedRules,
				explanation: this.explainDecision(matchedRule, context),
				evaluatedAt: new Date().toISOString(),
				durationMs: Date.now() - startTime,
			};
		}

		// 6. Cache the result
		this.setCacheEntry(key, result);

		return result;
	}

	/**
	 * Evaluate a single action and log the decision to the audit ledger.
	 *
	 * @param context - The policy context describing the action
	 * @param auditLedger - The audit ledger instance
	 * @returns PolicyResult plus the generated audit entry
	 */
	async evaluateWithAudit(
		context: PolicyContext,
		auditLedger: { append(entry: AuditEntry): Promise<void> },
	): Promise<PolicyResult & { auditEntry: AuditEntry }> {
		const result = await this.evaluate(context);

		const auditEntry: AuditEntry = {
			id: randomUUID(),
			timestamp: result.evaluatedAt,
			actor: context.actor,
			action: context.action,
			decision: result.decision,
			policyRuleId: result.matchedRule?.id,
			policyRuleName: result.matchedRule?.name,
			proposalId: context.proposalId,
			planExecId: context.planExecId,
			memoryId: context.memoryId,
			evidence: [],
			result: result.decision === "allow" ? "success" : "blocked",
			durationMs: result.durationMs,
			context: {
				autonomyLevel: context.autonomyLevel,
				riskLevel: context.riskLevel,
			},
			metadata: context.metadata,
		};

		await auditLedger.append(auditEntry);

		return { ...result, auditEntry };
	}

	// -----------------------------------------------------------------------
	// Convenience Methods
	// -----------------------------------------------------------------------

	/**
	 * Check whether an action can be auto-executed without approval.
	 *
	 * Returns true only if the policy decision is "allow".
	 */
	async canAutoExecute(context: PolicyContext): Promise<boolean> {
		const result = await this.evaluate(context);
		return result.decision === "allow";
	}

	/**
	 * Check whether an action requires user approval.
	 *
	 * Returns true if the policy decision is "approval_required".
	 */
	async requiresApproval(context: PolicyContext): Promise<boolean> {
		const result = await this.evaluate(context);
		return result.decision === "approval_required";
	}

	/**
	 * Check whether an action is forbidden.
	 *
	 * Returns true if the policy decision is "forbidden".
	 */
	async isForbidden(context: PolicyContext): Promise<boolean> {
		const result = await this.evaluate(context);
		return result.decision === "forbidden";
	}

	// -----------------------------------------------------------------------
	// Explanation
	// -----------------------------------------------------------------------

	/**
	 * Generate a human-readable explanation for a policy result.
	 */
	explain(result: PolicyResult): string {
		if (result.matchedRule) {
			return `Policy rule "${result.matchedRule.name}" (id: ${result.matchedRule.id}, priority: ${result.matchedRule.priority}) evaluated action with decision: ${result.decision}. ${result.matchedRule.description}`;
		}
		return `No matching policy rule found. Default decision: ${result.decision}.`;
	}

	/**
	 * Generate a simple one-line explanation for a decision.
	 */
	explainSimple(decision: PolicyDecision, rule: PolicyRule | null): string {
		if (rule) {
			return `[${decision.toUpperCase()}] ${rule.name}: ${rule.description}`;
		}
		return `[${decision.toUpperCase()}] Default decision (no matching rule)`;
	}

	// -----------------------------------------------------------------------
	// Cache Management
	// -----------------------------------------------------------------------

	/**
	 * Clear all cached policy decisions.
	 */
	clearCache(): void {
		this.cache.clear();
	}

	/**
	 * Invalidate cached decisions for a specific action.
	 */
	invalidateForAction(action: string): void {
		for (const [key] of this.cache) {
			if (key.startsWith(`${action}::`)) {
				this.cache.delete(key);
			}
		}
	}

	// -----------------------------------------------------------------------
	// Private: Matching & Evaluation
	// -----------------------------------------------------------------------

	/**
	 * Filter rules to only those that match the given context.
	 *
	 * A rule matches if:
	 * 1. The action pattern (glob) matches the context action
	 * 2. All condition fields (autonomy level, risk level, etc.) match
	 */
	private findMatchingRules(rules: PolicyRule[], context: PolicyContext): PolicyRule[] {
		return rules.filter((rule) => {
			if (!rule.enabled) return false;
			return this.evaluateCondition(rule.condition, context);
		});
	}

	/**
	 * Evaluate a single policy condition against the action context.
	 *
	 * Checks:
	 * - Action name matches (glob pattern)
	 * - Action type matches (if specified)
	 * - Autonomy level is within range (if specified)
	 * - Risk level matches (if specified)
	 * - Affected area matches (if specified)
	 * - Context match conditions (if specified)
	 * - Time restrictions (if specified)
	 */
	private evaluateCondition(condition: PolicyCondition, context: PolicyContext): boolean {
		// 1. Action name match (supports glob patterns)
		if (!this.matchGlob(condition.action, context.action)) {
			return false;
		}

		// 2. Action type match
		if (condition.actionType !== undefined && condition.actionType !== context.actionType) {
			return false;
		}

		// 3. Autonomy level range
		if (condition.minAutonomyLevel !== undefined) {
			if (context.autonomyLevel < condition.minAutonomyLevel) {
				return false;
			}
		}
		if (condition.maxAutonomyLevel !== undefined) {
			if (context.autonomyLevel > condition.maxAutonomyLevel) {
				return false;
			}
		}

		// 4. Risk level match
		if (condition.riskLevel !== undefined) {
			if (context.riskLevel === undefined) {
				return false;
			}
			const allowedLevels = Array.isArray(condition.riskLevel) ? condition.riskLevel : [condition.riskLevel];
			if (!allowedLevels.includes(context.riskLevel)) {
				return false;
			}
		}

		// 5. Affected area match
		if (condition.affectedArea !== undefined) {
			if (context.affectedSystem !== condition.affectedArea) {
				return false;
			}
		}

		// 6. Context match conditions
		if (condition.contextMatch !== undefined) {
			for (const [key, value] of Object.entries(condition.contextMatch)) {
				const ctxVal = context.metadata[key];
				if (ctxVal !== value) {
					return false;
				}
			}
		}

		// 7. Time restrictions
		if (condition.timeRestriction !== undefined) {
			if (!this.evaluateTimeRestriction(condition.timeRestriction)) {
				return false;
			}
		}

		return true;
	}

	/**
	 * Match a glob pattern against a value.
	 *
	 * Supports:
	 * - Exact match: "memory_query" matches "memory_query"
	 * - Wildcard suffix: "memory_*" matches "memory_creation", "memory_query"
	 * - Wildcard prefix: "*_query" matches "memory_query", "plan_query"
	 * - Full wildcard: "*" matches everything
	 */
	private matchGlob(pattern: string, value: string): boolean {
		// Fast path: exact match
		if (pattern === value) return true;

		// Full wildcard
		if (pattern === "*") return true;

		// Convert glob pattern to regex
		const regexStr =
			"^" +
			pattern
				.replace(/[.+^${}()|[\]\\]/g, "\\$&") // escape special regex chars
				.replace(/\*/g, ".*") // wildcard → regex .*
				.replace(/\?/g, ".") + // single char wildcard → regex .
			"$";

		try {
			return new RegExp(regexStr).test(value);
		} catch {
			// Invalid pattern, fall back to exact match
			return pattern === value;
		}
	}

	/**
	 * Evaluate time-based restrictions on a rule.
	 *
	 * If the current time falls within the restricted window and
	 * the rule's timeRestriction specifies it, the rule matches.
	 *
	 * If no timeRestriction is set, the condition is always satisfied.
	 */
	private evaluateTimeRestriction(restriction: NonNullable<PolicyCondition["timeRestriction"]>): boolean {
		const now = new Date();
		const currentMinutes = now.getHours() * 60 + now.getMinutes();

		// Parse start/end as HH:mm
		const [startH, startM] = restriction.start.split(":").map(Number);
		const [endH, endM] = restriction.end.split(":").map(Number);

		if (Number.isNaN(startH) || Number.isNaN(startM) || Number.isNaN(endH) || Number.isNaN(endM)) {
			return false; // Invalid time format, skip
		}

		const startMinutes = startH * 60 + startM;
		const endMinutes = endH * 60 + endM;

		if (startMinutes <= endMinutes) {
			// Normal range (e.g., 09:00–17:00)
			return currentMinutes >= startMinutes && currentMinutes <= endMinutes;
		}
		// Overnight range (e.g., 22:00–06:00)
		return currentMinutes >= startMinutes || currentMinutes <= endMinutes;
	}

	/**
	 * Sort rules by priority descending (highest first).
	 */
	private sortByPriority(rules: PolicyRule[]): PolicyRule[] {
		return [...rules].sort((a, b) => b.priority - a.priority);
	}

	// -----------------------------------------------------------------------
	// Private: Defaults
	// -----------------------------------------------------------------------

	/**
	 * Get the default policy decision when no rule matches.
	 *
	 * Fail-safe: returns "deny" so that unmatched actions are blocked.
	 */
	private getDefaultDecision(): PolicyDecision {
		return "deny";
	}

	// -----------------------------------------------------------------------
	// Private: Explanation
	// -----------------------------------------------------------------------

	/**
	 * Generate a human-readable explanation for why a rule matched.
	 */
	private explainDecision(rule: PolicyRule, context: PolicyContext): string {
		const parts: string[] = [
			`Rule "${rule.name}" matched action "${context.action}" with decision "${rule.decision}".`,
		];

		if (rule.description) {
			parts.push(rule.description);
		}

		if (context.autonomyLevel !== undefined) {
			parts.push(`Autonomy level: ${context.autonomyLevel}.`);
		}

		if (context.riskLevel) {
			parts.push(`Risk level: ${context.riskLevel}.`);
		}

		return parts.join(" ");
	}

	// -----------------------------------------------------------------------
	// Private: Cache
	// -----------------------------------------------------------------------

	/**
	 * Generate a cache key from the context.
	 *
	 * The key includes: action, actionType, actor, autonomyLevel,
	 * riskLevel, and affectedSystem — but not transient fields like
	 * proposalId or metadata.
	 */
	private cacheKey(context: PolicyContext): string {
		const parts = [
			context.action,
			context.actionType ?? "",
			context.actor,
			String(context.autonomyLevel),
			context.riskLevel ?? "",
			context.affectedSystem ?? "",
		];
		return parts.join("::");
	}

	/**
	 * Store a result in the cache, evicting oldest entries if at capacity.
	 */
	private setCacheEntry(key: string, result: PolicyResult): void {
		// Evict oldest entries if at capacity
		if (this.cache.size >= this.config.maxCacheSize) {
			const oldestKey = this.cache.keys().next().value;
			if (oldestKey !== undefined) {
				this.cache.delete(oldestKey);
			}
		}

		this.cache.set(key, {
			result,
			cachedAt: Date.now(),
		});
	}
}

// ---------------------------------------------------------------------------
// Factory
// ---------------------------------------------------------------------------

/**
 * Create a PolicyEngine instance.
 *
 * @param ruleStore - Initialized RuleStore instance
 * @param config - Optional configuration overrides
 * @returns PolicyEngine instance
 */
export function createPolicyEngine(ruleStore: RuleStore, config?: Partial<PolicyEngineConfig>): PolicyEngine {
	return new PolicyEngine(ruleStore, config);
}

/**
 * Provenance Tracker — P18.F / Workspace 7.F
 *
 * Tracks decision provenance chains so every action can be explained
 * with its evidence lineage.
 *
 * Features:
 * - Directed provenance chain: decision -> policy evaluation -> evidence
 * - Links to proposal, memory, observation, and policy rule refs
 * - Human-readable explanation generation via chain traversal
 * - JSON-file-based persistence to `.pi/brain/audit/provenance/`
 * - Stats for monitoring
 *
 * File Structure:
 *   .pi/brain/audit/provenance/
 *   └── records.json           # All provenance records as JSON object
 */

import { existsSync } from "fs";
import { mkdir, readFile, writeFile } from "fs/promises";
import { join, resolve } from "path";
import type {
	AuditEntry,
	ProvenanceLink,
	ProvenanceRecord,
	ProvenanceTargetType,
} from "../policy/types.js";

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------

const DEFAULT_PERSISTENCE_DIR = ".pi/brain/audit/provenance";
const RECORDS_FILE = "records.json";

// ---------------------------------------------------------------------------
// ProvenanceTracker
// ---------------------------------------------------------------------------

/**
 * Tracks and explains decision provenance chains.
 *
 * Every policy evaluation can create a provenance record linking the
 * decision to its input context (proposals, memories, observations,
 * and policy rules). The chain can be traversed to generate
 * human-readable explanations.
 */
export class ProvenanceTracker {
	private readonly persistencePath: string;
	private records: Map<string, ProvenanceRecord> = new Map();
	private persistenceReady: boolean = false;

	constructor(options?: { persistencePath?: string }) {
		this.persistencePath = options?.persistencePath ?? DEFAULT_PERSISTENCE_DIR;
	}

	// -----------------------------------------------------------------------
	// Init / Teardown
	// -----------------------------------------------------------------------

	/**
	 * Ensure the persistence directory exists and load existing records.
	 * Safe to call multiple times.
	 */
	async init(): Promise<void> {
		if (this.persistenceReady) return;
		await mkdir(resolve(this.persistencePath), { recursive: true });
		await this.load();
		this.persistenceReady = true;
	}

	// -----------------------------------------------------------------------
	// Track
	// -----------------------------------------------------------------------

	/**
	 * Create a new provenance record for a target.
	 *
	 * @param targetId - The ID of the target (proposal, plan, memory, decision, approval)
	 * @param targetType - The type of the target
	 * @param links - Initial provenance links
	 * @returns The new ProvenanceRecord
	 */
	async track(
		targetId: string,
		targetType: ProvenanceTargetType,
		links: ProvenanceLink[],
	): Promise<ProvenanceRecord> {
		await this.init();

		const now = new Date().toISOString();
		const record: ProvenanceRecord = {
			id: this.generateId(),
			targetId,
			targetType,
			links: links.map((l) => ({
				...l,
				timestamp: l.timestamp || now,
			})),
			createdAt: now,
			updatedAt: now,
		};

		this.records.set(targetId, record);
		await this.save();
		return record;
	}

	/**
	 * Add a link to an existing provenance record.
	 *
	 * @param targetId - The target ID to add the link to
	 * @param link - The provenance link to add
	 * @returns The updated ProvenanceRecord
	 * @throws If no record exists for the target ID
	 */
	async addLink(targetId: string, link: ProvenanceLink): Promise<ProvenanceRecord> {
		await this.init();

		const existing = this.records.get(targetId);
		if (!existing) {
			// Auto-create a record if none exists (lazy creation)
			return this.track(targetId, "decision", [link]);
		}

		const now = new Date().toISOString();
		existing.links.push({
			...link,
			timestamp: link.timestamp || now,
		});
		existing.updatedAt = now;

		this.records.set(targetId, existing);
		await this.save();
		return existing;
	}

	// -----------------------------------------------------------------------
	// Query
	// -----------------------------------------------------------------------

	/**
	 * Get the provenance record for a specific target ID.
	 *
	 * @param targetId - The target ID to look up
	 * @returns The provenance record, or null if not found
	 */
	async getProvenance(targetId: string): Promise<ProvenanceRecord | null> {
		await this.init();
		return this.records.get(targetId) ?? null;
	}

	/**
	 * Get the full provenance chain for a target ID, traversing
	 * linked records recursively.
	 *
	 * @param targetId - The starting target ID
	 * @returns Array of ProvenanceLinks from the chain traversal
	 */
	async getChain(targetId: string): Promise<ProvenanceLink[]> {
		await this.init();
		return this.buildExplanationChain(targetId, new Set(), 0).map(
			(line) =>
				({
					sourceId: targetId,
					sourceType: "decision" as ProvenanceTargetType,
					relationship: "derived_from" as const,
					timestamp: new Date().toISOString(),
					summary: line,
					metadata: {},
				}) as ProvenanceLink,
		);
	}

	// -----------------------------------------------------------------------
	// Explanation
	// -----------------------------------------------------------------------

	/**
	 * Generate a human-readable explanation of a decision from its audit entry.
	 *
	 * @param decisionAuditEntry - The audit entry for the decision
	 * @returns A human-readable explanation string
	 */
	async explainDecision(decisionAuditEntry: AuditEntry): Promise<string> {
		await this.init();

		const lines: string[] = [];
		const decision = decisionAuditEntry.decision;
		const action = decisionAuditEntry.action;
		const actor = decisionAuditEntry.actor;

		lines.push(`Decision: ${decision.toUpperCase()} — "${action}" by ${actor}`);
		lines.push(`When: ${decisionAuditEntry.timestamp}`);

		if (decisionAuditEntry.policyRuleId) {
			const ruleRef = decisionAuditEntry.policyRuleName
				? `${decisionAuditEntry.policyRuleName} (${decisionAuditEntry.policyRuleId})`
				: decisionAuditEntry.policyRuleId;
			lines.push(`Matched Rule: ${ruleRef}`);
		}

		if (decisionAuditEntry.proposalId) {
			lines.push(`Proposal: ${decisionAuditEntry.proposalId}`);
		}

		if (decisionAuditEntry.planExecId) {
			lines.push(`Plan Execution: ${decisionAuditEntry.planExecId}`);
		}

		if (decisionAuditEntry.memoryId) {
			lines.push(`Memory: ${decisionAuditEntry.memoryId}`);
		}

		if (decisionAuditEntry.evidence && decisionAuditEntry.evidence.length > 0) {
			lines.push("Evidence:");
			for (const ev of decisionAuditEntry.evidence) {
				lines.push(`  - ${ev.type}: ${ev.id}${ev.description ? ` — ${ev.description}` : ""}`);
			}
		}

		// Include context
		const ctx = decisionAuditEntry.context;
		lines.push(`Autonomy Level: ${ctx.autonomyLevel}`);
		if (ctx.riskLevel) {
			lines.push(`Risk Level: ${ctx.riskLevel}`);
		}

		// Chain traversal from provenance records
		const record = this.records.get(decisionAuditEntry.id);
		if (record && record.links.length > 0) {
			lines.push("");
			lines.push("Provenance Chain:");
			const chainLines = this.buildExplanationChain(decisionAuditEntry.id, new Set(), 0);
			lines.push(...chainLines);
		}

		return lines.join("\n");
	}

	/**
	 * Generate a human-readable explanation of a proposal's provenance.
	 *
	 * @param proposalId - The proposal ID to explain
	 * @returns A human-readable explanation string
	 */
	async explainProposal(proposalId: string): Promise<string> {
		await this.init();

		const record = this.records.get(proposalId);
		if (!record) {
			return `No provenance record found for proposal: ${proposalId}`;
		}

		const lines: string[] = [];
		lines.push(`Provenance for Proposal: ${proposalId}`);
		lines.push(`Created: ${record.createdAt}`);
		lines.push(`Last Updated: ${record.updatedAt}`);
		lines.push(`Links: ${record.links.length}`);

		if (record.links.length > 0) {
			lines.push("");
			lines.push("Chain:");
			const chainLines = this.buildExplanationChain(proposalId, new Set(), 0);
			lines.push(...chainLines);
		}

		return lines.join("\n");
	}

	/**
	 * Generate a human-readable explanation of a memory's provenance.
	 *
	 * @param memoryId - The memory ID to explain
	 * @returns A human-readable explanation string
	 */
	async explainMemory(memoryId: string): Promise<string> {
		await this.init();

		const record = this.records.get(memoryId);
		if (!record) {
			return `No provenance record found for memory: ${memoryId}`;
		}

		const lines: string[] = [];
		lines.push(`Provenance for Memory: ${memoryId}`);
		lines.push(`Created: ${record.createdAt}`);
		lines.push(`Last Updated: ${record.updatedAt}`);
		lines.push(`Links: ${record.links.length}`);

		if (record.links.length > 0) {
			lines.push("");
			lines.push("Chain:");
			const chainLines = this.buildExplanationChain(memoryId, new Set(), 0);
			lines.push(...chainLines);
		}

		return lines.join("\n");
	}

	// -----------------------------------------------------------------------
	// Internal: Chain Building
	// -----------------------------------------------------------------------

	/**
	 * Recursively build explanation lines for a provenance chain.
	 *
	 * Tracks visited nodes to prevent infinite loops from circular links.
	 *
	 * @param targetId - The current target ID to explain
	 * @param visited - Set of already-visited target IDs
	 * @param depth - Current recursion depth (for indentation)
	 * @returns Array of explanation lines
	 */
	private buildExplanationChain(
		targetId: string,
		visited: Set<string>,
		depth: number,
	): string[] {
		if (visited.has(targetId)) {
			return [`${"  ".repeat(depth)}[circular reference: ${targetId}]`];
		}

		const record = this.records.get(targetId);
		if (!record) {
			return [`${"  ".repeat(depth)}No provenance record for: ${targetId}`];
		}

		visited.add(targetId);
		const lines: string[] = [];

		for (const link of record.links) {
			const indent = "  ".repeat(depth);
			const arrow = this.relationshipArrow(link.relationship);
			lines.push(
				`${indent}${link.sourceId} (${link.sourceType}) ${arrow} ${targetId} (${record.targetType})`,
			);
			if (link.summary) {
				lines.push(`${indent}  Summary: ${link.summary}`);
			}

			// Recurse into linked sources
			if (link.sourceId !== targetId) {
				const subChain = this.buildExplanationChain(link.sourceId, visited, depth + 1);
				lines.push(...subChain);
			}
		}

		visited.delete(targetId);
		return lines;
	}

	/**
	 * Get a human-readable arrow symbol for a relationship type.
	 */
	private relationshipArrow(relationship: string): string {
		switch (relationship) {
			case "derived_from":
				return "<-- derived from --";
			case "supported_by":
				return "<-- supported by --";
			case "triggered_by":
				return "<-- triggered by --";
			case "corrected_by":
				return "<-- corrected by --";
			case "evaluated_by":
				return "<-- evaluated by --";
			case "resulted_in":
				return "-- resulted in -->";
			default:
				return "<--";
		}
	}

	// -----------------------------------------------------------------------
	// Persistence
	// -----------------------------------------------------------------------

	/**
	 * Save all provenance records to disk.
	 *
	 * Writes to a single JSON file that is atomically replaced.
	 */
	async save(): Promise<void> {
		const filePath = this.getFilePath();
		await mkdir(resolve(this.persistencePath), { recursive: true });

		const data = {
			version: 1,
			updatedAt: new Date().toISOString(),
			records: Object.fromEntries(this.records),
		};

		// Atomic write: write to temp file then rename
		const tempPath = `${filePath}.tmp`;
		await writeFile(tempPath, JSON.stringify(data, null, 2), "utf-8");

		const { rename } = await import("fs/promises");
		await rename(tempPath, filePath);
	}

	/**
	 * Load provenance records from disk.
	 *
	 * If the file does not exist yet, this is a no-op.
	 * If the file is corrupted, it is skipped and an error is logged.
	 */
	async load(): Promise<void> {
		const filePath = this.getFilePath();
		if (!existsSync(filePath)) {
			return;
		}

		try {
			const content = await readFile(filePath, "utf-8");
			const data = JSON.parse(content);

			if (!data.records || typeof data.records !== "object") {
				console.error("[ProvenanceTracker] Invalid records file: missing records object");
				return;
			}

			const loaded = new Map<string, ProvenanceRecord>();
			for (const [key, value] of Object.entries(data.records)) {
				const record = value as ProvenanceRecord;
				if (!record.id || !record.targetId || !record.targetType) {
					console.error(`[ProvenanceTracker] Skipping malformed record: ${key}`);
					continue;
				}
				loaded.set(key, record);
			}

			this.records = loaded;
		} catch (err) {
			console.error(`[ProvenanceTracker] Failed to load records: ${err}`);
		}
	}

	/**
	 * Get the full file path for the records file.
	 */
	private getFilePath(): string {
		return resolve(this.persistencePath, RECORDS_FILE);
	}

	// -----------------------------------------------------------------------
	// Stats
	// -----------------------------------------------------------------------

	/**
	 * Get statistics about stored provenance records.
	 *
	 * @returns Stats object
	 */
	async getStats(): Promise<{
		totalRecords: number;
		totalLinks: number;
		byType: Record<ProvenanceTargetType, number>;
	}> {
		await this.init();

		const byType: Record<string, number> = {};
		let totalLinks = 0;

		for (const record of this.records.values()) {
			byType[record.targetType] = (byType[record.targetType] ?? 0) + 1;
			totalLinks += record.links.length;
		}

		return {
			totalRecords: this.records.size,
			totalLinks,
			byType: byType as Record<ProvenanceTargetType, number>,
		};
	}

	/**
	 * Get all records currently held (for testing/debugging).
	 */
	getAllRecords(): Map<string, ProvenanceRecord> {
		return new Map(this.records);
	}

	/**
	 * Clear all records in memory (does not persist).
	 */
	clearInMemory(): void {
		this.records.clear();
		this.persistenceReady = false;
	}

	// -----------------------------------------------------------------------
	// Internal: ID Generation
	// -----------------------------------------------------------------------

	private idCounter = 0;

	/**
	 * Generate a simple unique ID for provenance records.
	 */
	private generateId(): string {
		this.idCounter++;
		const now = Date.now().toString(36);
		const counter = this.idCounter.toString(36).padStart(6, "0");
		const rand = Math.random().toString(36).slice(2, 6);
		return `prov-${now}-${counter}-${rand}`;
	}
}

